n32931.content:
\begin{theorem}[Measurability of the cocycle iterates]\label{measurable_cocycle}
  \lean{ErgodicTheory.measurable_cocycle}\leanok
  If \(A\) and \(T\) are measurable then for each \(n\) the iterate
  \(x \mapsto A^{(n)}(x)\) is measurable for the entrywise structure
  \ref{instMeasurableSpaceMatrix}.
\end{theorem}

n32934.content:
\begin{theorem}[Measurability of the L2 operator norm]\label{measurable_l2_opNorm}
  \lean{ErgodicTheory.measurable_l2_opNorm}\leanok
  The map \(M \mapsto \left\lVert M \right\rVert\) on \(\operatorname{Matrix}(\operatorname{Fin}d)(\operatorname{Fin}d)\,\mathbb{R}\) is measurable.
\end{theorem}

n32935.content:
\begin{proof}\leanok
  \uses{instOpensMeasurableSpaceMatrix, instMeasurableSpaceMatrix}
  The norm is continuous for the operator-norm topology, and by
  \ref{instOpensMeasurableSpaceMatrix} that topology's Borel structure is the entrywise
  Pi structure; continuous maps into a Borel codomain are measurable.
\end{proof}

n32936.content:
\begin{theorem}[Measurability of the determinant]\label{measurable_det}
  \lean{ErgodicTheory.measurable_det}\leanok
  The determinant \(M \mapsto \det M\) is measurable.
\end{theorem}

n32937.content:
\begin{proof}\leanok
  \uses{instMeasurableSpaceMatrix}
  By the Leibniz formula \(\det M = \sum_{\sigma}\operatorname{sgn}(\sigma)\prod_i M_{i,\sigma(i)}\),
  the determinant is a finite sum of finite products of measurable coordinate
  projections, hence measurable.
\end{proof}

n32938.content:
\begin{theorem}[Measurability of the matrix inverse]\label{measurable_inv_matrix}
  \lean{ErgodicTheory.measurable_inv_matrix}\leanok
  The inverse \(M \mapsto M^{-1}\) is measurable on the entrywise structure.
\end{theorem}

n32940.content:
\begin{lemma}[Invertibility of the iterates]\label{det_cocycle_ne_zero}
  \lean{ErgodicTheory.det_cocycle_ne_zero}\leanok
  If \(\det A(x) \neq 0\) for every \(x\), then \(\det A^{(n)}(x) \neq 0\) for all
  \(n, x\).
\end{lemma}

n32941.content:
\begin{proof}\leanok
  \uses{cocycle}
  Induction on \(n\). The base case is \(\det 1 = 1\). For the step,
  \(\det(A^{(n)}(Tx)\cdot A(x)) = \det A^{(n)}(Tx)\cdot \det A(x)\), and both factors are
  nonzero by the inductive hypothesis and the assumption on \(A\).
\end{proof}

n32942.content:
\begin{lemma}[The unit matrix has norm one]\label{norm_one_matrix}
  \lean{ErgodicTheory.norm_one_matrix}\leanok
  When \(d \neq 0\), \(\left\lVert (1 : \operatorname{Matrix}(\operatorname{Fin}d)(\operatorname{Fin}d)\,\mathbb{R}) \right\rVert = 1\) for the L2 operator
  norm.
\end{lemma}

n32945.content:
\begin{proof}\leanok
  \uses{det_cocycle_ne_zero}
  If \(\left\lVert A^{(n)}(x) \right\rVert = 0\) then \(A^{(n)}(x)\) is the zero matrix, whose determinant
  vanishes (as \(d \neq 0\)), contradicting \ref{det_cocycle_ne_zero}. The inverse case is
  identical using \(\det\bigl((A^{(n)}(x))^{-1}\bigr) = (\det A^{(n)}(x))^{-1} \neq 0\).
\end{proof}

n32947.content:
\begin{proof}\leanok
  \uses{cocycle_add, norm_cocycle_pos}
  Rewrite \(m+n\) as \(n+m\) and apply the cocycle identity \ref{cocycle_add} to get
  \(A^{(m+n)}(x) = A^{(n)}(T^{m}x)\cdot A^{(m)}(x)\). Submultiplicativity of the operator
  norm and monotonicity of \(\log\) give
  \(\log\left\lVert A^{(m+n)}(x) \right\rVert \le \log\bigl(\left\lVert A^{(n)}(T^{m}x) \right\rVert\cdot\left\lVert A^{(m)}(x) \right\rVert\bigr)\);
  both factors are strictly positive by \ref{norm_cocycle_pos}, so \(\log\) of the product
  splits as the sum \(\log\left\lVert A^{(n)}(T^{m}x) \right\rVert + \log\left\lVert A^{(m)}(x) \right\rVert\), which is the
  required bound after commuting the summands.
\end{proof}

n32948.content:
\begin{theorem}[Subadditivity of the inverse log-norm cocycle]\label{isSubadditiveCocycle_logNorm_inv}
  \lean{ErgodicTheory.isSubadditiveCocycle_logNorm_inv}\leanok
  Under the same hypotheses, \(g_n(x) = \log\left\lVert (A^{(n)}(x))^{-1} \right\rVert\) is a subadditive
  cocycle over \(T\).
\end{theorem}

n32956.content:
\begin{lemma}[Integral of a Birkhoff sum]\label{integral_birkhoffSum}
  \lean{ErgodicTheory.integral_birkhoffSum}\leanok
  For measure-preserving \(T\) and integrable \(f\),
  \(\int \sum_{k<n} f(T^{k}x)\,d\mu = n\int f\,d\mu\).
\end{lemma}

n32965.content:
\begin{lemma}[Nonnegativity of the maximal function]\label{maxBirkhoff_nonneg}
  \lean{ErgodicTheory.maxBirkhoff_nonneg}\leanok
  For all \(g, N, x\) one has \(0 \le \texttt{maxBirkhoff}\,T\,g\,N\,x\).
\end{lemma}

n32975.content:
\begin{lemma}[Level sets exhaust the target set]\label{iUnion_setOf_maxBirkhoff_pos}
  \lean{ErgodicTheory.iUnion_setOf_maxBirkhoff_pos}\leanok
  The level sets \(\{x : 0 < \texttt{maxBirkhoff}\,T\,g\,N\,x\}\) are monotone
  in \(N\), and their union over all \(N\) is exactly
  \(\{x : \exists n,\ 0 < \texttt{birkhoffSum}\,T\,g\,(n+1)\,x\}\).
\end{lemma}

n32977.content:
\begin{theorem}[Maximal ergodic inequality (Hopf--Garsia)]\label{setIntegral_birkhoffSum_pos_nonneg}
  \lean{ErgodicTheory.setIntegral_birkhoffSum_pos_nonneg}\leanok
  For a measure-preserving \(T\) and an integrable \(f : X \to \mathbb{R}\),
  \[
    0 \le \int_{\{x \,:\, \exists n,\ 0 < \texttt{birkhoffSum}\,T\,f\,(n+1)\,x\}}
      f \, d\mu.
  \]
\end{theorem}

n32981.content:
\begin{lemma}[Subexponential orbital tail]\label{ae_tendsto_orbit_div_atTop_zero}
  \lean{ErgodicTheory.ae_tendsto_orbit_div_atTop_zero}\leanok
  For a measure-preserving \(T\) and integrable \(g\), the orbital tail
  \(n^{-1}\, g(T^{[n]}x)\) tends to \(0\) for \(\mu\)-a.e.\ \(x\).
\end{lemma}

n32983.content:
\begin{lemma}[A.e.\ boundedness of Birkhoff averages]\label{ae_bddAbove_birkhoffAverage}
  \lean{ErgodicTheory.ae_bddAbove_birkhoffAverage}\leanok
  For a finite measure, a measure-preserving \(T\) and integrable \(g\), the
  Birkhoff averages \(n \mapsto \texttt{birkhoffAverage}\,\mathbb{R}\,T\,g\,(n+1)\,x\)
  are a.e.\ bounded above (and, applied to \(-g\), a.e.\ bounded below).
\end{lemma}

n32985.content:
\begin{lemma}[Limsup invariance and vanishing perturbations]\label{limsup_birkhoffAverage_comp_ae}
  \leanok
  The pointwise limsup \(x \mapsto \limsup_n
  \texttt{birkhoffAverage}\,\mathbb{R}\,T\,g\,n\,x\) is a.e.\ \(T\)-invariant.
\end{lemma}

n32987.content:
\begin{proposition}[The core maximal-inequality step]\label{measure_setOf_lt_limsup_eq_zero}
  \lean{ErgodicTheory.measure_setOf_lt_limsup_eq_zero}\leanok
  For a finite measure, measure-preserving \(T\), integrable \(g\) and
  \(\varepsilon > 0\), the superlevel set where the limsup of the Birkhoff
  averages exceeds \(\mu[g\mid\mathcal I] + \varepsilon\) is null.
\end{proposition}

n32991.content:
\begin{corollary}[Ergodic case of Birkhoff]\label{tendsto_birkhoffAverage_ae_integral}
  \lean{ErgodicTheory.tendsto_birkhoffAverage_ae_integral}\leanok
  For an ergodic \(T\) on a probability space and integrable \(g\), the Birkhoff
  averages converge \(\mu\)-a.e.\ to the space average \(\int g\, d\mu\).
\end{corollary}

n32997.content:
\begin{lemma}[Fekete limit of the normalized integrals]\label{exists_fekete}
  \lean{ErgodicTheory.Kingman.exists_fekete}\leanok
  For a measure-preserving \(T\), an integrable subadditive cocycle \(g\) whose
  normalized integrals are bounded below, the sequence
  \((\int g\,(n+1)\,d\mu)/(n+1)\) converges to the Fekete constant \(\gamma\).
\end{lemma}

n32999.content:
\begin{lemma}[Invariance from a one-sided orbital bound]\label{ae_eq_comp_of_le_comp}
  \lean{ErgodicTheory.Kingman.ae_eq_comp_of_le_comp}\leanok
  For a finite measure, measure-preserving \(T\) and an a.e.\ measurable \(F\)
  with \(F\,x \le F\,(Tx)\) for a.e.\ \(x\), one has \(F \circ T =^{\text{a.e.}}
  F\).
\end{lemma}

n33003.content:
\begin{lemma}[Integrability of the limsup envelope]\label{int_limsup_div_integrable}
  \lean{ErgodicTheory.Kingman.int_limsup_div_integrable}\leanok
  Under the same hypotheses, the limsup envelope \(f_+\) is integrable.
\end{lemma}

n33005.content:
\begin{proposition}[Hard direction: \(\limsup \le \liminf\) a.e.]\label{ae_ereal_limsup_le_liminf}
  \lean{ErgodicTheory.Kingman.ae_ereal_liminf_eq_limsup}\leanok
  Under the same hypotheses, for a.e.\ \(x\) the \texttt{EReal} limsup of the
  normalized cocycle is dominated by its liminf.
\end{proposition}

n33011.content:
\begin{corollary}[Kingman, ergodic case]\label{tendsto_kingman_ergodic}
  \lean{ErgodicTheory.tendsto_kingman_ergodic}\leanok
  For an ergodic \(T\) on a probability space, an integrable subadditive cocycle
  with normalized integrals bounded below, there is a constant \(c\) with
  \(n^{-1}\,g\,n\,x \to c\) for \(\mu\)-a.e.\ \(x\).
\end{corollary}

n33020.content:
\begin{lemma}[Finiteness of the value set]\label{finite_range}
  \lean{ErgodicTheory.IsUltrametricGrowth.finite_range}\leanok
  If $E$ is finite-dimensional and $g$ is an ultrametric growth function, then
  $\{g(v) : v\neq 0\}$ is finite, with at most $\dim_{\mathbb{R}} E$ elements.
  \begin{proof}\leanok
  \uses{linearIndependent_of_injOn}
  If the value set were infinite, pick $\dim_{\mathbb{R}} E + 1$ distinct values and
  witnessing nonzero vectors. By \ref{linearIndependent_of_injOn} these are
  linearly independent, exceeding $\dim_{\mathbb{R}} E$, a contradiction.
  \end{proof}
\end{lemma}

n33021.content:
\begin{proof}\leanok
  \uses{linearIndependent_of_injOn}
  If the value set were infinite, pick $\dim_{\mathbb{R}} E + 1$ distinct values and
  witnessing nonzero vectors. By \ref{linearIndependent_of_injOn} these are
  linearly independent, exceeding $\dim_{\mathbb{R}} E$, a contradiction.
  \end{proof}

n33022.content:
\begin{definition}[Sublevel submodule]\label{sublevel}
  \lean{ErgodicTheory.IsUltrametricGrowth.sublevel}\leanok
  \uses{IsUltrametricGrowth}
  For an ultrametric growth function $g$ and threshold $t\in\mathbb{R}$, the
  \emph{sublevel set}
  \[ \mathrm{sublevel}(g,t) = \{\, v \mid v=0 \ \lor\ g(v)\le t \,\} \]
  is a submodule of $E$: it contains $0$; closure under addition is the
  non-Archimedean inequality together with $\max(g v,g w)\le t$; closure under
  scaling is scaling-invariance. These submodules are monotone in $t$
  (\texttt{sublevel\_mono}).
\end{definition}

n33024.content:
\begin{definition}[Upper Lyapunov growth function]\label{lambdaBar}
  \lean{ErgodicTheory.lambdaBar}\leanok
  \uses{growthSeq}
  The \emph{upper Lyapunov growth function} is the $\limsup$ of the growth
  sequence,
  \[ \bar\lambda(v) \;=\; \mathrm{lambdaBar}(A,T,x,v)
     \;=\; \limsup_{n\to\infty}\ \frac1n\,\log\left\lVert A^{(n)}(x)\cdot v \right\rVert. \]
\end{definition}

n33025.content:
\begin{lemma}[Scaling invariance]\label{lambdaBar_smul}
  \lean{ErgodicTheory.lambdaBar_smul}\leanok
  For $c\neq 0$ and $v\neq 0$, $\bar\lambda(c\cdot v)=\bar\lambda(v)$.
  \begin{proof}\leanok
  \uses{lambdaBar, growthSeq}
  By linearity $\left\lVert A^{(n)}(x)(c\cdot v) \right\rVert=\left\lvert c \right\rvert\,\left\lVert A^{(n)}(x)v \right\rVert$, so the
  two growth sequences differ by $\tfrac1n\log\left\lvert c \right\rvert$, which $\to 0$. A
  $\limsup$ is unchanged under a perturbation tending to zero (a robust helper
  proved directly on the defining sets $\{a:\forall^{\infty} n,\ u_n\le a\}$, with
  no boundedness hypothesis). The bound is unconditional.
  \end{proof}
\end{lemma}

n33031.content:
\begin{theorem}[$\bar\lambda$ is an ultrametric growth function, a.e.]\label{isUltrametricGrowth_lambdaBar}
  \lean{ErgodicTheory.isUltrametricGrowth_lambdaBar}\leanok
  Under the hypotheses of \ref{lambdaBar_mem_Icc}, for a.e.\ $x$ the function
  $v\mapsto\bar\lambda(v)$ is an ultrametric growth function.
  \begin{proof}\leanok
  \uses{IsUltrametricGrowth, lambdaBar_smul, lambdaBar_add_le, lambdaBar_mem_Icc}
  Scaling-invariance is \ref{lambdaBar_smul} (trivial on $v=0$). The
  non-Archimedean axiom is \ref{lambdaBar_add_le}, whose boundedness hypotheses
  are discharged on the full-measure Furstenberg--Kesten convergence set, where
  the growth sequence of every nonzero vector is bounded above and below by the
  two FK sandwich sequences.
  \end{proof}
\end{theorem}

n33035.content:
\begin{definition}[Lyapunov spectrum]\label{lyapunovSpectrum}
  \lean{ErgodicTheory.lyapunovSpectrum}\leanok
  \uses{lambdaBar, finite_range}
  The \emph{Lyapunov spectrum} at $x$ is the finite set of realized values
  \[ \mathrm{lyapunovSpectrum}(A,T,x)
     = \{\,\bar\lambda_x(v) : v\neq 0\,\}, \]
  defined as a \texttt{Finset} via \ref{finite_range} on the good set where
  $\bar\lambda_x$ is an ultrametric growth function, and as $\emptyset$ off it.
  A value lies in it iff it is realized by some nonzero vector.
\end{definition}

n33036.content:
\begin{definition}[Multiplicity count and descending list]\label{specList}
  \lean{ErgodicTheory.specList}\leanok
  \uses{lyapunovSpectrum}
  Write $k=\mathrm{specCard}(A,T,x)$ for the number of distinct exponents (the
  cardinality of the spectrum). The \emph{exponent list}
  $\mathrm{specList}\colon \mathrm{Fin}\,k\to\mathbb{R}$ enumerates the spectrum in
  \emph{strictly descending} order, $\lambda_0>\lambda_1>\cdots>\lambda_{k-1}$,
  obtained from the order embedding of the finset composed with index reversal.
  It is strictly antitone, every $\mathrm{specList}(i)$ lies in the spectrum, and
  every spectrum value is $\mathrm{specList}(i)$ for a unique $i$.
\end{definition}

n33037.content:
\begin{definition}[Sublevel subspace]\label{lambdaSublevel}
  \lean{ErgodicTheory.lambdaSublevel}\leanok
  \uses{lambdaBar, sublevel}
  The \emph{sublevel subspace} at threshold $t$,
  \[ \mathrm{lambdaSublevel}(A,T,x,t)
     = \{\, v \mid v=0 \ \lor\ \bar\lambda_x(v)\le t \,\}, \]
  is the submodule \ref{sublevel} of $\bar\lambda_x$ at $t$ on the good set, and
  $\bot$ off it.
\end{definition}

n33038.content:
\begin{definition}[Oseledets filtration / limsup flag]\label{vflag}
  \lean{ErgodicTheory.vflag}\leanok
  \uses{lambdaSublevel, specList}
  The \emph{limsup flag} at $x$ is the family
  $\mathrm{vflag}(A,T,x)\colon\mathrm{Fin}\,(k+1)\to\mathrm{Submodule}$ with
  \[ \mathrm{vflag}(A,T,x)(j)
     = \begin{cases}
        \mathrm{lambdaSublevel}\bigl(A,T,x,\ \mathrm{specList}(j)\bigr) & j<k,\\
        \bot & j=k.
       \end{cases} \]
  With the descending enumeration, level $j$ is the sublevel set at $\lambda_j$,
  so the flag decreases from the whole space down to $\bot$.
\end{definition}

n33039.content:
\begin{lemma}[Extremal levels]\label{vflag_zero}
  \lean{ErgodicTheory.vflag_zero}\leanok
  On the good set, $\mathrm{vflag}(A,T,x)(0)=\top$; and unconditionally
  $\mathrm{vflag}(A,T,x)(\mathrm{last})=\bot$ (\texttt{vflag\_last}).
  \begin{proof}\leanok
  \uses{vflag, lyapunovSpectrum, specList}
  For any $v\neq 0$, $\bar\lambda_x(v)$ lies in the spectrum, so $k>0$ and
  $\mathrm{specList}(0)$ is the maximum of the spectrum; thus
  $\bar\lambda_x(v)\le\mathrm{specList}(0)$ and $v$ lies in level $0$. Level $k$
  is $\bot$ by definition.
  \end{proof}
\end{lemma}

n33043.content:
\begin{lemma}[Stratum exactness]\label{lambdaBar_eq_on_stratum}
  \lean{ErgodicTheory.lambdaBar_eq_on_stratum}\leanok
  On the good set, if $v\in\mathrm{vflag}(A,T,x)(i)$ but
  $v\notin\mathrm{vflag}(A,T,x)(i{+}1)$, then $\bar\lambda_x(v)=\mathrm{specList}(i)=\lambda_i$.
  \begin{proof}\leanok
  \uses{vflag, specList, lyapunovSpectrum}
  Membership in level $i$ gives $\bar\lambda_x(v)\le\lambda_i$. Since
  $\bar\lambda_x(v)$ is a spectrum value, $\bar\lambda_x(v)=\lambda_j$ for some
  $j\ge i$. Non-membership in level $i{+}1$ rules out $\bar\lambda_x(v)\le
  \lambda_{i+1}$, forcing $j\le i$. Hence $j=i$ by injectivity of the strictly
  antitone list.
  \end{proof}
\end{lemma}

n33048.content:
\begin{definition}[Measurable family of subspaces]\label{MeasurableSubspace}
  \lean{ErgodicTheory.MeasurableSubspace}\leanok
  \uses{orthProjMatrix}
  A subspace-valued map $V\colon X\to\mathrm{Submodule}\,\mathbb{R}\,\mathbb{R}^d$ is a
  \emph{measurable family of subspaces} when $x\mapsto\mathrm{orthProjMatrix}(V x)$
  is measurable. Equivalently (\texttt{measurable\_orthProjMatrix\_iff}), for each
  standard basis index $j$ the $\mathbb{R}^d$-valued map
  $x\mapsto (V x).\mathtt{starProjection}(e_j)$ is measurable.
\end{definition}

n33049.content:
\begin{lemma}[Scalar growth is measurable]\label{measurable_lambdaBar_apply}
  \lean{ErgodicTheory.measurable_lambdaBar_apply}\leanok
  For fixed $v$, the map $x\mapsto\bar\lambda_x(v)$ is measurable.
  \begin{proof}\leanok
  \uses{lambdaBar}
  It is the $\limsup$ of the sequence
  $x\mapsto\tfrac1n\log\left\lVert A^{(n)}(x)\cdot v \right\rVert$. Each term is measurable:
  $x\mapsto A^{(n)}(x)$ is measurable (measurability of the cocycle), and
  $M\mapsto\left\lVert M\cdot v \right\rVert$ is continuous (a fixed-vector linear map of $M$,
  on a finite-dimensional space, post-composed with the norm), so the composite
  with $\log$ is measurable, and a $\limsup$ of measurable functions is measurable.
  \end{proof}
\end{lemma}

n33051.content:
\begin{lemma}[Polynomial in a measurable matrix]\label{measurable_aeval_matrix}
  \lean{ErgodicTheory.measurable_aeval_matrix}\leanok
  For a fixed real polynomial $q$, the map $a\mapsto q(a)$ on
  $\mathrm{Mat}_{d\times d}(\mathbb{R})$ is measurable.
  \begin{proof}\leanok
  Induction on $q$ over the constant/sum/monomial generators, using that matrix
  addition and multiplication are measurable in each argument
  (\texttt{instMeasurableAdd₂Matrix} and the matrix \texttt{MeasurableMul₂}
  instance), whence $a\mapsto a^n$ is measurable (\texttt{measurable\_matrix\_pow}).
  \end{proof}
\end{lemma}

