n33084.content:
\begin{lemma}[Slow-volume exponent squeeze (superseded route)]\label{limsup_topSlow_le_of_squeeze}
  \emph{This lemma belonged to a superseded determinant/volume-squeeze route and has no counterpart
  in the current Lean development; the statement is kept for exposition and the label only so that
  cross-references resolve.}
  Given a volume cocycle whose top, slow and remaining log-exponent sequences satisfy a sum law
  \(\mathrm{vol} = \mathrm{slow} + \mathrm{rest}\) with the appropriate limits, the slow
  restricted-operator-norm exponent obeys
  \(\limsup_n \tfrac1n\log(\mathrm{slow}_n) \le \lambda_i\).
\end{lemma}

n33088.content:
\begin{theorem}[Upper bound on the slow space]\label{vslow_subset_lambdaSublevel_of_upper}
  \lean{ErgodicTheory.vslow_subset_lambdaSublevel_of_upper}\leanok
  On the ultrametric-growth good set, every vector \(v\) of the \(\Lambda\)-slow band
  \(\mathrm{vslow}(e^t)\) with \(\limsup_n\tfrac1n\log\left\lVert A^{(n)}v \right\rVert\le t\) lies in the growth
  sublevel \(\{v:\overline\lambda(x,v)\le t\}\).
\end{theorem}

n33089.content:
\begin{proof}\leanok
  \uses{spectral_upper_bound_of_squeeze,lambdaSublevel}
  The \(\limsup\) of \(\tfrac1n\log\left\lVert A^{(n)}v \right\rVert\) is by definition the upper growth function
  \(\overline\lambda(x,v)\); the hypothesis says it is \(\le t\), which is exactly membership in
  the sublevel \(\mathrm{lambdaSublevel}\,t\). The zero vector lies in every submodule.
\end{proof}

n33099.content:
\begin{lemma}[Multi-source geometric envelope]\label{multi_source_envelope}
  \lean{ErgodicTheory.ChainCore.multi_source_envelope}\leanok
  If a nonnegative sequence \(a\) obeys a one-step recursion fed by finitely many source sequences
  each decaying geometrically with ratio \(\rho<1\), then \(a_n\) is bounded by a fixed multiple of
  the summed source envelopes for all \(n\).
\end{lemma}

n33101.content:
\begin{lemma}[Per-stratum envelope step]\label{perStratumEnvelope_step}
  \lean{ErgodicTheory.perStratumEnvelope_step}\leanok
  At a fixed cut strictly inside a gap of width \(\ge G\), the one-step band-mass increment is the
  current mass damped by \(e^{-G}\) plus a tempered source term; iterating produces the per-stratum
  leakage envelope.
\end{lemma}

n33103.content:
\begin{theorem}[The top-gap envelope, a.e.]\label{topGapMassEnvelope_ae}
  \lean{ErgodicTheory.topGapMassEnvelope_ae}\leanok
  For \(\mu\)-a.e.\ \(x\), the top-gap fast-band-mass envelope
  \(\mathrm{TopGapMassEnvelope}\,A\,T\,\lambda^0\,x\) holds.
\end{theorem}

n33105.content:
\begin{lemma}[Spectrum identity from two inclusions]\label{lyapunovSpectrum_eq_of_subsets}
  \lean{ErgodicTheory.lyapunovSpectrum_eq_of_subsets}\leanok
  If at \(x\) every realized exponent is a deterministic one and every deterministic exponent is
  attained, then \(\mathrm{lyapunovSpectrum}(x) = \mathrm{distinctExp}\,\lambda^0\,d\).
\end{lemma}

n33106.content:
\begin{proof}\leanok
  \uses{lyapunovSpectrum}
  Both directions are finite-set inclusions; antisymmetry of \(\subseteq\) gives the equality of
  the two finite subsets of \(\mathbb{R}\).
\end{proof}

n33111.content:
\begin{theorem}[Filtration from the top-gap envelope]\label{oseledets_filtration_of_topgap}
  \lean{ErgodicTheory.oseledets_filtration_of_topgap}\leanok
  Under the standing ergodic, invertible, log-integrable hypotheses, and assuming the top-gap
  envelope \(\mathrm{TopGapMassEnvelope}\) quantified over \(\lambda^0\), the full Oseledets
  filtration conclusion holds.
\end{theorem}

n33116.content:
\begin{theorem}[Repackaged existence]\label{oseledets_filtration'}
  \lean{ErgodicTheory.oseledets_filtration'}\leanok
  Under the standing hypotheses (ergodic $T$, invertible measurable $A$ with $\log^+\left\lVert A \right\rVert, \log^+\left\lVert A^{-1} \right\rVert \in L^1$), there exist $k, \lambda, V$ with $\mathrm{IsOseledetsFiltration}\ \mu\ T\ A\ k\ \lambda\ V$.
\end{theorem}

n33117.content:
\begin{proof}\leanok
  \uses{oseledets_filtration, IsOseledetsFiltration}
  Destructure the conclusion of $\texttt{oseledets\_filtration}$ and repackage its three conjuncts as the bundled predicate; the data match definitionally.
\end{proof}

n33118.content:
\begin{theorem}[Canonical sublevel characterization]\label{ae_mem_iff_limsup_le}
  \lean{ErgodicTheory.IsOseledetsFiltration.ae_mem_iff_limsup_le}\leanok
  If $\mathrm{IsOseledetsFiltration}\ \mu\ T\ A\ k\ \lambda\ V$ holds, then $\mu$-a.e.\ each interior flag level is exactly a growth-sublevel set: for every $i$ and vector $v$,
  \[ v \in V_i(x) \iff v = 0 \ \lor\ \limsup_n \tfrac1n \log\left\lVert A^{(n)}(x)v \right\rVert \le \lambda_i. \]
\end{theorem}

n33119.content:
\begin{proof}\leanok
  \uses{oseledets_filtration, IsOseledetsFiltration}
  At a good point pick the stratum index $j$ of $v \ne 0$; the per-stratum convergence gives $\limsup = \lambda_j$. Membership in $V_i$ forces $i \le j$, so by antitonicity $\lambda_j \le \lambda_i$; conversely if $v \notin V_i$ then $j < i$ and $\lambda_j > \lambda_i$ strictly, contradicting the bound. The disjunct $v = 0$ handles $\log 0$. No machinery beyond the a.e.\ block is used.
\end{proof}

n33120.content:
\begin{theorem}[Uniqueness of the spectrum and filtration]\label{unique}
  \lean{ErgodicTheory.IsOseledetsFiltration.unique}\leanok
  On a probability space, any two Oseledets filtration data $(k, \lambda, V)$ and $(k_2, \lambda_2, V_2)$ for the same cocycle agree: $k = k_2$, the exponents coincide under the index cast, and $\mu$-a.e.\ the flags agree level by level.
\end{theorem}

n33121.content:
\begin{proof}\leanok
  \uses{ae_mem_iff_limsup_le, oseledets_filtration}
  At a single good point the set of realized growth limits equals $\mathrm{range}\,\lambda$ and $\mathrm{range}\,\lambda_2$; two strictly antitone enumerations of one finite set coincide, giving $k = k_2$ and $\lambda = \lambda_2$. Levelwise identity then follows from the sublevel characterization $\ref{ae_mem_iff_limsup_le}$ applied to both data.
\end{proof}

n33122.content:
\begin{lemma}[Nontriviality]\label{k_pos}
  \lean{ErgodicTheory.IsOseledetsFiltration.k_pos}\leanok
  On a probability space with $0 < d$, any Oseledets filtration has $0 < k$.
\end{lemma}

n33123.content:
\begin{proof}\leanok
  \uses{oseledets_filtration}
  If $k = 0$ then at a good point $\mathbb{R}^d = V_0(x) = V_{\mathrm{last}}(x) = 0$, forcing $\mathrm{finrank} = 0$, contradicting $d > 0$.
\end{proof}

n33124.content:
\begin{theorem}[Top exponent = norm growth]\label{tendsto_log_opNorm_cocycle}
  \lean{ErgodicTheory.IsOseledetsFiltration.tendsto_log_opNorm_cocycle}\leanok
  On a probability space, with $A$ invertible and $0 < k$, $\mu$-a.e.\ the operator-norm growth rate of the cocycle converges to the top exponent:
  \[ \tfrac1n \log\left\lVert A^{(n)}(x) \right\rVert \to \lambda_0. \]
\end{theorem}

n33126.content:
\begin{corollary}[Identification of the Furstenberg--Kesten constant]\label{oseledets_top_exponent_eq_furstenbergKesten}
  \lean{ErgodicTheory.oseledets_top_exponent_eq_furstenbergKesten}\leanok
  Any constant $c$ to which $\tfrac1n\log\left\lVert A^{(n)}(x) \right\rVert$ converges $\mu$-a.e.\ (e.g.\ the Furstenberg--Kesten constant) equals $\lambda_0$.
\end{corollary}

n33127.content:
\begin{proof}\leanok
  \uses{tendsto_log_opNorm_cocycle}
  Both $\ref{tendsto_log_opNorm_cocycle}$ and the hypothesis hold at a common good point; uniqueness of limits gives $\lambda_0 = c$.
\end{proof}

n33128.content:
\begin{theorem}[Deterministic dimension profile]\label{exists_finrank_ae_eq}
  \lean{ErgodicTheory.IsOseledetsFiltration.exists_finrank_ae_eq}\leanok
  For ergodic $T$ and invertible $A$, every Oseledets filtration has a deterministic dimension profile: there is a strictly decreasing $m : \mathrm{Fin}(k+1) \to \mathbb{N}$ with $m_0 = d$, $m_k = 0$ and, $\mu$-a.e., $\mathrm{finrank}\,V_i(x) = m_i$.
\end{theorem}

n33129.content:
\begin{proof}\leanok
  \uses{oseledets_filtration}
  The dimension $x \mapsto \mathrm{finrank}\,V_i(x)$ is measurable via the trace of the orthogonal projector, and $T$-invariant a.e.\ because equivariance through the invertible $A(x)$ preserves dimension. Ergodicity makes each invariant $\mathbb{N}$-valued function a.e.\ constant. The profile structure ($\mathrm{StrictAnti}$, endpoints) is read off one good point.
\end{proof}

n33130.content:
\begin{corollary}[Per-exponent multiplicities]\label{exists_multiplicity}
  \lean{ErgodicTheory.IsOseledetsFiltration.exists_multiplicity}\leanok
  For ergodic $T$ and invertible $A$, each exponent $\lambda_i$ carries a positive deterministic multiplicity $m_i = \dim V_i - \dim V_{i+1}$ with $\sum_i m_i = d$.
\end{corollary}

n33131.content:
\begin{proof}\leanok
  \uses{exists_finrank_ae_eq}
  Set $m_i$ to the consecutive dimension drops of $\ref{exists_finrank_ae_eq}$; positivity is strict antitonicity, and the telescoping sum equals $m_0 - m_k = d$.
\end{proof}

n33132.content:
\begin{theorem}[MET with multiplicities]\label{oseledets_filtration_with_multiplicities}
  \lean{ErgodicTheory.oseledets_filtration_with_multiplicities}\leanok
  Under the standing hypotheses there exist $k, \lambda, V$ and a strictly decreasing $m$ with $m_0 = d$, $m_k = 0$, such that $\mathrm{IsOseledetsFiltration}\ \mu\ T\ A\ k\ \lambda\ V$ holds and $\mu$-a.e.\ $\mathrm{finrank}\,V_i(x) = m_i$.
\end{theorem}

n33133.content:
\begin{proof}\leanok
  \uses{oseledets_filtration', exists_finrank_ae_eq}
  Obtain a witness from $\ref{oseledets_filtration'}$ and apply $\ref{exists_finrank_ae_eq}$ to it.
\end{proof}

n33134.content:
\begin{definition}[Sorted spectrum]\label{exponents}
  \lean{ErgodicTheory.exponents}\leanok
  The full Lyapunov spectrum with multiplicity is the total function $\mathrm{exponents} : \mathrm{Fin}\,d \to \mathbb{R}$, whose $i$-th entry is the deterministic limit of $\tfrac1n\log\sigma_i(A^{(n)})$, sorted non-increasingly. The top entry is $\mathrm{topExponent}$.
\end{definition}

n33135.content:
\begin{theorem}[Defining $\sigma$-limit and order]\label{exponents_tendsto_log_singularValue}
  \lean{ErgodicTheory.exponents_tendsto_log_singularValue}\leanok
  For each sorted index $i$ and $\mu$-a.e.\ $x$, $\tfrac1n\log\sigma_i(A^{(n)}(x)) \to \mathrm{exponents}_i$; moreover $\mathrm{exponents}$ is antitone.
\end{theorem}

n33136.content:
\begin{proof}\leanok
  \uses{oseledets_filtration}
  The deterministic exponent sequence is extracted by $\mathrm{Classical.choose}$ from the singular-value convergence theorem underlying the MET; antitonicity and the a.e.\ limit are its defining specification.
\end{proof}

n33137.content:
\begin{theorem}[Eigenvalue tie]\label{exp_exponents_eq_eigenvalues₀_oseledetsLimit}
  \lean{ErgodicTheory.exp_exponents_eq_eigenvalues₀_oseledetsLimit}\leanok
  $\mu$-a.e., $\exp(\mathrm{exponents}_i)$ is the $i$-th sorted eigenvalue of the Oseledets limit matrix $\Lambda(x)$.
\end{theorem}

n33138.content:
\begin{proof}\leanok
  \uses{exponents_tendsto_log_singularValue}
  The $\sigma$-limit identifies $\mathrm{lamSing}(x,i) = \mathrm{exponents}_i$ a.e.; combine with the eigenvalues of $\Lambda$ being $e^{\mathrm{lamSing}}$.
\end{proof}

n33139.content:
\begin{theorem}[Sign characterizations of exponent sums]\label{sumPosExp_pos_iff}
  \lean{ErgodicTheory.sumPosExp_pos_iff}\leanok
  The sum $\mathrm{sumPosExp}$ of the strictly positive exponents is nonnegative, vanishes iff all exponents are $\le 0$, and is strictly positive iff some exponent is positive (and dually $\mathrm{sumNegExp} \le 0$ with the mirror characterizations).
\end{theorem}

n33140.content:
\begin{proof}\leanok
  \uses{exponents_tendsto_log_singularValue}
  Each summand of $\mathrm{sumPosExp}$ is strictly positive on the filter, so the sum is $\ge 0$; a sum of nonnegatives vanishes iff the filter is empty, i.e.\ no exponent is positive.
\end{proof}

n33141.content:
\begin{theorem}[Telescoping identity for partial sums]\label{gammaK_eq_sum_top_exponents}
  \lean{ErgodicTheory.gammaK_eq_sum_top_exponents}\leanok
  For $k \le d$, the ergodic growth rate $\Gamma_k$ of the product of the top-$k$ singular values equals the sum of the top-$k$ exponents: $\Gamma_k = \sum_{i<k} \mathrm{exponents}_i$.
\end{theorem}

n33142.content:
\begin{proof}\leanok
  \uses{exponents_tendsto_log_singularValue}
  Since $\mathrm{sprod}_k = \prod_{i<k}\sigma_i$, the normalized $\log\mathrm{sprod}_k$ is the finite sum of the per-index $\tfrac1n\log\sigma_i$, each converging to $\mathrm{exponents}_i$. The sum of convergents converges to the sum of limits; uniqueness against the defining limit of $\Gamma_k$ closes it.
\end{proof}

n33143.content:
\begin{definition}[Exterior cocycle generator]\label{extGen}
  \lean{ErgodicTheory.extGen}\leanok
  The $k$-th exterior generator $\mathrm{extGen}\,k\,A$ sends $x$ to the $k$-th compound matrix $C_k(A x)$ of $k\times k$ minors. Its iterated cocycle is the compound of the iterate: $\mathrm{cocycle}(\mathrm{extGen}\,k\,A)\,T\,n\,x = C_k(A^{(n)}(x))$.
\end{definition}

n33144.content:
\begin{theorem}[$k$-volume growth rate]\label{tendsto_log_opNorm_compound_cocycle}
  \lean{ErgodicTheory.tendsto_log_opNorm_compound_cocycle}\leanok
  For $k \le d$ and $\mu$-a.e.\ $x$, the operator-norm growth of the compound cocycle converges to $\Gamma_k$: $\tfrac1n\log\left\lVert C_k(A^{(n)}(x)) \right\rVert \to \Gamma_k$, the $k$-dimensional volume growth rate.
\end{theorem}

n33145.content:
\begin{proof}\leanok
  \uses{gammaK_eq_sum_top_exponents}
  The operator norm of the compound matrix is $\mathrm{sprod}_k$, the product of the top-$k$ singular values; rewrite and apply the defining a.e.\ limit of $\Gamma_k$.
\end{proof}

n33146.content:
\begin{corollary}[Positive sum as a maximal partial sum]\label{sumPosExp_eq_gammaK_card_pos}
  \lean{ErgodicTheory.sumPosExp_eq_gammaK_card_pos}\leanok
  Writing $k_+ = \#\{i : 0 < \mathrm{exponents}_i\}$, the positive-exponent sum equals the partial sum $\Gamma_{k_+} = \sum_{i<k_+}\mathrm{exponents}_i$.
\end{corollary}

n33147.content:
\begin{proof}\leanok
  \uses{gammaK_eq_sum_top_exponents, sumPosExp_pos_iff}
  By antitonicity the strictly positive entries are exactly the top $k_+$ indices, so the filtered positive sum coincides with the top-$k_+$ prefix sum, which is $\Gamma_{k_+}$ via $\ref{gammaK_eq_sum_top_exponents}$.
\end{proof}

n33148.content:
\begin{lemma}[Product of singular values is the absolute determinant]\label{sprod_d_eq_abs_det}
  \lean{ErgodicTheory.sprod_d_eq_abs_det}\leanok
  For every $n$, $x$: $\mathrm{sprod}\,A\,T\,d\,n\,x = \left\lvert \det A^{(n)}(x) \right\rvert$.
\end{lemma}

n33149.content:
\begin{proof}\leanok
  Squaring, $\mathrm{sprod}_d^2 = \prod_i \sigma_i^2 = \det(M^{\top} M) = (\det M)^2$ for the symmetric Gram operator; take the nonnegative square root. No invertibility is needed.
\end{proof}

n33150.content:
\begin{theorem}[Determinant identity]\label{sumAllExp_eq_integral_log_abs_det}
  \lean{ErgodicTheory.sumAllExp_eq_integral_log_abs_det}\leanok
  The sum of all Lyapunov exponents equals the integral of $\log\left\lvert \det \right\rvert$ of the generator:
  \[ \sum_i \mathrm{exponents}_i = \int_X \log\left\lvert \det A(x) \right\rvert\,d\mu. \]
\end{theorem}

n33153.content:
\begin{proof}\leanok
  \uses{sumAllExp_eq_integral_log_abs_det}
  Since $\tfrac1n\log\left\lvert \det A^{(n)} \right\rvert$ tends to a negative constant, $\log\left\lvert \det A^{(n)} \right\rvert \to -\infty$, so its exponential tends to $0$.
\end{proof}

n33154.content:
\begin{theorem}[Inverse cocycle exponents]\label{tendsto_log_singularValue_inv_cocycle}
  \lean{ErgodicTheory.tendsto_log_singularValue_inv_cocycle}\leanok
  For each sorted index $i$ and $\mu$-a.e.\ $x$, the singular-value exponents of the inverse-matrix cocycle are the negated, reversed exponents of $A$:
  \[ \tfrac1n\log\sigma_i\!\big((A^{(n)}(x))^{-1}\big) \to -\,\mathrm{exponents}_{\mathrm{rev}\,i}. \]
\end{theorem}

n33155.content:
\begin{proof}\leanok
  \uses{exponents_tendsto_log_singularValue}
  Singular-value reciprocity $\sigma_i(M^{-1}) = \sigma_{\mathrm{rev}\,i}(M)^{-1}$ for invertible $M$, applied to the iterate, turns the forward limit $\mathrm{exponents}_{\mathrm{rev}\,i}$ into its negative.
\end{proof}

n33156.content:
\begin{corollary}[Top of the reversed spectrum is minus the bottom]\label{topExponent_inv_eq_neg_bot}
  \lean{ErgodicTheory.topExponent_inv_eq_neg_bot}\leanok
  $\mu$-a.e.\ the largest exponent of the inverse cocycle is $-\,\mathrm{exponents}_{d-1}$, the negative of the smallest forward exponent.
\end{corollary}

n33158.content:
\begin{definition}[Invariant subbundle]\label{InvariantSubbundle}
  \lean{ErgodicTheory.InvariantSubbundle}\leanok
  An invariant subbundle is a measurable family of fibre subspaces $W(x) \le \mathbb{R}^d$ that is $A$-equivariant a.e.: $A(x)\,W(x) = W(Tx)$.
\end{definition}

n33159.content:
\begin{lemma}[Dimension interlacing]\label{restricted_finrank_le}
  \lean{ErgodicTheory.restricted_finrank_le}\leanok
  At each ambient flag level, the dimension captured by the subbundle is bounded by the ambient dimension: $\dim\big(W(x) \cap V_i(x)\big) \le \dim V_i(x)$, so the restricted multiplicities are a sub-multiset of the ambient ones.
\end{lemma}

n33163.content:
\begin{theorem}[Non-ergodic exponents]\label{exists_exponents_nonergodic}
  \lean{ErgodicTheory.exists_exponents_nonergodic}\leanok
  For merely measure-preserving $T$ (no ergodicity) and invertible measurable $A$ with the standing integrability, there is a family of $T$-invariant integrable functions $\lambda_i : X \to \mathbb{R}$ such that for each $i < d$ and $\mu$-a.e.\ $x$, $\tfrac1n\log\sigma_i(A^{(n)}(x)) \to \lambda_i(x)$. The exponents become invariant functions rather than constants.
\end{theorem}

n33164.content:
\begin{proof}\leanok
  \uses{oseledets_filtration}
  The non-ergodic Kingman theorem applied to the subadditive cocycle $\log\mathrm{sprod}_k$ produces invariant integrable partial-sum limits $G_k$; set $\lambda_i = G_{i+1} - G_i$, with the per-$\sigma$ telescoping as in the ergodic case.
\end{proof}

n33165.content:
\begin{corollary}[Non-ergodic positive-exponent sum]\label{exists_sumPosExp_nonergodic}
  \lean{ErgodicTheory.exists_sumPosExp_nonergodic}\leanok
  Summing the positive parts $\max(\lambda_i(x),0)$ over $i < d$ yields a single $T$-invariant integrable function $G_+ : X \to \mathbb{R}$, the non-ergodic analogue of the positive-exponent sum.
\end{corollary}

n33166.content:
\begin{proof}\leanok
  \uses{exists_exponents_nonergodic}
  A finite sum of positive parts of the invariant integrable functions of $\ref{exists_exponents_nonergodic}$ is invariant and integrable.
\end{proof}

n33167.content:
\begin{theorem}[Fekete infimum representation]\label{gammaK_eq_iInf}
  \lean{ErgodicTheory.gammaK_eq_iInf}\leanok
  The partial-sum growth rate is the infimum over $n$ of the normalized integrals:
  \[ \Gamma_k = \inf_n \frac{1}{n+1}\int_X \log\mathrm{sprod}_k(n+1,x)\,d\mu. \]
\end{theorem}

n33168.content:
\begin{proof}\leanok
  \uses{gammaK_eq_sum_top_exponents}
  The integral sequence is subadditive (Fekete), so it converges to its infimum; a Fatou estimate against the dominating Birkhoff averages of $\log^+\left\lVert A^{\pm1} \right\rVert$ identifies that limit with the a.e.\ growth rate $\Gamma_k$ in both directions.
\end{proof}

n33169.content:
\begin{theorem}[Upper semicontinuity of partial sums and top exponent]\label{gammaK_upperSemicontinuous}
  \lean{ErgodicTheory.gammaK_upperSemicontinuous}\leanok
  Along a filter of generators $B_i \to A$ for which each fixed-$n$ integral is continuous, the partial-sum rate is upper semicontinuous: $\limsup_i \Gamma_k(B_i) \le \Gamma_k(A)$; specializing $k=1$ gives the same for the top exponent. This is USC, not continuity --- equality can fail when a spectral gap closes.
\end{theorem}

n33170.content:
\begin{proof}\leanok
  \uses{gammaK_eq_iInf}
  $\Gamma_k$ is an infimum of the per-$n$ continuous normalized integrals ($\ref{gammaK_eq_iInf}$); for each $n$, $\Gamma_k(B_i)$ is below the $n$-th integral, whose limit along the filter is the $n$-th integral of $A$, so $\limsup_i \Gamma_k(B_i)$ is at most every term of the infimum.
\end{proof}

n33171.content:
\begin{theorem}[Lower semicontinuity of the bottom exponent]\label{botExp_lowerSemicontinuous}
  \lean{ErgodicTheory.botExp_lowerSemicontinuous}\leanok
  The bottom exponent $\lambda_d = \Gamma_d - \Gamma_{d-1}$ is lower semicontinuous in the generator: $\lambda_d(A) \le \liminf_i \lambda_d(B_i)$.
\end{theorem}

n33172.content:
\begin{proof}\leanok
  \uses{gammaK_upperSemicontinuous, sumAllExp_eq_integral_log_abs_det}
  Writing $\Gamma_d = \int\log\left\lvert \det \right\rvert$ (the determinant identity $\ref{sumAllExp_eq_integral_log_abs_det}$), which is continuous in the generator under the hypothesis, and $\Gamma_{d-1}$ upper semicontinuous ($\ref{gammaK_upperSemicontinuous}$), the difference $\Gamma_d - \Gamma_{d-1}$ is lower semicontinuous.
\end{proof}

n33173.content:
\begin{theorem}[Forward top value]\label{tendsto_top_posLogNorm}
  \lean{ErgodicTheory.tendsto_top_posLogNorm}\leanok
  For ergodic $T$ and a possibly-singular measurable generator with only $\log^+\left\lVert A \right\rVert \in L^1$ (no invertibility, no inverse integrability), the normalized positive-part log-norms $\tfrac1n\log^+\left\lVert A^{(n)}(x) \right\rVert$ converge $\mu$-a.e.\ to a constant $\lambda_1^+$.
\end{theorem}

n33174.content:
\begin{proof}\leanok
  Apply the ergodic Kingman theorem to the subadditive, bounded-below, integrable cocycle $\log^+\left\lVert A^{(n)} \right\rVert$; only the forward integrability is used.
\end{proof}

n33175.content:
\begin{theorem}[Upper bound on the singular top exponent]\label{limsup_logNorm_le_top}
  \lean{ErgodicTheory.limsup_logNorm_le_top}\leanok
  Under the same singular hypotheses there is $\lambda_1^+$ with, $\mu$-a.e.,
  \[ \limsup_n\Big(\tfrac1n\log\left\lVert A^{(n)}(x) \right\rVert : \mathrm{EReal}\Big) \le \lambda_1^+. \]
  The $\limsup$ is taken in $\mathrm{EReal}$ so the bound is unconditional even when the growth tends to $-\infty$; this is one-sided only.
\end{theorem}

n33176.content:
\begin{proof}\leanok
  \uses{tendsto_top_posLogNorm}
  Termwise $\log \le \log^+$, then pass to the $\mathrm{EReal}$ $\limsup$; since the $\log^+$ sequence converges to $\lambda_1^+$ ($\ref{tendsto_top_posLogNorm}$), its $\limsup$ is $\lambda_1^+$.
\end{proof}

n33177.content:
\begin{theorem}[Sharp $\limsup$ in the expanding case]\label{limsup_logNorm_eq_top_of_pos}
  \lean{ErgodicTheory.limsup_logNorm_eq_top_of_pos}\leanok
  There is a forward top value $\lambda_1^+$ (the a.e.\ limit of $\tfrac1n\log^+\left\lVert A^{(n)} \right\rVert$) such that, whenever $\lambda_1^+ > 0$, $\mu$-a.e.\ the genuine log-norm $\limsup$ is exactly $\lambda_1^+$:
  \[ \limsup_n\Big(\tfrac1n\log\left\lVert A^{(n)}(x) \right\rVert : \mathrm{EReal}\Big) = \lambda_1^+. \]
  The positivity hypothesis is essential; in the contracting case $\lambda_1^+ = 0$ the genuine growth may tend to $-\infty$ and equality fails.
\end{theorem}

n33178.content:
\begin{proof}\leanok
  \uses{limsup_logNorm_le_top, tendsto_top_posLogNorm}
  The $\le$ half is $\ref{limsup_logNorm_le_top}$. For $\ge$: where $\tfrac1n\log^+\left\lVert A^{(n)} \right\rVert \to \lambda_1^+ > 0$ the sequence is eventually positive, forcing $\log\left\lVert A^{(n)} \right\rVert > 0$, so $\log^+ = \log$ eventually; the two $\mathrm{EReal}$ sequences agree eventually, hence so do their $\limsup$s, which equal $\lambda_1^+$.
\end{proof}

n33179.content:
\begin{theorem}[Singular top-$k$ volume upper bound]\label{limsup_logSprod_le_top}
  \lean{ErgodicTheory.limsup_logSprod_le_top}\leanok
  For ergodic $T$ and a possibly-singular generator with $\log^+\left\lVert A \right\rVert \in L^1$, there is a constant $\Gamma_k^+$ with, $\mu$-a.e.,
  \[ \limsup_n\Big(\tfrac1n\log\mathrm{sprod}_k(x) : \mathrm{EReal}\Big) \le \Gamma_k^+. \]
  The top-$k$ volume growth is bounded above unconditionally (the $\mathrm{EReal}$ $\limsup$ allows volume collapse), again one-sided only.
\end{theorem}

n33180.content:
\begin{proof}\leanok
  \uses{tendsto_top_posLogNorm}
  Since $\mathrm{sprod}_k \ge 0$ is submultiplicative with no invertibility, the same $\log^+$-of-a-nonnegative-subadditive-quantity Kingman construction gives the a.e.-constant value $\Gamma_k^+$ and the termwise $\log \le \log^+$ domination transfers to the $\mathrm{EReal}$ $\limsup$.
\end{proof}

n33182.content:
\begin{lemma}[Cocycle recursion, newest factor on the right]\label{cocycle_succ'}
  \lean{ErgodicTheory.cocycle_succ'}\leanok
  For any generator \(A\) and map \(T\), \(A^{(n+1)}(x) = A(T^{[n]}x)\cdot A^{(n)}(x)\).
\end{lemma}

n33183.content:
\begin{proof}\leanok
  \uses{cocycle_add}
  This is the companion of the standard recursion \(A^{(n+1)}(x) = A^{(n)}(Tx)\cdot A(x)\): apply the additive law \(A^{(m+n)} = A^{(m)}(T^{[n]}\cdot)\cdot A^{(n)}\) with \(m = 1\) after commuting the summands.
\end{proof}

n33186.content:
\begin{proposition}[Backward standing hypotheses]\label{backwardData_of}
  \lean{ErgodicTheory.backwardData_of}\leanok
  If \(\det A(x) \neq 0\) for all \(x\), \(A\) is measurable, \(T\) is measure-preserving, and \(\log^+\left\lVert A \right\rVert, \log^+\left\lVert A^{-1} \right\rVert \in L^1(\mu)\), then the backward system \((T^{-1}, B)\) satisfies the same four hypotheses: \(\det B \neq 0\) everywhere, \(B\) measurable, and \(\log^+\left\lVert B \right\rVert, \log^+\left\lVert B^{-1} \right\rVert \in L^1(\mu)\).
\end{proposition}

n33188.content:
\begin{lemma}[Biinvariant conull set]\label{exists_conull_biinvariant}
  For \(T\) measure-preserving on a probability space and a conull measurable set \(S\), there is a conull measurable \(S' \subseteq S\) invariant under both \(T\) and \(T^{-1}\).
\end{lemma}

n33189.content:
\begin{proof}
  Take \(S' = \bigl(\bigcap_n (T^{[n]})^{-1}S\bigr) \cap \bigl(\bigcap_n (T^{-[n]})^{-1}S\bigr)\). Each iterate is measure-preserving, so every preimage of the conull \(S\) is conull and the countable intersection is conull. Membership is "all forward and backward iterates land in \(S\)"; applying \(T\) or \(T^{-1}\) merely shifts the index, the cross term collapsing through \(T^{-1}\circ T = \mathrm{id}\).
\end{proof}

n33194.content:
\begin{lemma}[Functional calculus on an eigenvector]\label{cfc_apply_of_eigenvector}
  \lean{ErgodicTheory.cfc_apply_of_eigenvector}\leanok
  If \(M\) is self-adjoint and \(M v = c\,v\) for \(v \neq 0\), then \((\mathrm{cfc}\,f\,M)\,v = f(c)\cdot v\).
\end{lemma}

n33195.content:
\begin{proof}\leanok
  The eigenvalue \(c\) lies in the (finite) spectrum of \(M\). Pick a Lagrange interpolating polynomial \(q\) with \(q = f\) on the spectrum; then \(\mathrm{cfc}\,f\,M = \mathrm{cfc}\,q\,M = q(M)\), and \(q(M)v = q(c)v = f(c)v\) because \(v\) is an eigenvector. This is pointwise, so no measurability is incurred.
\end{proof}

n33199.content:
\begin{lemma}[Everywhere subadditivity]\label{isSubadditiveCocycle_restLog}
  \lean{ErgodicTheory.isSubadditiveCocycle_restLog}\leanok
  \(\mathrm{restLog}\,A\,V\,T\) is an everywhere subadditive cocycle: for all \(m,n,x\), \(\mathrm{restLog}\,(m+n)\,x \le \mathrm{restLog}\,m\,x + \mathrm{restLog}\,n\,(T^{[m]}x)\).
\end{lemma}

n33201.content:
\begin{lemma}[Restricted Kingman, both directions of time]\label{restLog_backward_kingman}
  \lean{ErgodicTheory.restLog_backward_kingman}\leanok
  Kingman applied to \(\mathrm{restLog}\) over \(T\) yields a constant \(\chi_V\); the orbit-reversed cocycle \(h_n(x) = \mathrm{restLog}_n(T^{-n}x)\) is subadditive over \(T^{-1}\) with the same integral means, hence converges a.e.\ to the same \(\chi_V\).
\end{lemma}

n33203.content:
\begin{proposition}[Restricted exponent equals \(\lambda_i\)]\label{restricted_const_eq}
  \lean{ErgodicTheory.restricted_const_eq}\leanok
  For the forward level \(V_i\), the restricted Kingman constant equals the \(i\)-th exponent: \(\chi_{V_i} = \mathrm{expEnum}\,\mathrm{lam0}\,d\,i\).
\end{proposition}

n33206.content:
\begin{proof}\leanok
  \uses{restricted_const_eq,restLog_backward_kingman}
  This is the analytic heart. By \cref{restLog_backward_kingman} the reversed restricted log converges a.e.\ to the same constant \(\chi_{V_i}\), which \cref{restricted_const_eq} identifies as \(\lambda_i\). On the good set the floor is absorbed, so the \(\limsup\) of the genuine restricted norm along the backward orbit is bounded by \(\lambda_i\). Only the \(\le\) direction is consumed downstream.
\end{proof}

n33207.content:
\begin{proposition}[Sublevels of opposite sign are transverse]\label{inf_eq_bot_of_neg_sum}
  \lean{ErgodicTheory.inf_eq_bot_of_neg_sum}\leanok
  Fix \(x\). If the forward envelope for \(V_x\) holds at rate \(a\), \(U_x\) decays backward at rate \(\le b\), and \(a + b < 0\), then \(V_x \sqcap U_x = \bot\).
\end{proposition}

n33212.content:
\begin{proof}\leanok
  \uses{ae_crux,oseledets_filtration_dims}
  Convert thresholds to filtration levels and apply \cref{ae_crux} at one good point: the two sublevel spaces meet in \(\bot\), so by the Grassmann formula their dimensions sum to at most \(\dim \mathbb{R}^d = d\). The dimension formula of \cref{oseledets_filtration_dims} (forward and backward) turns the dimensions into the stated counts. The bound is deterministic, so it holds outright.
\end{proof}

n33213.content:
\begin{proposition}[Forward determinant sum]\label{sum_lam0_eq_integral_log_abs_det}
  \lean{ErgodicTheory.sum_lam0_eq_integral_log_abs_det}\leanok
  Any exponent sequence \(\mathrm{lam0}\) realizing the a.e.\ singular-value limits satisfies \(\sum_{j<d}\mathrm{lam0}\,j = \int_X \log\left\lvert \det A(x) \right\rvert\,d\mu\).
\end{proposition}

n33214.content:
\begin{proof}\leanok
  By uniqueness of a.e.\ limits at a common conull point, \(\mathrm{lam0}\,j\) equals the chosen spectrum \(\mathrm{exponents}\,j\) for each \(j < d\); the sum of those is the integral of \(\log\left\lvert \det A \right\rvert = \log\prod_j \sigma_j\) via the established singular-value/determinant identity.
\end{proof}

n33215.content:
\begin{proposition}[Backward sum is the negated forward sum]\label{sum_mu0_eq_neg_sum_lam0}
  \lean{ErgodicTheory.sum_mu0_eq_neg_sum_lam0}\leanok
  For a backward exponent sequence \(\mathrm{mu0}\), \(\sum_{j<d}\mathrm{mu0}\,j = -\sum_{j<d}\mathrm{lam0}\,j\).
\end{proposition}

n33217.content:
\begin{proposition}[Reflection lemma]\label{reflect_of_counting_and_sum}
  \lean{ErgodicTheory.reflect_of_counting_and_sum}\leanok
  Let \(p, q : \mathbb{N}\to \mathbb{R}\) be antitone on \([0,d)\). If \(\#\{p \le a\} + \#\{q \le b\} \le d\) whenever \(a + b < 0\), and \(\sum_{j<d} q\,j = -\sum_{j<d} p\,j\), then \(q\,j = -p\,(d-1-j)\) for all \(j < d\).
\end{proposition}

n33218.content:
\begin{proof}\leanok
  Apply the counting bound at \(b\) and \(a = -q(j) - \varepsilon\): since antitone tuples are their own sorted enumerations, this gives the sorted domination \(q\,j \ge -p\,(d-1-j)\) for each \(j\). A pointwise \(\ge\) whose total sum is an equality forces pointwise equality, so \(q\,j = -p\,(d-1-j)\). This is pure finite combinatorics with no analytic content.
\end{proof}

n33219.content:
\begin{corollary}[Aligned backward index]\label{sidx_exp}
  \lean{ErgodicTheory.sidx_exp}\leanok
  Under the reflection \(\mathrm{mu0}\,j = -\mathrm{lam0}\,(d-1-j)\), the backward count of distinct exponents equals the forward one, and the index \(\mathrm{sidx}\,i = \mathrm{cast}\,(\mathrm{Fin.rev}\,i)\) satisfies \(\mathrm{expEnum}\,\mathrm{mu0}\,d\,(\mathrm{sidx}\,i) = -\mathrm{expEnum}\,\mathrm{lam0}\,d\,i\).
\end{corollary}

n33222.content:
\begin{proof}\leanok
  \uses{one_eigenspace_projComp}
  The matrix \(S = P_K P_L P_K\) is self-adjoint, PSD, and a contraction, so its eigenvalues lie in \([0,1]\); by \cref{one_eigenspace_projComp} its \(1\)-eigenspace is exactly \(K \sqcap L\). Diagonalizing by the spectral theorem, \(c^n \to 1\) if \(c = 1\) and \(\to 0\) otherwise, so \(S^n\) converges to the orthogonal projection onto the \(1\)-eigenspace, namely \(P_{K\sqcap L}\).
\end{proof}

n33223.content:
\begin{lemma}[The intersection fixes exactly \(K \sqcap L\)]\label{one_eigenspace_projComp}
  \lean{ErgodicTheory.one_eigenspace_projComp}\leanok
  \((P_K\,P_L\,P_K)\,v = v\) if and only if \(v \in K \sqcap L\).
\end{lemma}

n33224.content:
\begin{proof}\leanok
  The "if" direction is immediate since both projectors fix vectors in \(K \sqcap L\). For "only if", \(\langle Sv, v\rangle = \left\lVert P_L P_K v \right\rVert^2\); the Cauchy--Schwarz equality chain \(\left\lVert v \right\rVert^2 = \langle Sv, v\rangle \le \left\lVert v \right\rVert^2\) forces \(v \in K\) and \(P_K v \in L\), whence \(v \in K \sqcap L\).
\end{proof}

n33225.content:
\begin{proposition}[Measurable intersection of measurable subspaces]\label{inf}
  \lean{ErgodicTheory.MeasurableSubspace.inf}\leanok
  If \(x \mapsto V(x)\) and \(x \mapsto W(x)\) are measurable subspace families, then so is \(x \mapsto V(x) \sqcap W(x)\).
\end{proposition}

n33226.content:
\begin{proof}\leanok
  \uses{tendsto_pow_orthProj_inf}
  Each \(x \mapsto (P_{V(x)} P_{W(x)} P_{V(x)})^{n}\) is measurable (matrix powers of measurable matrices). By \cref{tendsto_pow_orthProj_inf} these converge pointwise to \(P_{V(x)\sqcap W(x)}\), so the limiting projector is measurable entrywise as a limit of measurable functions; this exhibits the intersection family as measurable.
\end{proof}

n33227.content:
\begin{lemma}[Telescoping-flag lattice lemma]\label{flag_iSupIndep_and_iSup}
  A descending flag \(V_0 \supseteq \cdots \supseteq V_k = \bot\) in a modular lattice, with complements \(E_i\) satisfying \(V_i = E_i \sqcup V_{i+1}\) and \(E_i \sqcap V_{i+1} = \bot\), telescopes into an independent family \((E_i)\) with \(\bigsqcup_i E_i = V_0\).
\end{lemma}

n33228.content:
\begin{proof}\leanok
  Induct on \(k\). The cons step shows that prepending a head \(E_0\) disjoint from the supremum of an already-independent tail preserves independence, using modularity to peel \(E_0\) off the join \(E_0 \sqcup C\) intersected with the tail bound. The supremum identity unfolds \(\bigsqcup_{i} E_i = E_0 \sqcup \bigsqcup_i E_{i+1} = E_0 \sqcup V_1 = V_0\) via the first telescoping identity.
\end{proof}

n33229.content:
\begin{proposition}[Splitting at a point]\label{esplitAt}
  \lean{ErgodicTheory.esplitAt}\leanok
  Define \(E_i = V_i \sqcap W_{\mathrm{sidx}\,i}\). Then \(\mathrm{finrank}\,E_i \ge 1\), the telescoping identities \(V_i = E_i \sqcup V_{i+1}\) and \(E_i \sqcap V_{i+1} = \bot\) hold, and consequently \((E_i)\) is independent with \(\bigsqcup_i E_i = V_0 = \top\).
\end{proposition}

n33231.content:
\begin{theorem}[The two-sided Oseledets splitting]\label{oseledets_splitting}
  \lean{ErgodicTheory.oseledets_splitting}\leanok
  Let \(T : X \simeq_m X\) be an invertible ergodic measure-preserving transformation of a probability space, and let \(A : X \to \mathrm{Matrix}\,(\mathrm{Fin}\,d)\,(\mathrm{Fin}\,d)\,\mathbb{R}\) be measurable with \(\det A(x) \neq 0\) for all \(x\) and \(\log^+\left\lVert A \right\rVert, \log^+\left\lVert A^{-1} \right\rVert \in L^1(\mu)\). Then there exist \(k \in \mathbb{N}\), a strictly decreasing \(\lambda : \mathrm{Fin}\,k \to \mathbb{R}\), and measurable subspace families \(E : \mathrm{Fin}\,k \to X \to \mathrm{Submodule}\,\mathbb{R}\,(\mathbb{R}^d)\) such that for \(\mu\)-a.e.\ \(x\):
  \begin{itemize}
    \item \(\mathbb{R}^d = \bigoplus_{i} E_i(x)\) is an internal direct sum with every \(E_i(x) \neq \bot\);
    \item each \(E_i\) is \(A\)-equivariant: \(\bigl(A(x)\bigr)\bigl(E_i(x)\bigr) = E_i(Tx)\);
    \item for every nonzero \(v \in E_i(x)\),
    \[
      \tfrac{1}{n}\log\bigl\lVert A^{(n)}(x)\,v \bigr\rVert \to \lambda_i \qquad\text{and}\qquad \tfrac{1}{n}\log\bigl\lVert \bigl(A^{(n)}(T^{-n}x)\bigr)^{-1}\,v \bigr\rVert \to -\lambda_i.
    \]
  \end{itemize}
\end{theorem}

n33234.content:
\begin{lemma}[Integer times are iterates of the time-one map]\label{natCast_eq_iterate}
  \lean{ErgodicTheory.MeasurePreservingFlow.natCast_eq_iterate}\leanok
  For a measure-preserving flow \( \varphi \) and \( n \in \mathbb{N}\), the integer-time map of the
  flow is the \( n \)-fold iterate of its time-one map: \( \varphi(n) = (\varphi(1))^{[n]} \).
\end{lemma}

n33239.content:
\begin{lemma}[Integrability of the time-one log-norm]\label{integrableLogNorm_timeOne}
  \lean{ErgodicTheory.integrableLogNorm_timeOne}\leanok
  If \( g \in L^1(\mu) \) dominates \( \log^{+}\left\lVert A(s,x) \right\rVert \) for all \( s \in [0,1] \) and all
  \( x \), then the time-one map \( A(1,\cdot) \) has integrable positive log-norm.
\end{lemma}

n33241.content:
\begin{lemma}[Integrability of the inverse time-one log-norm]\label{integrableLogNorm_timeOne_inv}
  \lean{ErgodicTheory.integrableLogNorm_timeOne_inv}\leanok
  If \( g' \in L^1(\mu) \) dominates \( \log^{+}\left\lVert (A(s,x))^{-1} \right\rVert \) for all \( s \in [0,1] \)
  and all \( x \), then the inverse \( (A(1,\cdot))^{-1} \) has integrable positive log-norm.
\end{lemma}

n33242.content:
\begin{proof}\leanok
  \uses{FlowCocycle}
  Identical to \ref{integrableLogNorm_timeOne}, inserting the measurable matrix-inversion map
  and evaluating the dominating hypothesis at \( s = 1 \).
\end{proof}

n33245.content:
\begin{lemma}[Error sublinearity along the integer orbit]\label{ae_tendsto_flowError_zero}
  \lean{ErgodicTheory.ae_tendsto_flowError_zero}\leanok
  For integrable \( g, g' \) and a measure-preserving flow \( \varphi \), for almost every
  \( x \) the combined fluctuation along the integer orbit vanishes:
  \[ n^{-1}\bigl(g(\varphi(n)x) + g'(\varphi(n)x)\bigr) \to 0 \quad (n \to \infty). \]
\end{lemma}

n33246.content:
\begin{proof}\leanok
  \uses{natCast_eq_iterate}
  Apply the Birkhoff orbital-tail estimate (a.e.\ \( n^{-1} h(T^{[n]}x) \to 0 \) for integrable
  \( h \)) to \( h = g + g' \) and the time-one map \( T = \varphi(1) \), then rewrite the
  iterate orbit \( (\varphi(1))^{[n]}x \) as \( \varphi(n)x \) using \ref{natCast_eq_iterate}.
\end{proof}

n33249.content:
\begin{lemma}[Fixed-time log-norm is sublinear]\label{ae_tendsto_logNorm_fixedTime_zero}
  \lean{ErgodicTheory.ae_tendsto_logNorm_fixedTime_zero}\leanok
  Fix a real time \( t_0 \). For almost every \( x \), both
  \( n^{-1}\log\left\lVert A(t_0, \varphi(n)x) \right\rVert \) and \( n^{-1}\log\left\lVert (A(t_0, \varphi(n)x))^{-1} \right\rVert \)
  tend to \( 0 \) as \( n \to \infty \).
\end{lemma}

n33251.content:
\begin{theorem}[Shift-invariance of the growth limsup]\label{glim_shift}
  \lean{ErgodicTheory.glim_shift}\leanok
  Fix a real time \( t_0 \). For almost every \( x \) and every test vector \( u \), the
  discrete-time growth \( \limsup \) of the cocycle applied to \( u \) at \( x \) equals that at
  \( \varphi(t_0)x \) applied to the pushed-forward vector \( A(t_0,x)\, u \).
\end{theorem}

n33253.content:
\begin{theorem}[Flow-equivariance of the filtration at every real time]\label{ae_flow_equivariant}
  \lean{ErgodicTheory.ae_flow_equivariant}\leanok
  Let \( V \) be the Oseledets filtration of the time-one data, and fix \( t_0 \in \mathbb{R}\). Then for
  almost every \( x \) and every level \( i \),
  \[ \mathrm{map}\,(A(t_0,x))\,(V_i\, x) = V_i\,(\varphi(t_0)x). \]
\end{theorem}

n33258.content:
\begin{definition}[The invariant suspension probability measure]\label{thm:susp-measure}
  \lean{ErgodicTheory.suspensionMeasure}\leanok
  \uses{thm:susp-space}
  The \emph{suspension measure} $\hat\mu = \operatorname{suspensionMeasure} T\,\tau\,\mu$ is
  obtained by restricting $\mu \times \operatorname{vol}$ to the fundamental box
  $\{(x, s) : 0 \le s < \tau x\}$, pushing forward along $\pi$, and normalising by
  $(\int\tau)^{-1}$. The generator $G$ preserves $\mu \times \operatorname{vol}$ whenever $T$
  preserves $\mu$ (\lean{ErgodicTheory.measurePreserving_suspensionGen}), because the shear is
  a fibered translation and $\mathbb{R}$-translation is Haar-invariant.
\end{definition}

n33259.content:
\begin{theorem}[$\hat\mu$ is a probability measure]\label{thm:susp-prob}
  \lean{ErgodicTheory.isProbabilityMeasure_suspensionMeasure}\leanok
  \uses{thm:susp-measure}
  For a nonnegative integrable roof with $0 < \int\tau$, the normalised suspension measure
  $\hat\mu$ is a probability measure.
\end{theorem}

n33260.content:
\begin{proof}\leanok
  \uses{thm:susp-measure}
  The raw box push-forward has total mass $\int\tau$ (Fubini: the $x$-fibre of the box is
  $[0, \tau x)$, of length $\tau x$), which is positive and finite; multiplying by
  $(\int\tau)^{-1}$ makes the total mass $1$.
\end{proof}

n33261.content:
\begin{definition}[The cover flow cocycle]\label{thm:susp-coverCocycle}
  \lean{ErgodicTheory.coverCocycle}\leanok
  \uses{cocycle}
  For a cover point $p = (x, h)$ the \emph{cover cocycle}
  $\operatorname{coverCocycle} A\,T\,\tau\,(x, h)\,t$ is the cross-section flow cocycle read at
  the total elapsed time $h + t$ from the base point $x$. This is the cover-level form of the
  Cornfeld--Fomin--Sinai special-flow cocycle, one step before the orbit-quotient descent.
\end{definition}

n33262.content:
\begin{lemma}[Agreement on the base section]\label{thm:susp-coverBase}
  \lean{ErgodicTheory.coverCocycle_base}\leanok
  \uses{thm:susp-coverCocycle}
  At height $0$ the cover cocycle is the cross-section flow cocycle:
  $\operatorname{coverCocycle}(x, 0)\,t = \operatorname{flowCocycleSection} t\,x$, since the
  total elapsed time $0 + t$ collapses to $t$.
\end{lemma}

n33263.content:
\begin{proof}\leanok
  \uses{thm:susp-coverCocycle}
  Immediate from the definition on rewriting $0 + t = t$ in the fibre coordinate.
\end{proof}

n33264.content:
\begin{theorem}[Section multiplicativity at a return boundary]\label{thm:susp-coverReturn}
  \lean{ErgodicTheory.coverCocycle_section_returnTime}\leanok
  \uses{thm:susp-coverBase, cocycle}
  Starting on the base section at $x$, the cover cocycle over flow time
  $\operatorname{returnTime} n\,x + r$ (for $0 \le r$) factors as the residual flow over time
  $r$ from the shifted base point $T^n x$, composed on the left of the discrete base cocycle
  for the $n$ completed laps:
  \[
    \operatorname{coverCocycle}(x, 0)\bigl(\operatorname{returnTime} n\,x + r\bigr)
      = \operatorname{coverCocycle}(T^n x, 0)\,r \cdot \operatorname{cocycle} A\,T\,n\,x.
  \]
\end{theorem}

n33268.content:
\begin{theorem}[The Lyapunov-exponent limit transfer]\label{thm:susp-limitTransfer}
  \lean{ErgodicTheory.coverCocycle_suspensionAct_tendsto_exponent}\leanok
  \uses{thm:susp-logDisc}
  If the cover-cocycle growth rate $t^{-1}\log\left\lVert \operatorname{coverCocycle}(x, s)\,t \right\rVert$
  converges to $L$ as $t \to \infty$, the base cocycle is invertible, and both cover-cocycle
  norms are eventually strictly positive, then the growth rate at the re-based orbit point
  $\operatorname{suspensionAct}(n)\,(x, s)$ converges to the \emph{same} $L$.
\end{theorem}

n33269.content:
\begin{proof}\leanok
  \uses{thm:susp-logDisc}
  The per-$t$ average at the re-based point lies within $C/t$ of the average at $(x, s)$, where
  $C$ is the $t$-independent additive discrepancy of \Cref{thm:susp-logDisc}; since
  $C/t \to 0$, a \texttt{Filter.Tendsto} squeeze transfers the limit.
\end{proof}

n33270.content:
\begin{definition}[The flow Lyapunov exponent of an orbit class]\label{thm:susp-hasFlow}
  \lean{ErgodicTheory.HasFlowExponent}\leanok
  \uses{thm:susp-coverCocycle, thm:susp-space}
  $\operatorname{HasFlowExponent} q\,L$ holds when \emph{some} representative $(x, s)$ of the
  orbit class $q \in \Sigma$ carries the cover-cocycle growth rate $L$:
  $\pi(x, s) = q$ and $t^{-1}\log\left\lVert \operatorname{coverCocycle}(x, s)\,t \right\rVert \to L$. The
  existential form lifts cleanly to the quotient; the well-definedness results below show that,
  under base-cocycle invertibility, the rate is in fact the same for every representative.
\end{definition}

n33271.content:
\begin{theorem}[Two-sided well-definedness across a forward step]\label{thm:susp-iffForward}
  \lean{ErgodicTheory.tendsto_exponent_iff_of_suspensionAct}\leanok
  \uses{thm:susp-limitTransfer}
  If $(x_2, s_2) = \operatorname{suspensionAct}(n)\,(x, s)$ for a natural $n$, the base cocycle
  is invertible, and both cover-cocycle norms are eventually strictly positive, then the
  cover-cocycle growth rates at $(x, s)$ and at $(x_2, s_2)$ converge to one and the same $L$:
  the two \texttt{Tendsto} statements are equivalent.
\end{theorem}

n33272.content:
\begin{proof}\leanok
  \uses{thm:susp-limitTransfer}
  The $\to$ direction is \Cref{thm:susp-limitTransfer}. The $\leftarrow$ direction is its mirror:
  the additive $\log$-discrepancy bound of \Cref{thm:susp-logDisc} is symmetric in the two points,
  so the same $1/t$ squeeze transfers the limit the other way.
\end{proof}

n33273.content:
\begin{theorem}[Orbit-class invariance of the flow exponent]\label{thm:susp-classInv}
  \lean{ErgodicTheory.hasFlowExponent_of_suspensionAct}\leanok
  \uses{thm:susp-hasFlow}
  If two cover points are connected by a forward orbit step
  $\operatorname{suspensionAct}(n)\,(x, s) = (x_2, s_2)$, then a growth rate $L$ computed at
  $(x, s)$ witnesses $\operatorname{HasFlowExponent}(\pi(x_2, s_2))\,L$: the exponent is a
  property of the whole orbit class, read off from any representative.
\end{theorem}

n33274.content:
\begin{proof}\leanok
  \uses{thm:susp-hasFlow}
  Orbit-equivalent points have equal $\pi$-images, so $(x, s)$ itself serves as the witness for
  the common class; its growth rate is $L$ by hypothesis. (Invertibility is needed only to
  guarantee the \emph{same} $L$ from the other representative, via \Cref{thm:susp-iffForward}.)
\end{proof}

n33277.content:
\begin{theorem}[The exponent along genuine flow orbits]\label{thm:susp-abramovExpFlow}
  \lean{ErgodicTheory.ae_suspensionMeasure_hasFlowExponent_flowOrbit_of_measurable}\leanok
  \uses{thm:susp-abramovExp}
  Under the same hypotheses (and $T$ measure-preserving), for $\hat\mu$-a.e.\ $q$ there are a base
  point $x$ and a flow time $s$ with $q = \operatorname{suspensionFlow} s\,(\text{section } x)$ and
  $\operatorname{HasFlowExponent} q\,(\lambda_{\mathrm{base}}/\int\tau)$: the exponent is realised
  on the genuine measure-preserving flow orbit of a cross-section point.
\end{theorem}

n33278.content:
\begin{proof}\leanok
  \uses{thm:susp-abramovExp}
  The disintegration already identifies each a.e.\ class with a flow-orbit point of the base
  section; carry that identification alongside the exponent conclusion of
  \Cref{thm:susp-abramovExp}.
\end{proof}

n33279.content:
\begin{lemma}[Strict positivity under global invertibility]\label{thm:susp-normPos}
  \lean{ErgodicTheory.coverCocycle_norm_pos}\leanok
  \uses{thm:susp-coverCocycle}
  If the base generator $A$ is everywhere invertible ($\det \ne 0$), then
  $0 < \left\lVert \operatorname{coverCocycle} p\,t \right\rVert$ for every cover point $p$ and time $t$: the cover
  cocycle reduces to a base-cocycle iterate whose norm is strictly positive.
\end{lemma}

n33280.content:
\begin{proof}\leanok
  \uses{thm:susp-coverCocycle}
  Unfold the cover cocycle to $\operatorname{cocycle} A\,T\,(\text{lap count})\,x$, a product of
  invertible matrices, hence nonzero with positive operator norm.
\end{proof}

n33281.content:
\begin{theorem}[Signed-step cross-representative uniqueness]\label{thm:susp-iffSigned}
  \lean{ErgodicTheory.tendsto_exponent_iff_of_orbitRel}\leanok
  \uses{thm:susp-iffForward, thm:susp-normPos}
  If two cover points are connected by a \emph{signed} orbit step
  $\operatorname{suspensionAct} m\,(x_2, s_2) = (x_1, s_1)$ for $m \in \mathbb{Z}$, and the base cocycle is
  everywhere invertible, then the cover-cocycle growth rates at $(x_1, s_1)$ and $(x_2, s_2)$
  converge to the same $L$.
\end{theorem}

n33283.content:
\begin{definition}[The representative-level and descended exponents]\label{thm:susp-flowExpAt}
  \lean{ErgodicTheory.flowExponentAt}\leanok
  \uses{thm:susp-iffSigned}
  $\operatorname{repExponent} p$ (\lean{ErgodicTheory.repExponent}) is the growth-rate limit
  $\lim_t t^{-1}\log\left\lVert \operatorname{coverCocycle} p\,t \right\rVert$ read off from a representative, with a
  fixed junk value $0$ off the convergence locus (a plain $\texttt{dite}$/$\texttt{choose}$ rather
  than $\texttt{limUnder}$, whose junk is not constant across representatives).
  $\operatorname{flowExponentAt} : \Sigma \to \mathbb{R}$ is its $\texttt{Quotient.lift}$, made total by
  global base-cocycle invertibility.
\end{definition}

n33284.content:
\begin{theorem}[$\operatorname{flowExponentAt}$ reads off the exponent]\label{thm:susp-flowExpEq}
  \lean{ErgodicTheory.flowExponentAt_eq_of_hasFlowExponent}\leanok
  \uses{thm:susp-flowExpAt, thm:susp-hasFlow}
  If $q$ carries the flow exponent $L$ (some representative has cover-cocycle growth rate $L$),
  then $\operatorname{flowExponentAt} q = L$.
\end{theorem}

n33285.content:
\begin{proof}\leanok
  \uses{thm:susp-flowExpAt}
  Well-definedness of the lift (\Cref{thm:susp-iffSigned}) transfers existence of the limit across
  any orbit step; where it exists on both sides, uniqueness of limits forces the two values to
  agree, so the descended value equals the witnessing $L$.
\end{proof}

n33286.content:
\begin{theorem}[The representative-free Abramov exponent]\label{thm:susp-flowExpAe}
  \lean{ErgodicTheory.ae_flowExponentAt_eq_base_div_roof}\leanok
  \uses{thm:susp-flowExpEq, thm:susp-abramovExp}
  Under a bounded roof, positive $\int\tau$, measurable base generator, global invertibility
  $\forall x,\ \det(A x) \ne 0$, and the base-a.e.\ Birkhoff limits, for $\hat\mu$-almost every
  orbit class $q$ the genuine (representative-free) flow exponent equals
  $\lambda_{\mathrm{base}}/\int\tau$:
  $\operatorname{flowExponentAt} q = \lambda_{\mathrm{base}}/\int\tau$.
\end{theorem}

n33287.content:
\begin{proof}\leanok
  \uses{thm:susp-flowExpEq, thm:susp-abramovExp}
  Combine the existential a.e.\ exponent of \Cref{thm:susp-abramovExp} with the read-off equality
  \Cref{thm:susp-flowExpEq}; the added global-invertibility hypothesis is the documented honest
  cost of upgrading the predicate to the actual lifted value.
\end{proof}

n33288.content:
\begin{theorem}[The cat suspension realises the base derivative-cocycle exponent]\label{thm:susp-catHasFlow}
  \lean{ErgodicTheory.CatMapToral.catSuspension_ae_hasFlowExponent}\leanok
  \uses{thm:susp-abramovExp, catTorus_constCocycle_exponents, derivativeCocycle}
  For $\hat\mu$-a.e.\ orbit class $q$ of the cat-map suspension under the unit roof, the flow
  Lyapunov exponent of the base's own derivative cocycle is
  $\operatorname{HasFlowExponent} q\ \bigl(\log((3+\sqrt5)/2)\bigr) = \lambda_{\mathrm{base}}/\int\tau$.
\end{theorem}

n33290.content:
\begin{theorem}[Positivity of the cat suspension exponent (issue \#30)]\label{thm:susp-catPos}
  \lean{ErgodicTheory.CatMapToral.catSuspensionFlow_ownExponent_pos}\leanok
