n33302.content:
\begin{theorem}[Mixing kills eigenvalues]\label{thm:susp-eigZero}
  \lean{ErgodicTheory.eigenfunction_ae_zero_of_mixing}\leanok
  A measurable eigenfunction $g$ (with $g \circ f = l\,g$) of a strongly-mixing transformation $f$,
  whose eigenvalue $l$ is unimodular ($\left\lVert l \right\rVert = 1$) but $l \ne 1$, vanishes almost everywhere.
\end{theorem}

n33305.content:
\begin{theorem}[The twisted eigenfunction relation]\label{thm:susp-twist}
  \lean{ErgodicTheory.coeffFn_twist}\leanok
  \uses{thm:susp-coeffFn}
  If $F$ is $1$-periodic in the fibre and satisfies the deck identity $F(Tx, s) = F(x, s + r)$, then
  \[
    \operatorname{coeffFn} F\,n\,(Tx) = e^{2\pi i n r}\,\operatorname{coeffFn} F\,n\,x.
  \]
\end{theorem}

n33306.content:
\begin{proof}\leanok
  \uses{thm:susp-coeffFn}
  A three-step change of variables over the unit window: character algebra factoring out
  $e^{2\pi i n r}$, the translation $\int_0^1 G(s + r)\,ds = \int_r^{1+r} G$, and
  $1$-periodicity of $G$ to return the window to $[0, 1]$.
\end{proof}

n33307.content:
\begin{theorem}[Per-fibre Parseval bridge]\label{thm:susp-parseval}
  \lean{ErgodicTheory.parseval_bridge}\leanok
  For a bounded measurable $f : \mathbb{R}\to \mathbb{C}$, the squared fibre-coefficient sum equals the fibre
  $L^2$ mass: $\sum_{n \in \mathbb{Z}}\left\lVert \operatorname{coeffFn}(f)\,n \right\rVert^2 = \int_0^1\left\lVert f \right\rVert^2$.
\end{theorem}

n33309.content:
\begin{theorem}[Indicator dichotomy]\label{thm:susp-dichotomy}
  \lean{ErgodicTheory.fibre_indicator_dichotomy}\leanok
  \uses{thm:susp-parseval}
  Let $g : \mathbb{R}\to \mathbb{R}$ be measurable, $1$-periodic, $\{0, 1\}$-valued, with all nonzero-mode Fourier
  coefficients (over period $1$) vanishing. Then $g = 0$ a.e.\ on $(0, 1]$ or $g = 1$ a.e.\ on
  $(0, 1]$.
\end{theorem}

n33311.content:
\begin{theorem}[Time-one ergodicity, abstract base-generic form (issue \#35)]\label{thm:susp-timeOneErgodic}
  \lean{ErgodicTheory.ergodic_suspensionFlowMap_one_const_roof}\leanok
  \uses{thm:susp-twist, thm:susp-dichotomy, thm:susp-prob}
  Let $T$ be ergodic and measure-preserving on a probability space whose only measurable
  eigenfunction with a unimodular eigenvalue $\ne 1$ is $0$. For a positive \emph{irrational} roof
  $r$, the time-$1$ map of the constant-roof suspension flow is ergodic for $\hat\mu$.
\end{theorem}

n33313.content:
\begin{theorem}[Time-one ergodicity of the irrational-roof Bernoulli suspension]\label{thm:susp-bernTimeOne}
  \lean{ErgodicTheory.Multifractal.ergodic_suspensionFlow_timeOne_const_irrational}\leanok
  \uses{thm:susp-timeOneErgodic, thm:susp-bernMixing, thm:susp-eigZero}
  For the two-sided Bernoulli shift with measure $\operatorname{bernZ}\nu$ and any positive
  irrational roof $r$, the time-$1$ map of the constant-roof suspension flow is ergodic for the
  invariant suspension probability measure.
\end{theorem}

n33315.content:
\begin{theorem}[Concrete non-vacuity witness $r = \sqrt2$]\label{thm:susp-sqrt2}
  \lean{ErgodicTheory.Multifractal.ergodic_suspensionFlow_timeOne_sqrtTwo}\leanok
  \uses{thm:susp-bernTimeOne}
  The irrational roof $r := \sqrt2$ yields an ergodic time-$1$ map, confirming the hypothesis
  $\operatorname{Irrational} r$ is satisfiable.
\end{theorem}

n33317.content:
\begin{theorem}[Non-ergodicity at the unit roof]\label{thm:susp-notErgodic}
  \lean{ErgodicTheory.Multifractal.not_ergodic_bernSuspensionFlow_one}\leanok
  \uses{bernSuspensionFlow}
  The time-$1$ map of the \emph{unit-roof} Bernoulli suspension flow is \emph{not} ergodic.
\end{theorem}

n33319.content:
\begin{theorem}[Discrete entropy power rule]\label{thm:susp-ksPow}
  \lean{ErgodicTheory.Entropy.ksEntropy_iterate}\leanok
  \uses{ksEntropy}
  For a measure-preserving $T$ on a probability space and $n \in \mathbb{N}$, $h(T^n) = n \cdot h(T)$.
\end{theorem}

n33320.content:
\begin{proof}\leanok
  \uses{ksEntropy}
  Walters, \emph{An Introduction to Ergodic Theory}, Theorem 4.13. The $n$-fold refinement of a
  partition under $T^n$ is a subsequence of the refinement under $T$, and the Fekete limit along
  the arithmetic progression $kn$ equals $n$ times the full limit.
\end{proof}

n33321.content:
\begin{theorem}[Flow iterate identity]\label{thm:susp-flowIter}
  \lean{ErgodicTheory.flow_iterate}\leanok
  For a measure-preserving flow $\varphi$, the $n$-th iterate of the time-$t$ map is the
  time-$(nt)$ map: $(\varphi_t)^{[n]} = \varphi_{nt}$.
\end{theorem}

n33322.content:
\begin{proof}\leanok
  Induction on $n$ using $\varphi_{s+t} = \varphi_s \circ \varphi_t$ and the iterate recursion.
\end{proof}

n33323.content:
\begin{theorem}[Flow entropy homogeneity along $\mathbb{N}$-multiples]\label{thm:susp-nsmulKs}
  \lean{ErgodicTheory.nsmul_ksEntropy_flow}\leanok
  \uses{thm:susp-ksPow, thm:susp-flowIter}
  For a measure-preserving flow $\varphi$ on a probability space,
  $n \cdot h(\varphi_t) = h(\varphi_{nt})$.
\end{theorem}

n33324.content:
\begin{proof}\leanok
  \uses{thm:susp-ksPow, thm:susp-flowIter}
  Apply the power rule \Cref{thm:susp-ksPow} to $T = \varphi_t$, whose $n$-th iterate is
  $\varphi_{nt}$ by \Cref{thm:susp-flowIter}; entropy depends only on the underlying map.
\end{proof}

n33325.content:
\begin{definition}[The fibre-rescaling equivalence]\label{thm:susp-rescale}
  \lean{ErgodicTheory.suspensionRescale}\leanok
  \uses{thm:susp-space}
  The fibre map $(x, s) \mapsto (x, s/r)$ descends to a measurable equivalence
  $\operatorname{suspensionRescale} : \operatorname{SuspensionSpace} T\,(\tau \equiv r) \simeq
  \operatorname{SuspensionSpace} T\,(\tau \equiv 1)$, conjugating the constant-$r$ generator
  $(x, s) \mapsto (Tx, s - r)$ to the unit generator $(x, s) \mapsto (Tx, s - 1)$ (since
  $(s - r)/r = s/r - 1$). It is the constant-roof case of the Ambrose--Kakutani/Abramov time-change.
\end{definition}

n33326.content:
\begin{theorem}[The time-$r$ entropy conjugacy]\label{thm:susp-rescaleKs}
  \lean{ErgodicTheory.ksEntropy_suspensionFlowMap_const_eq_unit}\leanok
  \uses{thm:susp-rescale}
  The time-$t$ map of the constant-$r$ suspension flow has the same Kolmogorov--Sinai entropy as the
  time-$(t/r)$ map of the unit-roof suspension flow.
\end{theorem}

n33328.content:
\begin{theorem}[Time-$r$ entropy of the Bernoulli suspension]\label{thm:susp-timeRBern}
  \lean{ErgodicTheory.ksEntropy_bernConstSuspension_time_r}\leanok
  \uses{thm:susp-rescaleKs, ksEntropy_bernSuspensionFlow_one_eq_Hnu}
  For the constant-roof ($\tau \equiv r$) suspension of the two-sided Bernoulli shift, the time-$r$
  map has Kolmogorov--Sinai entropy exactly the per-symbol Shannon entropy $H_\nu$.
\end{theorem}

n33329.content:
\begin{proof}\leanok
  \uses{thm:susp-rescaleKs}
  \Cref{thm:susp-rescaleKs} at $t = r$ (so $t/r = 1$) reduces to the unit-roof time-$1$ value
  $h(\zeta^{(1)}_1) = H_\nu$ (\Cref{ksEntropy_bernSuspensionFlow_one_eq_Hnu}).
\end{proof}

n33330.content:
\begin{theorem}[Constant-roof time-one entropy, rational roof (issue \#38)]\label{thm:susp-timeOneEntropy}
  \lean{ErgodicTheory.ksEntropy_bernConstSuspension_time_one}\leanok
  \uses{thm:susp-nsmulKs, thm:susp-rescaleKs, ksEntropy_bernSuspensionFlow_one_eq_Hnu}
  For a \emph{rational} roof $r = a/b$ ($a, b \in \mathbb{N}$ positive), the time-$1$ map of the
  constant-roof Bernoulli suspension flow has Kolmogorov--Sinai entropy $H_\nu/r$.
\end{theorem}

n33332.content:
\begin{theorem}[Multiplicative form]\label{thm:susp-timeOneEntropyMul}
  \lean{ErgodicTheory.ksEntropy_bernConstSuspension_time_one_mul}\leanok
  \uses{thm:susp-timeOneEntropy}
  For a rational roof $r = a/b$, $\;h(\zeta^{(r)}_1) \cdot r = H_\nu$.
\end{theorem}

n33333.content:
\begin{proof}\leanok
  \uses{thm:susp-timeOneEntropy}
  Multiply the value form \Cref{thm:susp-timeOneEntropy} by $r$; the product
  $(H_\nu/r) \cdot r = H_\nu$ is real arithmetic.
\end{proof}

n33334.content:
\begin{definition}[Measure-continuity of a flow]\label{def:flow-measCont}
  \lean{ErgodicTheory.MeasurePreservingFlow.MeasureContinuous}\leanok
  A measure-preserving flow $\varphi$ is \emph{measure-continuous} if for every measurable set $A$
  the real measure of the symmetric difference $\varphi_t^{-1} A \,\triangle\, A$ tends to $0$ as
  $t \to 0$.
\end{definition}

n33335.content:
\begin{theorem}[Measure-continuity of the suspension flow]\label{thm:flow-suspMeasCont}
  \lean{ErgodicTheory.tendsto_measureReal_symmDiff_suspensionFlowMap}\leanok
  \uses{bernSuspensionFlow}
  The unit-roof suspension flow of an \emph{arbitrary} measure-preserving base is measure-continuous:
  for every measurable $A$, $\mu\!\left(\varphi_t^{-1} A \,\triangle\, A\right) \to 0$ as $t \to 0$.
  This is the keystone hypothesis; the Bernoulli suspension flow instantiates it
  (\lean{ErgodicTheory.measureContinuous_bernSuspensionFlow}).
\end{theorem}

n33337.content:
\begin{theorem}[Ito's L1: the partition moves little under a small shift]\label{thm:flow-L1}
  \lean{ErgodicTheory.condEntropyGivenPartition_flow_tendsto_zero}\leanok
  \uses{def:flow-measCont}
  For a measure-continuous flow and a finite partition $P$, the conditional Shannon entropy
  $H(\varphi_t P \mid P) \to 0$ as $t \to 0$ (Ito's (2.2)).
\end{theorem}

n33338.content:
\begin{proof}\leanok
  \uses{def:flow-measCont}
  The self-conditioning $H(P \mid P) = 0$, and the cell measures $\mu(\varphi_t^{-1}P_i \cap P_j)$
  are continuous at $t = 0$ by measure-continuity; continuity of the Shannon cell functional
  transports the limit.
\end{proof}

n33339.content:
\begin{theorem}[Two-family Shannon comparison]\label{thm:flow-finJoin}
  \lean{ErgodicTheory.Entropy.entropy_finJoin_le_add_sum_condEntropy}\leanok
  For two finite families $\beta = (\beta_k)$, $\gamma = (\gamma_k)$ of finite partitions,
  $H\!\left(\bigvee_k \gamma_k\right) \le H\!\left(\bigvee_k \beta_k\right)
  + \sum_k H(\gamma_k \mid \beta_k)$.
\end{theorem}

n33341.content:
\begin{theorem}[$\varepsilon$--$\delta$ alignment proposition]\label{thm:flow-ratioLUB}
  \lean{ErgodicTheory.exists_isLUB_ksEntropyPartition_flow_ratio}\leanok
  \uses{def:flow-measCont, thm:flow-L1, thm:flow-finJoin}
  For a measure-continuous flow on a standard Borel space and a finite partition $P$, the ratio
  $t \mapsto h(\varphi_t, P)/t$ converges as $t \downarrow 0$ to its least upper bound
  $L \in \overline{\mathbb{R}}$ over all positive times. The statement is genuinely in $\overline{\mathbb{R}}$: the
  $\mathbb{R}$-valued form is false for infinite-entropy flows, and this repair is disclosed in-module.
\end{theorem}

n33342.content:
\begin{proof}\leanok
  \uses{thm:flow-L1, thm:flow-finJoin}
  The alignment inequality (from \Cref{thm:flow-L1} and \Cref{thm:flow-finJoin}) makes each slope
  eventually dominate every value below the supremum; the supremum is thus the limit.
\end{proof}

n33343.content:
\begin{theorem}[Abstract Abramov homogeneity]\label{thm:flow-abramov-hom}
  \lean{ErgodicTheory.ksEntropy_flow_eq_mul}\leanok
  \uses{thm:flow-ratioLUB, thm:susp-nsmulKs}
  For a measure-continuous measure-preserving flow $\varphi$ on a standard Borel probability space
  and $t > 0$, $\;h(\varphi_t) = t \cdot h(\varphi_1)$ in $\overline{\mathbb{R}}$.
\end{theorem}

n33344.content:
\begin{proof}\leanok
  \uses{thm:flow-ratioLUB, thm:susp-nsmulKs}
  Interchange the supremum over partitions with the alignment proposition
  (\Cref{thm:flow-ratioLUB}), using the discrete $\mathbb{N}$-homogeneity (\Cref{thm:susp-nsmulKs}); at
  $t = 1$ the slope is $h(\varphi_1)$, giving the stated multiple.
\end{proof}

n33345.content:
\begin{theorem}[Unit-roof time-$s$ entropy, all $s > 0$]\label{thm:flow-timeS}
  \lean{ErgodicTheory.ksEntropy_bernSuspensionFlow_time_s_eq}\leanok
  \uses{thm:flow-abramov-hom, ksEntropy_bernSuspensionFlow_one_eq_Hnu}
  For the unit-roof Bernoulli suspension flow and every $s > 0$,
  $h(\zeta^{(1)}_s) = s \cdot H_\nu$.
\end{theorem}

n33346.content:
\begin{proof}\leanok
  \uses{thm:flow-abramov-hom}
  \Cref{thm:flow-abramov-hom} for the measure-continuous Bernoulli suspension flow, at the finite
  value $h(\zeta^{(1)}_1) = H_\nu$.
\end{proof}

n33347.content:
\begin{theorem}[Constant-roof time-one entropy, all roofs (issue \#48)]\label{thm:flow-timeOneAll}
  \lean{ErgodicTheory.ksEntropy_bernConstSuspension_time_one_irrational}\leanok
  \uses{thm:flow-timeS}
  For \emph{every} roof $r > 0$ (irrational included), the time-$1$ map of the constant-roof
  Bernoulli suspension flow has Kolmogorov--Sinai entropy $H_\nu/r$.
\end{theorem}

n33348.content:
\begin{proof}\leanok
  \uses{thm:flow-timeS}
  Fibre time-rescaling reduces $h(\zeta^{(r)}_1)$ to the unit-roof $h(\zeta^{(1)}_{1/r})$;
  \Cref{thm:flow-timeS} at $s = 1/r$ gives $(1/r)\,H_\nu = H_\nu/r$.
\end{proof}

n33349.content:
\begin{definition}[The two-sided $\mathbb{Z}$-indexed matrix cocycle]\label{cocycleZ}
  \lean{ErgodicTheory.cocycleZ}\leanok
  \uses{FlowCocycle}
  Over an invertible measure-preserving base $T : X \simeq X$, the one-sided iterated cocycle
  (indexed by $\mathbb{N}$) extends to a two-sided $\mathbb{Z}$-indexed cocycle $\operatorname{cocycleZ} A\,T\,n$: for
  $n \ge 0$ the forward cocycle, and for $n < 0$ the backward cocycle of the inverse dynamics with
  generator $x \mapsto (A(T^{-1}x))^{-1}$.
\end{definition}

n33350.content:
\begin{theorem}[The two-sided cocycle identity]\label{cocycleZ_add}
  \lean{ErgodicTheory.cocycleZ_add}\leanok
  \uses{cocycleZ}
  $\operatorname{cocycleZ}(m + n)\,x = \operatorname{cocycleZ} m\,(\operatorname{baseIter} n\,x)
  \cdot \operatorname{cocycleZ} n\,x$, where $\operatorname{baseIter}$ is the $\mathbb{Z}$-iterate of the
  base. This is the keystone that lets the discrete object assemble into a continuous-time cocycle.
\end{theorem}

n33351.content:
\begin{definition}[The genuine quotient flow cocycle]\label{quotientFlowCocycle}
  \lean{ErgodicTheory.quotientFlowCocycle}\leanok
  \uses{cocycleZ, FlowCocycle}
  For the constant unit roof, reading off a measurable canonical representative
  $\operatorname{unitFwd} q = (\operatorname{baseIter}\lfloor s\rfloor x, \{s\})$ of each orbit class
  $q = [x,s]$, the assignment $t \mapsto \operatorname{cocycleZ} A\,T\,\lfloor \{s\} + t\rfloor\,
  (\operatorname{unitFwd} q)_1$ is a genuine \Cref{FlowCocycle} on the mapping torus. The four cocycle
  fields follow from \Cref{cocycleZ_add} transported through the floor split
  $\lfloor a + t\rfloor = \lfloor a\rfloor + \lfloor \{a\} + t\rfloor$.
\end{definition}

n33352.content:
\begin{theorem}[Cohomology to the cover cocycle]\label{exists_flowCocycle_cohomologous_to_cover}
  \lean{ErgodicTheory.exists_flowCocycle_cohomologous_to_cover}\leanok
  \uses{quotientFlowCocycle, thm:susp-coverCocycle}
  Over the quotient, \Cref{quotientFlowCocycle} is cohomologous to the cover cocycle
  (\Cref{thm:susp-coverCocycle}): at a general representative $(x,s)$ with $0 \le s$ the two differ
  by the measurable \emph{rep-level frame} $C(x,s) = \operatorname{cocycleZ} A\,T\,\lfloor s\rfloor
  x$. Because different representatives of one class carry different $\lfloor s\rfloor$, the issue's
  schematic \emph{class}-level conjugacy is provably impossible; the honest general statement is this
  rep-level frame, collapsing to the conjugation-free canonical identity at $\operatorname{unitFwd}$.
\end{theorem}

n33353.content:
\begin{proof}\leanok
  \uses{quotientFlowCocycle, cocycleZ_add}
  Take $B = \operatorname{quotientFlowCocycle}$ and $C(p) = \operatorname{cocycleZ} A\,T
  \lfloor p_2\rfloor p_1$; measurability of $C$ is the composition of $\lfloor \cdot\rfloor$ with the
  measurable-in-index cocycle, and the frame identity is the floor split of \Cref{cocycleZ_add}.
\end{proof}

n33354.content:
\begin{theorem}[Exponent transport]\label{flowExponentAt_quotientFlowCocycle}
  \lean{ErgodicTheory.flowExponentAt_quotientFlowCocycle}\leanok
  \uses{quotientFlowCocycle, thm:susp-flowExpAt}
  Along the $\operatorname{atTop}$ half-line $0 \le t$, the growth rate of \Cref{quotientFlowCocycle}
  equals the descended flow exponent $\operatorname{flowExponentAt}$ (\Cref{thm:susp-flowExpAt}).
\end{theorem}

n33355.content:
\begin{definition}[The cat map's quotient flow cocycle]\label{catQuotientFlowCocycle}
  \lean{ErgodicTheory.CatMapToral.catQuotientFlowCocycle}\leanok
  \uses{quotientFlowCocycle, catTorus}
  Instantiating \Cref{quotientFlowCocycle} at the Arnold cat map \Cref{catTorus} under the constant
  unit roof, with base generator the cat map's own derivative cocycle (the constant hyperbolic
  matrix $\operatorname{cat}_{\mathbb{R}}$), yields a genuine \Cref{FlowCocycle} on the cat suspension.
\end{definition}

n33356.content:
\begin{theorem}[The cat quotient flow-cocycle Lyapunov exponent]\label{catQuotientFlowCocycle_exponent}
  \lean{ErgodicTheory.CatMapToral.catQuotientFlowCocycle_exponent}\leanok
  \uses{catQuotientFlowCocycle, flowExponentAt_quotientFlowCocycle, thm:susp-catFlowExpEq}
  For $\hat\mu$-a.e.\ orbit class $q$, the growth rate of \Cref{catQuotientFlowCocycle} converges to
  the flow Lyapunov exponent $\log\!\big((3+\sqrt5)/2\big)$ --- the log of the cat matrix's top
  eigenvalue.
\end{theorem}

n33357.content:
\begin{proof}\leanok
  \uses{flowExponentAt_quotientFlowCocycle, thm:susp-catFlowExpEq}
  Chain the descended cat-suspension exponent (\Cref{thm:susp-catFlowExpEq}) through the
  exponent-transport \Cref{flowExponentAt_quotientFlowCocycle}.
\end{proof}

n33360.content:
\begin{theorem}[$\operatorname{embDist}$ is a metric]\label{embDist_triangle}
  \lean{ErgodicTheory.embDist_triangle}\leanok
  \uses{embDist}
  $\operatorname{embDist}$ satisfies the triangle inequality and separates points
  (\lean{ErgodicTheory.embDist_eq_zero}): the two test parts descend from the sup-norm triangle
  inequality of $X \to^{b} \mathbb{R}$, the height part from the $\mathbb{R}/\mathbb{Z}$ quotient metric, and a $2\times 2$
  linear solve on the two weightings recovers the base point from a vanishing distance. It is
  bi-Lipschitz to the route gauge $\operatorname{routeDist}$.
\end{theorem}

n33361.content:
\begin{proof}\leanok
  \uses{embDist}
  The Kuratowski map is an isometry into $X \to^{b} \mathbb{R}$, so both test distances are genuine metrics;
  the height gauge $\operatorname{hgt}$ is the standard circle metric. Their sum inherits symmetry, the
  triangle inequality and nonnegativity; zero distance forces equal heights (height part) and, at the
  common height, equal Kuratowski images through the two weightings (test parts), hence $x = y$.
\end{proof}

n33362.content:
\begin{theorem}[Metric-space topology and Polishness]\label{suspensionPolish}
  \lean{ErgodicTheory.suspensionPolish}\leanok
  \uses{embDist_triangle, thm:susp-space}
  For a compact metric base $X$ with $\operatorname{diam} X\le 1$ and a homeomorphism $T$, the
  $\operatorname{embDist}$ metric induces exactly the quotient topology
  (\lean{ErgodicTheory.suspensionMetricSpace}, via $\texttt{MetricSpace.ofDistTopology}$), under which
  the suspension space is compact, complete and separable --- hence \emph{Polish}.
\end{theorem}

n33364.content:
\begin{theorem}[The flow is Lipschitz in time]\label{embDist_flow_le}
  \lean{ErgodicTheory.embDist_flow_le}\leanok
  \uses{embDist}
  The suspension flow is $5$-Lipschitz in the time parameter along each orbit:
  $\operatorname{embDist}(\zeta_a q, \zeta_b q)\le 5\,\left\lvert a - b \right\rvert$.
\end{theorem}

n33365.content:
\begin{proof}\leanok
  \uses{embDist}
  Both flowed points share the base coordinate of the canonical representative; the height advances by
  $a - b$, so the height gauge contributes $\le\left\lvert a-b \right\rvert$ and each test bundle at most twice that,
  totalling the $5\left\lvert a-b \right\rvert$ bound (with the seam-wrap regime handled by the vertical/step estimates).
\end{proof}

n33366.content:
\begin{definition}[The variable-roof embedding metric]\label{embDistVar}
  \lean{ErgodicTheory.embDistVar}\leanok
  \uses{embDist}
  For a roof $\tau\ge\rho_{\min} > 0$, the canonical box representative
  $\operatorname{suspensionRepVar}$ (\lean{ErgodicTheory.suspensionRepVar}) is the unique orbit
  representative in $\{(x,s) : 0\le s < \tau x\}$ (the roof-cocycle is strictly increasing with gaps
  $\ge\rho_{\min}$, so it partitions $\mathbb{R}$), and $\operatorname{normHeightVar}$
  (\lean{ErgodicTheory.normHeightVar}) is its normalized height $s/\tau x$. The metric
  $\operatorname{embDistVar}$ is the constant-roof sum evaluated at the \emph{normalized}
  representatives; it is a genuine metric (\lean{ErgodicTheory.embDistVar_triangle}).
\end{definition}

n33367.content:
\begin{theorem}[Variable-roof flow-Lipschitz bound]\label{embDistVar_flow_le}
  \lean{ErgodicTheory.embDistVar_flow_le}\leanok
  \uses{embDistVar}
  The realisation cost of the variable roof appears only in the flow-Lipschitz constant: the flow
  moves the raw height at unit speed, hence the normalized height at speed $1/\tau\le 1/\rho_{\min}$,
  giving $\operatorname{embDistVar}(\zeta_a q, \zeta_b q)\le(5/\rho_{\min})\,\left\lvert a - b \right\rvert$.
\end{theorem}

n33368.content:
\begin{proof}\leanok
  \uses{embDistVar}
  Repeat the constant-roof estimate \Cref{embDist_flow_le} on the normalized coordinate, where the
  time increment $a - b$ is scaled by $1/\tau x\le 1/\rho_{\min}$ before entering the height and test
  gauges.
\end{proof}

n33369.content:
\begin{definition}[The descended suspension factor map]\label{suspensionFactorMap}
  \lean{ErgodicTheory.suspensionFactorMap}\leanok
  \uses{thm:susp-space}
  For measurable automorphisms \(T : X\simeq X\), \(S : Y\simeq Y\) with unit roofs and a base factor
  map \(\pi : X\to Y\) (measurable, \(\pi\circ T = S\circ\pi\)), the fibrewise raw map
  \((x,s)\mapsto(\pi x, s)\) on \(X\times\mathbb{R}\) descends through the two orbit quotients to
  \(\operatorname{suspensionFactorMap} : \widehat X\to\widehat Y\), \([x,s]\mapsto[\pi x, s]\).
\end{definition}

n33374.content:
\begin{lemma}[Entropy is at most \(\log k\)]\label{entropy_le_log_card_partition}
  \lean{ErgodicTheory.Entropy.entropy_le_log_card_partition}\leanok
  \uses{entropy, MeasurePartition}
  A finite measurable partition of a probability space into \(k\) cells (with \(k\ge 1\)) has
  Shannon entropy at most \(\log k\).
\end{lemma}

n33376.content:
\begin{theorem}[Subadditivity under joins]\label{entropy_join_le}
  \lean{ErgodicTheory.Entropy.entropy_join_le}\leanok
  \uses{entropy, MeasurePartition}
  For two finite measurable partitions \(\alpha=(A_i)\) and \(\beta=(B_j)\) of a probability
  space, the entropy of the \emph{join} (common refinement) \(\alpha\vee\beta\), whose cell
  family
  \lean{ErgodicTheory.Entropy.joinCells}
  at \((i,j)\) is the intersection \(A_i\cap B_j\), satisfies
  \[
    H(\alpha\vee\beta) \;\le\; H(\alpha) + H(\beta).
  \]
\end{theorem}

n33377.content:
\begin{proof}\leanok
  \uses{entropy, MeasurePartition}
  The discrete Gibbs inequality \(\sum_x p_x\log p_x \ge \sum_x p_x\log q_x\) (proved termwise
  from \(\log(q/p)\le q/p-1\)) is applied to the joint distribution \(p_{(i,j)}=\mu(A_i\cap B_j)\)
  and the product distribution \(q_{(i,j)}=\mu(A_i)\mu(B_j)\). The marginal identities
  \(\sum_j p_{(i,j)}=\mu(A_i)\) and \(\sum_i p_{(i,j)}=\mu(B_j)\) make both vectors probability
  vectors and expand \(-\sum p_{(i,j)}\log q_{(i,j)}\) into exactly \(H(\alpha)+H(\beta)\).
\end{proof}

n33378.content:
\begin{lemma}[Invariance under a measure-preserving pullback]\label{entropy_pullback}
  \lean{ErgodicTheory.Entropy.entropy_pullback}\leanok
  \uses{entropy, MeasurePartition}
  For a measure-preserving \(T\) and a finite measurable partition \(\beta\), the \emph{pullback
  partition} \(T^{-1}\beta\)
  \lean{ErgodicTheory.Entropy.MeasurePartition.pullback}
  with cells \(T^{-1}B_j\) has the same Shannon entropy as \(\beta\):
  \(H(T^{-1}\beta)=H(\beta)\).
\end{lemma}

n33379.content:
\begin{proof}\leanok
  \uses{entropy, MeasurePartition}
  Each cell measure is preserved, \(\mu(T^{-1}B_j)=\mu(B_j)\), so the corresponding \(\eta\)-terms
  agree summand by summand.
\end{proof}

n33381.content:
\begin{theorem}[Conditioning does not increase entropy]\label{condEntropy_le}
  \lean{ErgodicTheory.Entropy.condEntropy_le}\leanok
  \uses{condEntropyPartition, MeasurePartition}
  For any finite measurable partition \(P\) of a standard Borel probability space and any
  sub-\(\sigma\)-algebra \(\mathcal A\le m_\alpha\),
  \[
    H(P \mid \mathcal A) \;\le\; H(P).
  \]
\end{theorem}

n33384.content:
\begin{definition}[Iterated-join entropy sequence]\label{ksEntropySeq}
  \lean{ErgodicTheory.Entropy.ksEntropySeq}\leanok
  \uses{ksJoin, entropy}
  The \emph{iterated-join entropy sequence} of \((T,\alpha)\) is
  \[
    n \;\longmapsto\; H\Bigl(\bigvee_{k=0}^{n-1}T^{-k}\alpha\Bigr),
  \]
  the Shannon entropy of the flat \(n\)-fold join. Its term at \(0\) is \(0\), and every term is
  nonnegative.
\end{definition}

n33385.content:
\begin{theorem}[Subadditivity of the entropy sequence]\label{ksEntropySeq_subadditive}
  \lean{ErgodicTheory.Entropy.ksEntropySeq_subadditive}\leanok
  \uses{ksEntropySeq, entropy_join_le, entropy_pullback}
  For a measure-preserving \(T\) on a probability space and all \(n,m\),
  \[
    H\Bigl(\bigvee_{k=0}^{n+m-1}T^{-k}\alpha\Bigr) \;\le\;
      H\Bigl(\bigvee_{k=0}^{n-1}T^{-k}\alpha\Bigr) + H\Bigl(\bigvee_{k=0}^{m-1}T^{-k}\alpha\Bigr).
  \]
\end{theorem}

n33388.content:
\begin{theorem}[Fekete convergence]\label{tendsto_ksEntropySeq}
  \lean{ErgodicTheory.Entropy.tendsto_ksEntropySeq}\leanok
  \uses{ksEntropyPartition, ksEntropySeq_subadditive}
  The averaged iterated-join entropies converge:
  \(\frac1n H\bigl(\bigvee_{k<n}T^{-k}\alpha\bigr)\to h(T,\alpha)\) as \(n\to\infty\).
\end{theorem}

n33389.content:
\begin{proof}\leanok
  \uses{ksEntropyPartition, ksEntropySeq_subadditive, ksEntropySeq}
  Fekete's subadditivity lemma (\(\texttt{Subadditive.tendsto\_lim}\)) applied to the sequence of
  \Cref{ksEntropySeq_subadditive}; its boundedness-below hypothesis is discharged from the
  nonnegativity of the entropies, each averaged term being at least \(0\).
\end{proof}

n33395.content:
\begin{theorem}[Two-sided generator theorem]\label{ksEntropy_eq_ksEntropyPartition_of_isGeneratingTwoSided}
  \lean{ErgodicTheory.Entropy.ksEntropy_eq_ksEntropyPartition_of_isGeneratingTwoSided}\leanok
  \uses{ksEntropy, ksEntropyPartition, IsGeneratingTwoSided}
  Let \(e\) be a measure-preserving automorphism of a standard Borel probability space and \(P\)
  a two-sided generating finite partition. Then
  \[
    h(e) \;=\; h(e,P).
  \]
\end{theorem}

n33398.content:
\begin{definition}[Relative Kolmogorov--Sinai entropy of the system]\label{condKsEntropy}
  \lean{ErgodicTheory.Entropy.condKsEntropy}\leanok
  \uses{condKsEntropyPartition, ksEntropy}
  The \emph{relative entropy of the system given \(\mathcal A\)} is the \(\overline\R\)-valued
  supremum
  \(h(T\mid\mathcal A) = \sup_\alpha h(T,\alpha\mid\mathcal A)\)
  over all finite measurable partitions, mirroring \Cref{ksEntropy}.
\end{definition}

n33410.content:
\begin{theorem}[The information function integrates to the join entropy]\label{integral_infoFun_eq}
  \lean{ErgodicTheory.Krieger.integral_infoFun_eq}\leanok
  \uses{infoFun, ksEntropyPartition}
  For every \(n\),
  \[
    \int_\alpha i_n \,d\mu \;=\; H\Bigl(\bigvee_{k=0}^{n-1} T^{-k}P\Bigr),
  \]
  the Shannon entropy of the \(n\)-fold iterated join (the \(n\)-th term of the
  Kolmogorov--Sinai entropy sequence).
\end{theorem}

n33412.content:
\begin{theorem}[Telescoped Breiman chain rule, entropy level]\label{ksEntropySeq_eq_sum_condEntropy}
  \lean{ErgodicTheory.Krieger.ksEntropySeq_eq_sum_condEntropy}\leanok
  \uses{ksEntropyPartition, condEntropyPartition}
  On a standard Borel space, the \(n\)-step join entropy telescopes into conditional entropies:
  \[
    H\Bigl(\bigvee_{k=0}^{n-1} T^{-k}P\Bigr)
      \;=\; \sum_{k=0}^{n-1}
        H\Bigl(P \,\Big|\, \sigma\bigl(T^{-1}\textstyle\bigvee_{j=0}^{k-1} T^{-j}P\bigr)\Bigr),
  \]
  where the \(k\)-th conditioning \(\sigma\)-algebra is generated by the cells of the
  \(T\)-pullback of the \(k\)-step join.
\end{theorem}

n33426.content:
\begin{proof}\leanok
  \uses{ae_tendsto_div_infoFun_self}
  Almost-everywhere convergence (\Cref{ae_tendsto_div_infoFun_self}) makes the deviation sets
  eventually empty along a.e.\ orbit; convergence in measure of their indicators to the empty set
  follows on the finite measure space.
\end{proof}

n33438.content:
\begin{theorem}[Recovery assembly of Krieger's theorem]\label{krieger_finite_generator_of_coding}
  \lean{ErgodicTheory.Krieger.krieger_finite_generator_of_coding}\leanok
  \uses{KriegerCodingData, IsGeneratingTwoSidedMod0}
  Given a Krieger coding datum \(D\) for \((e, \mu, k)\), there exists a partition
  \(P\) into at most \(k\) cells that two-sidedly generates \((\alpha, e, \mu)\) mod \(0\). No
  entropy, ergodicity or aperiodicity hypotheses enter: those are consumed upstream, in producing
  \(D\). This is the pure recovery content of Krieger's theorem.
\end{theorem}

n33441.content:
\begin{proof}\leanok
  \uses{krieger_finite_generator_of_coding}
  Immediate from the recovery assembly \Cref{krieger_finite_generator_of_coding} applied to the
  supplied coding datum, which already carries the measure-preservation the cross-layer recovery
  needs.
\end{proof}

n33443.content:
\begin{definition}[Mass exponent]\label{massExponent}
  \lean{ErgodicTheory.Multifractal.massExponent}\leanok
  \uses{partitionFunction}
  The \emph{mass exponent} of the family \(p\) at scale \(\varepsilon\) is
  \[
    \tau(q) \;=\; \frac{\log Z_q}{\log \varepsilon},
  \]
  defined for every \(q\) with no case split. For a probability family \(\tau(1) = 0\), since
  \(Z_1 = 1\).
\end{definition}

n33446.content:
\begin{theorem}[Log-convexity of the partition function]\label{logPartitionFunction_convexOn}
  \lean{ErgodicTheory.Multifractal.logPartitionFunction_convexOn}\leanok
  \uses{partitionFunction}
  Let \(p : \iota \to \mathbb{R}\) satisfy \(p_i \ge 0\) for all \(i\) and \(p_i > 0\) for some \(i\).
  Then \(q \mapsto \log Z_q\) is \emph{convex} on all of \(\mathbb{R}\). This is the cumulant-convexity /
  H\"older property, the mathematical core of the multifractal theory.
\end{theorem}

n33448.content:
\begin{theorem}[Concavity of the mass exponent]\label{massExponent_concaveOn}
  \lean{ErgodicTheory.Multifractal.massExponent_concaveOn}\leanok
  \uses{massExponent, logPartitionFunction_convexOn}
  Under the same hypotheses on \(p\), for a scale \(0 < \varepsilon < 1\) the mass exponent
  \(q \mapsto \tau(q) = \log Z_q / \log \varepsilon\) is \emph{concave} on \(\mathbb{R}\).
\end{theorem}

n33450.content:
\begin{theorem}[Antitonicity of the R\'enyi dimension]\label{renyiDim_antitone}
  \lean{ErgodicTheory.Multifractal.renyiDim_antitone}\leanok
  \uses{renyiDim, logPartitionFunction_convexOn}
  Let \(p\) be a probability weight family (\(p_i \ge 0\), \(\sum_i p_i = 1\), at least one
  \(p_i > 0\)) and \(0 < \varepsilon < 1\). Then \(q \mapsto D_q\) is \emph{non-increasing}
  (\texttt{Antitone}) on all of \(\mathbb{R}\) --- including across the information-dimension branch point
  \(q = 1\).
\end{theorem}

n33452.content:
\begin{definition}[R\'enyi dimension of a measure]\label{renyiDimMeasure}
  \lean{ErgodicTheory.Multifractal.renyiDimMeasure}\leanok
  \uses{renyiDim}
  For a measure \(\mu\) on \(\alpha\), a finite measurable partition \(P\) of \(\mu\) indexed by
  \(\iota\), and \(\varepsilon, q \in \mathbb{R}\), the \emph{R\'enyi dimension of \(\mu\)} at partition
  scale \(\varepsilon\) is the abstract \(D_q\) of the cell-mass family
  \(i \mapsto \mu(P_i)\) (real-valued via \texttt{toReal}). The companion definitions
  \texttt{partitionFunctionMeasure} and \texttt{massExponentMeasure} specialize \(Z_q\) and
  \(\tau\) in the same way.
\end{definition}

n33453.content:
\begin{theorem}[Antitonicity for a probability measure]\label{renyiDimMeasure_antitone}
  \lean{ErgodicTheory.Multifractal.renyiDimMeasure_antitone}\leanok
  \uses{renyiDimMeasure, renyiDim_antitone}
  For a probability measure \(\mu\), a finite measurable partition \(P\), and a scale
  \(0 < \varepsilon < 1\), the R\'enyi dimension \(q \mapsto D_q(\mu, P, \varepsilon)\) is
  non-increasing in \(q\).
\end{theorem}

n33456.content:
\begin{proof}\leanok
  \uses{renyiDimMeasure}
  Unfold the \(q = 1\) branch of \(D_q\): its numerator \(\sum_i \mu(P_i)\log\mu(P_i)\) is
  term-by-term the negation of the \(\operatorname{negMulLog}\) sum defining \(H(P)\).
\end{proof}

n33457.content:
\begin{definition}[R\'enyi dimension of a flow's invariant measure]\label{renyiDimFlow}
  \lean{ErgodicTheory.Multifractal.renyiDimFlow}\leanok
  \uses{renyiDimMeasure, MeasurePreservingFlow}
  For a measure-preserving flow \(\varphi\) with invariant probability measure \(\mu\)
  (Definition~\ref{MeasurePreservingFlow}), a partition \(P\), and \(\varepsilon, q\), the
  \emph{R\'enyi dimension of the flow's invariant measure} is
  \(D_q(\varphi, P, \varepsilon) = D_q(\mu, P, \varepsilon)\). The flow is an explicit (unused)
  argument whose \emph{type} documents that \(\mu\) is flow-invariant; the multifractal API
  consumes any invariant probability measure.
\end{definition}

n33458.content:
\begin{corollary}[Flow-level antitonicity]\label{renyiDimFlow_antitone}
  \lean{ErgodicTheory.Multifractal.renyiDimFlow_antitone}\leanok
  \uses{renyiDimFlow, renyiDimMeasure_antitone}
  For a measure-preserving flow \(\varphi\) of a probability measure \(\mu\), a partition \(P\),
  and \(0 < \varepsilon < 1\), the flow R\'enyi dimension \(q \mapsto D_q(\varphi, P,
  \varepsilon)\) is non-increasing in \(q\).
\end{corollary}

n33459.content:
\begin{proof}\leanok
  \uses{renyiDimMeasure_antitone}
  \texttt{renyiDimFlow} unfolds to \texttt{renyiDimMeasure}, so this is
  Theorem~\ref{renyiDimMeasure_antitone} verbatim.
\end{proof}

n33461.content:
\begin{theorem}[Local dimension in the absolutely-continuous case]\label{ae_tendsto_localDimension_of_absolutelyContinuous}
  \lean{ErgodicTheory.Multifractal.ae_tendsto_localDimension_of_absolutelyContinuous}\leanok
  \uses{localDimension}
  Let \(E\) be a finite-dimensional real inner-product space (Borel-measurable) and let \(\mu\)
  be a probability measure on \(E\) absolutely continuous with respect to an additive Haar measure
  \(\nu\) (e.g.\ Lebesgue). Then for \(\mu\)-almost every \(x\) the local-dimension quotient
  \(\log \mu(\bar B(x,r)) / \log r\) \emph{converges}, as \(r \to 0^+\), to the ambient dimension
  \(\dim_{\mathbb{R}} E = \operatorname{finrank}_{\mathbb{R}} E\).
\end{theorem}

n33463.content:
\begin{corollary}[A.e.\ value of the local dimension]\label{ae_localDimension_eq_finrank}
  \lean{ErgodicTheory.Multifractal.ae_localDimension_eq_finrank}\leanok
  \uses{localDimension, ae_tendsto_localDimension_of_absolutelyContinuous}
  Under the same hypotheses, \(\bar d_\mu(x) = \operatorname{finrank}_{\mathbb{R}} E\) for \(\mu\)-almost
  every \(x\): the measure is exact-dimensional with dimension equal to the ambient dimension.
\end{corollary}

n33464.content:
\begin{proof}\leanok
  \uses{ae_tendsto_localDimension_of_absolutelyContinuous}
  Where the genuine limit of Theorem~\ref{ae_tendsto_localDimension_of_absolutelyContinuous}
  exists, the \(\limsup\) defining \(\bar d_\mu\) returns that limit.
\end{proof}

n33465.content:
\begin{theorem}[Local-to-Hausdorff dimension bridge]\label{dimH_eq_of_localDimension_eq}
  \lean{ErgodicTheory.Multifractal.dimH_eq_of_localDimension_eq}\leanok
  \uses{localDimension}
  Let \(\mu\) be a probability measure on a Borel second-countable metric space \(E\), let
  \(\alpha > 0\), and let \(s\) be a set of full \(\mu\)-measure (\(\mu(s^{\mathsf c}) = 0\)) such
  that \emph{for every} \(x \in s\) the local-dimension quotient
  \(\log \mu(\bar B(x,r))/\log r\) tends to \(\alpha\) as \(r \to 0^+\). Then
  \(\dim_H s = \alpha\).
\end{theorem}

n33467.content:
\begin{theorem}[Hausdorff dimension of full-measure sets, a.c.\ case]\label{dimH_eq_finrank_of_ae_full_of_absolutelyContinuous}
  \lean{ErgodicTheory.Multifractal.dimH_eq_finrank_of_ae_full_of_absolutelyContinuous}\leanok
  \uses{ae_tendsto_localDimension_of_absolutelyContinuous}
  Let \(\mu\) be a probability measure on a finite-dimensional real inner-product space \(E\),
  absolutely continuous with respect to a Haar measure. Then \emph{every} set \(s\) of full
  \(\mu\)-measure has Hausdorff dimension equal to the ambient dimension:
  \(\dim_H s = \operatorname{finrank}_{\mathbb{R}} E\).
\end{theorem}

n33468.content:
\begin{proof}\leanok
  \uses{ae_tendsto_localDimension_of_absolutelyContinuous, dimH_eq_of_localDimension_eq}
  The upper bound is monotonicity: \(\dim_H s \le \dim_H E = \operatorname{finrank}_{\mathbb{R}} E\). The
  lower bound is the Frostman direction of the bridge, fed by the a.e.\ local-dimension limit of
  Theorem~\ref{ae_tendsto_localDimension_of_absolutelyContinuous}.
\end{proof}

n33479.content:
\begin{theorem}[Heterogeneity of the witness]\label{isHeterogeneous_bernSuspensionWitness}
  \lean{ErgodicTheory.Multifractal.isHeterogeneous_bernSuspensionWitness}\leanok
  \uses{bernSuspensionWitness}
  If \(\nu\) charges two distinct symbols \(i \ne j\) with \emph{different} masses
  (\(\nu\{i\} \ne \nu\{j\}\)), then the witness partition is \emph{heterogeneous}: two of its
  cells carry distinct \(\hat\mu\)-mass (\texttt{IsHeterogeneous}, the honest non-uniformity
  predicate whose negation is exactly the equal-measure hypothesis of the monofractal degeneracy
  \(D_q \equiv \log N / (-\log\varepsilon)\)).
\end{theorem}

n33480.content:
\begin{proof}\leanok
  \uses{bernSuspensionWitness}
  By the mass identity, the cells indexed by \(i\) and \(j\) carry masses \(\nu\{i\}\) and
  \(\nu\{j\}\), which differ by hypothesis (the \texttt{toReal} coercion is injective on finite
  masses).
\end{proof}

n33483.content:
\begin{definition}[Merged weights]\label{mergedWeights}
  \lean{ErgodicTheory.Multifractal.mergedWeights}\leanok
  For a finite weight family \(p : \iota \to \mathbb{R}\) and a \emph{merge} map \(f : \iota \to \kappa\),
  the \emph{merged weights} \(\mathrm{mergedWeights}\,f\,p : \kappa \to \mathbb{R}\) push \(p\) forward along
  \(f\) by summing each fibre: \((\mathrm{mergedWeights}\,f\,p)(b) = \sum_{a \,:\, f a = b} p_a\).
\end{definition}

n33484.content:
\begin{definition}[R\'enyi entropy]\label{renyiEntropy}
  \lean{ErgodicTheory.Multifractal.renyiEntropy}\leanok
  \uses{partitionFunction}
  The \emph{R\'enyi entropy of order \(q\)} of a family \(p : \iota \to \mathbb{R}\) is
  \[
    H_q(p) \;=\; (1 - q)^{-1} \, \log Z_q(p),
  \]
  reusing the generalized partition function \(Z_q\) (Definition~\ref{partitionFunction}) verbatim as
  the power sum \(\sum_{p_i > 0} p_i^{\,q}\).
\end{definition}

n33485.content:
\begin{lemma}[Power-sum super/subadditivity under merge]\label{partitionFunction_merge}
  \lean{ErgodicTheory.Multifractal.partitionFunction_merge_ge}\leanok
  \uses{partitionFunction, mergedWeights}
  Let \(p : \iota \to \mathbb{R}\) with \(p_a \ge 0\). For \(q \ge 1\) the partition function \emph{grows}
  under merge, \(Z_q(p) \le Z_q(\mathrm{mergedWeights}\,f\,p)\)
  (\texttt{partitionFunction\_merge\_ge}, per-fibre superadditivity of \(x \mapsto x^q\)), while for
  \(0 \le q \le 1\) it \emph{shrinks}, \(Z_q(\mathrm{mergedWeights}\,f\,p) \le Z_q(p)\)
  (\texttt{partitionFunction\_merge\_le}, subadditivity).
\end{lemma}

n33489.content:
\begin{definition}[Cylinder masses and the R\'enyi rate]\label{renyiRateSup}
  \lean{ErgodicTheory.Multifractal.renyiRateSup}\leanok
  \uses{renyiEntropy}
  For a probability measure \(\mu\) on \(\mathrm{Shift}\,A\), the \emph{length-\(n\) cylinder mass}
  of a word \(w : \operatorname{Fin}n \to A\) is \(\mathrm{cylinderMass}\,\mu\,n\,w = \mu(\text{cylinder}\,w)\),
  the \emph{length-\(n\) R\'enyi entropy} is \(H_q^{(n)}(\mu) = \mathrm{renyiEntropySeq}\,\mu\,q\,n\)
  --- the R\'enyi entropy (Definition~\ref{renyiEntropy}) of the family of cylinder masses --- and
  the \emph{upper} and \emph{lower R\'enyi rates} are its normalized limit superior and inferior,
  \(\mathrm{renyiRateSup}\,\mu\,q = \limsup_n H_q^{(n)}(\mu)/n\) and
  \(\mathrm{renyiRateInf}\,\mu\,q = \liminf_n H_q^{(n)}(\mu)/n\).
\end{definition}

n33490.content:
\begin{definition}[One-block code]\label{blockCode}
  \lean{ErgodicTheory.Multifractal.blockCode}\leanok
  A symbol map \(\varphi : A \to B\) lifts coordinatewise to the \emph{one-block code}
  \(\mathrm{blockCode}\,\varphi : \mathrm{Shift}\,A \to \mathrm{Shift}\,B\),
  \((\mathrm{blockCode}\,\varphi\,x)(k) = \varphi(x_k)\), with induced word map
  \(\mathrm{wordMap}\,\varphi\,n : (\operatorname{Fin}n \to A) \to (\operatorname{Fin}n \to B)\).
\end{definition}

n33491.content:
\begin{theorem}[Per-length pushforward identity and DPI]\label{renyiEntropySeq_map_blockCode_le}
  \lean{ErgodicTheory.Multifractal.renyiEntropySeq_map_blockCode_le}\leanok
  \uses{blockCode, renyiEntropy_merge_le, renyiRateSup}
  The preimage of a length-\(n\) cylinder of \(\mathrm{Shift}\,B\) under \(\mathrm{blockCode}\,\varphi\)
  is the finite disjoint union of the length-\(n\) cylinders over the fibre of
  \(\mathrm{wordMap}\,\varphi\,n\), so by additivity the pushed cylinder masses are exactly the
  \emph{merged} weights of the originals (\texttt{cylinderMass\_map\_blockCode}). The static DPI
  (\Cref{renyiEntropy_merge_le}) then gives the per-length bound
  \(H_q^{(n)}(\mathrm{blockCode}\,\varphi_*\mu) \le H_q^{(n)}(\mu)\) for every \(0 \le q\), \(q \ne 1\).
\end{theorem}

n33500.content:
\begin{theorem}[Chain-rule cocycle identity]\label{chainRule_cocycle}
  \lean{ErgodicTheory.chainRule_cocycle}\leanok
  \uses{derivativeCocycle, cocycle}
  For a differentiable \(T\), the \(n\)-th cocycle iterate of the derivative generator represents
  the derivative of the \(n\)-th iterate of the map:
  \[
    \texttt{toEuclideanCLM}\bigl(\operatorname{cocycle}(\operatorname{derivativeCocycle} T)\,T\,n\,x\bigr)
      \;=\; D_x\bigl(T^{[n]}\bigr) .
  \]
\end{theorem}

n33506.content:
\begin{lemma}[Every singular value is at least \(K^n\)]\label{expanding_pow_le_singularValues}
  \lean{ErgodicTheory.expanding_pow_le_singularValues}\leanok
  \uses{cocycle_expanding_bound, chainRule_cocycle}
  Under the same hypotheses, every singular value of the cocycle iterate
  \(A^{(n)}(x) = \operatorname{cocycle}(\operatorname{derivativeCocycle} T)\,T\,n\,x\) is at least
  \(K^n\): \(\ K^n\le\sigma_i\bigl(A^{(n)}(x)\bigr)\) for every \(i < d\).
\end{lemma}

n33508.content:
\begin{theorem}[Every exponent is at least \(\log K\)]\label{log_le_exponents_of_expanding}
  \lean{ErgodicTheory.log_le_exponents_of_expanding}\leanok
  \uses{exponents, exponents_tendsto_log_singularValue, expanding_pow_le_singularValues}
  For an ergodic, log-integrable, differentiable uniformly expanding map with constant \(K > 1\)
  (and \(d\ge 1\)), each Lyapunov exponent of the tangent cocycle satisfies
  \(\log K \le \lambda_i\).
\end{theorem}

n33509.content:
\begin{proof}\leanok
  \uses{exponents_tendsto_log_singularValue, expanding_pow_le_singularValues}
  Pick a base point where the per-index singular-value limit
  \(\frac1n\log\sigma_i(A^{(n)}(x))\to\lambda_i\) of \Cref{exponents_tendsto_log_singularValue}
  holds. By \Cref{expanding_pow_le_singularValues} each pre-limit term is at least
  \(\frac1n\log K^n = \log K\), and the limit inherits the lower bound.
\end{proof}

n33510.content:
\begin{corollary}[Positivity of the whole spectrum]\label{exponents_pos_of_expanding}
  \lean{ErgodicTheory.exponents_pos_of_expanding}\leanok
  \uses{log_le_exponents_of_expanding}
  Every Lyapunov exponent of a uniformly expanding map is strictly positive:
  \(0 < \log K \le \lambda_i\).
\end{corollary}

n33512.content:
\begin{proposition}[All-positive-spectrum collapse]\label{sumPosExp_eq_sumAllExp_of_expanding}
  \lean{ErgodicTheory.sumPosExp_eq_sumAllExp_of_expanding}\leanok
  \uses{exponents_pos_of_expanding, exponents}
  For a uniformly expanding map the positive-part exponent sum is the full exponent sum:
  \(\sum\lambda^{+} = \sum_i\lambda_i\) (with multiplicity).
\end{proposition}

n33513.content:
\begin{proof}\leanok
  \uses{exponents_pos_of_expanding}
  By \Cref{exponents_pos_of_expanding} the filter \(\{i \mid 0 < \lambda_i\}\) is all of the index
  set, so the two finite sums have identical terms.
\end{proof}

n33521.content:
\begin{theorem}[Doubling map: top exponent \(\log 2\)]\label{doublingMap_topExponent_eq_log_two}
  \lean{ErgodicTheory.doublingMap_topExponent_eq_log_two}\leanok
  \uses{exponents}
  The constant cocycle with generator \(M = (2)\) over the ergodic doubling map has top Lyapunov
  exponent \(\log 2\).
\end{theorem}

n33523.content:
\begin{corollary}[Doubling map: positive-exponent sum \(\log 2\)]\label{doublingMap_sumPosExp_eq_log_two}
  \lean{ErgodicTheory.doublingMap_sumPosExp_eq_log_two}\leanok
  \uses{doublingMap_topExponent_eq_log_two}
  The sum of the strictly positive Lyapunov exponents of the doubling-map cocycle is \(\log 2\),
  with every spectrum hypothesis (invertibility, measurability, both log-integrability conditions)
  discharged unconditionally from the constant-cocycle API.
\end{corollary}

n33524.content:
\begin{proof}\leanok
  \uses{doublingMap_topExponent_eq_log_two}
  The spectrum consists of the single exponent \(\log 2 > 0\), so the positive-part filter is the
  full (one-element) index set and the sum is that one term.
\end{proof}

n33527.content:
\begin{proposition}[Entropy of a uniform-join system]\label{ksEntropyPartition_of_uniform}
  \lean{ErgodicTheory.Examples.Rokhlin.ksEntropyPartition_of_uniform}\leanok
  \uses{ksEntropyPartition}
  Let \(T\) preserve a probability measure and let \(P\) be a finite partition indexed by a type
  of cardinality \(b\) such that for \emph{every} \(n\), every cell of the \(n\)-fold join
  \(\bigvee_{k=0}^{n-1}T^{-k}P\) has measure exactly \(b^{-n}\). Then
  \(h(P,T) = \log b\).
\end{proposition}

n33529.content:
\begin{theorem}[Rokhlin equality, entropy side: \(h(\alpha,T) = \log 2\)]\label{ksEntropyPartition_doublingMap_eq_log_two}
  \lean{ErgodicTheory.Examples.Rokhlin.ksEntropyPartition_doublingMap_eq_log_two}\leanok
  \uses{ksEntropyPartition_of_uniform}
  For the binary partition \(\alpha = \{[0,\tfrac12), [\tfrac12,1)\}\) of the circle
  (\lean{ErgodicTheory.Examples.Rokhlin.binPartition}), the partition-relative Kolmogorov--Sinai
  entropy under the doubling map is exactly \(\log 2\).
\end{theorem}

n33532.content:
\begin{proof}\leanok
  \uses{ksEntropyPartition_doublingMap_eq_log_two, derivativeCocycle}
  The entropy side is \Cref{ksEntropyPartition_doublingMap_eq_log_two}. For the integral side,
  \(\det(2) = 2\), so the integrand is the constant \(\log 2\), which integrates against the
  probability measure to \(\log 2\). Both sides equal \(\log 2\).
\end{proof}

n33535.content:
\begin{corollary}[The cat-map exponents sum to zero]\label{catMapMatrix_exponents_sum_eq_zero}
  \lean{ErgodicTheory.catMapMatrix_exponents_sum_eq_zero}\leanok
  \uses{catMapMatrix_exponents}
  \(\lambda_1 + \lambda_2 = 0\): the cocycle is conservative (\(\det M = 1\)).
\end{corollary}

n33538.content:
\begin{proposition}[Measure preservation]\label{measurePreserving_catTorus}
  \lean{ErgodicTheory.CatMapToral.measurePreserving_catTorus}\leanok
  \uses{catTorus}
  \(\operatorname{catTorus}\) preserves the Haar probability measure on \(\mathbb{T}^2\).
\end{proposition}

n33540.content:
\begin{theorem}[Ergodicity of the Arnold cat map]\label{ergodic_catTorus}
  \lean{ErgodicTheory.CatMapToral.ergodic_catTorus}\leanok
  \uses{measurePreserving_catTorus, catTorus}
  \(\operatorname{catTorus}\) is ergodic for the Haar probability measure on \(\mathbb{T}^2\).
\end{theorem}

n33542.content:
\begin{theorem}[Cat-map spectrum over the genuine ergodic base]\label{catTorus_constCocycle_exponents}
  \lean{ErgodicTheory.CatMapToral.catTorus_constCocycle_exponents}\leanok
  \uses{ergodic_catTorus, catMapMatrix_exponents, exponents}
  Realized as a constant cocycle with generator \(M\) over the \emph{genuine} ergodic Arnold cat
  map \(\operatorname{catTorus}\), the two Lyapunov exponents are
  \(\log\bigl((3+\sqrt5)/2\bigr)\) and \(\log\bigl((3-\sqrt5)/2\bigr)\) --- the same spectrum as
  \Cref{catMapMatrix_exponents}, now over the hyperbolic toral automorphism itself rather than a
  surrogate base.
\end{theorem}

n33543.content:
\begin{proof}\leanok
  \uses{ergodic_catTorus, catMapMatrix_exponents}
  The constant-cocycle spectrum theorem applies over any ergodic base; instantiate it over
  \(\operatorname{catTorus}\) (\Cref{ergodic_catTorus}) and evaluate the sorted eigenvalues of
  \(\left\lvert M \right\rvert = M\) by the closed form computed for \Cref{catMapMatrix_exponents}.
\end{proof}

n33548.content:
\begin{theorem}[\(L^2\) correlation decay]\label{tendsto_catCorr}
  \lean{ErgodicTheory.CatMapToral.tendsto_catCorr}\leanok
  \uses{ergodic_catTorus}
  Let \(U_k v = v\circ\operatorname{catTorus}^{[k]}\) be the Koopman operator (an \(L^2\)-isometry,
  \lean{ErgodicTheory.CatMapToral.catComp}) and \(\Phi_k(u,v) = \langle u, U_k v\rangle\) the
  correlation (\lean{ErgodicTheory.CatMapToral.catCorr}). For every \(u,v\in L^2(\mathbb{T}^2)\),
  \[
    \Phi_k(u,v) \;\xrightarrow[k\to\infty]{}\;
      \Bigl(\int_{\mathbb{T}^2}\overline{u}\Bigr)\Bigl(\int_{\mathbb{T}^2} v\Bigr),
  \]
  the orthogonal projection onto the constants.
\end{theorem}

n33550.content:
\begin{theorem}[Strong mixing of the Arnold cat map]\label{catTorus_mixing}
  \lean{ErgodicTheory.CatMapToral.catTorus_mixing}\leanok
  \uses{tendsto_catCorr, measurePreserving_catTorus}
  For arbitrary measurable sets \(A,B\subseteq\mathbb{T}^2\),
  \[
    \operatorname{vol}\bigl(A\cap\operatorname{catTorus}^{[k]\,-1}B\bigr)
      \;\xrightarrow[k\to\infty]{}\;
      \operatorname{vol}(A)\cdot\operatorname{vol}(B),
  \]
  i.e.\ \(\operatorname{catTorus}\) is strongly mixing for the Haar probability measure.
\end{theorem}

n33552.content:
\begin{lemma}[Mixing kills unimodular eigenvalues]\label{eigenfunction_ae_zero_of_mixing}
  \lean{ErgodicTheory.eigenfunction_ae_zero_of_mixing}\leanok
  A reusable spectral interface: for a strongly mixing measure-preserving map on a probability
  space, any measurable eigenfunction \(g\) with \(g\circ f = l\cdot g\), \(\left\lvert l \right\rvert = 1\),
  \(l\ne 1\), vanishes a.e.
\end{lemma}

n33554.content:
\begin{corollary}[Eigenfunction rigidity from mixing]\label{catTorus_eigenfunction_ae_zero_of_mixing}
  \lean{ErgodicTheory.CatMapToral.catTorus_eigenfunction_ae_zero_of_mixing}\leanok
  \uses{catTorus_mixing, eigenfunction_ae_zero_of_mixing}
  A measurable \(g:\mathbb{T}^2\to\mathbb C\) with \(g(\operatorname{catTorus} x) = l\cdot g(x)\),
  \(\left\lvert l \right\rvert = 1\), \(l\ne 1\), vanishes a.e.\ --- re-deriving \Cref{thm:catTorus-eigZero} through the
  mixing interface rather than the direct Fourier argument.
\end{corollary}

n33555.content:
\begin{proof}\leanok
  \uses{catTorus_mixing, eigenfunction_ae_zero_of_mixing}
  Discharge \Cref{eigenfunction_ae_zero_of_mixing} with the strong mixing of the cat map
  (\Cref{catTorus_mixing}) as the correlation-decay hypothesis.
\end{proof}

n33556.content:
\begin{theorem}[Cat-map eigenfunction rigidity]\label{thm:catTorus-eigZero}
  \lean{ErgodicTheory.CatMapToral.catTorus_eigenfunction_ae_zero}\leanok
  \uses{ergodic_catTorus}
  A measurable \(g : \mathbb{T}^2 \to \mathbb{C}\) with \(g(\operatorname{catTorus} x) = l\cdot g(x)\)
  for all \(x\), where \(\left\lVert l \right\rVert = 1\) and \(l \ne 1\), vanishes almost everywhere.
\end{theorem}

n33558.content:
\begin{theorem}[Time-one ergodicity of the irrational-roof cat suspension]\label{thm:catSusp-timeOne}
  \lean{ErgodicTheory.CatMapToral.ergodic_catSuspension_timeOne_const_irrational}\leanok
  \uses{thm:susp-timeOneErgodic, thm:catTorus-eigZero, measurePreserving_catTorus}
  For the Arnold cat map with Haar \(\operatorname{volume}\) on \(\mathbb{T}^2\) and any positive
  \emph{irrational} roof \(r\), the time-\(1\) map of the constant-roof suspension flow is ergodic
  for the invariant suspension probability measure.
\end{theorem}

n33559.content:
\begin{proof}\leanok
  \uses{thm:susp-timeOneErgodic, thm:catTorus-eigZero}
  Discharge the abstract \Cref{thm:susp-timeOneErgodic} with base ergodicity
  (\Cref{ergodic_catTorus}) and the no-nontrivial-eigenfunctions input
  (\Cref{thm:catTorus-eigZero}).
\end{proof}

n33560.content:
\begin{theorem}[Concrete non-vacuity witness $r = \sqrt2$]\label{thm:catSusp-sqrt2}
  \lean{ErgodicTheory.CatMapToral.ergodic_catSuspension_timeOne_sqrtTwo}\leanok
  \uses{thm:catSusp-timeOne}
  The irrational roof \(r := \sqrt2\) yields an ergodic time-\(1\) map of the cat suspension.
\end{theorem}

n33562.content:
\begin{definition}[Positive-measure atom count]\label{posAtomCount}
  \lean{ErgodicTheory.Entropy.posAtomCount}\leanok
  \uses{ksJoin}
  The number of index families \(f : \operatorname{Fin} n \to \iota\) whose atom of the flat
  \(n\)-fold join \(\bigvee_{k<n} T^{-k}P\) (\Cref{ksJoin}) has nonzero \(\mu\)-mass. It is at most
  the set-nonempty atom count, yet still bounds the entropy from above (a null junk cell is not
  counted), giving a sharper crude Ruelle backbone.
\end{definition}

n33563.content:
\begin{theorem}[The wall lemma]\label{catTorus_gridJoinAtom_volume_le}
  \lean{ErgodicTheory.CatMapToral.catTorus_gridJoinAtom_volume_le}\leanok
  \uses{catTorus, measurePreserving_catTorus}
  Every atom of the \(n\)-fold forward join of the \(5 \times 5\) grid partition under
  \(\operatorname{catTorus}\) has \(\operatorname{volume}\) at most \((9\sqrt5/25)\cdot\lambda\cdot
  \mu^n\). Two points sharing every grid cell for \(n\) steps stay \(1/5\)-close along the orbit, so
  a nearest-integer lift of their difference telescopes into an eigencoordinate slab
  \(\left\lvert \operatorname{eigCoordU} \right\rvert \le (3/10)\mu^{n-1}\), \(\left\lvert \operatorname{eigCoordS} \right\rvert \le 3/10\);
  translation invariance and the projection contraction give the measure bound.
\end{theorem}

n33566.content:
\begin{corollary}[Strict positivity of the cat-map entropy (Tier 1, \#52)]\label{catTorus_ksEntropy_pos}
  \lean{ErgodicTheory.CatMapToral.catTorus_ksEntropy_pos}\leanok
  \uses{catTorus_gridJoinAtom_volume_le}
  \(0 < h(\operatorname{catTorus})\).
\end{corollary}

n33567.content:
\begin{definition}[The Adler--Weiss Markov partition]\label{catAWPartition}
  \lean{ErgodicTheory.CatMapToral.catAWPartition}\leanok
  \uses{catTorus}
  The golden two-box partition of \(\mathbb{T}^2\) into the projected branches of the two golden
  rectangles \(R_1 = [0,\varphi)\times[0,\varphi)\) and \(R_2 = [\varphi,\varphi^2)\times[0,1)\) (in
  the eigen-coordinates), a six-cell \(\operatorname{MeasurePartition}\) (five branch cells plus a
  junk cell).
\end{definition}

n33568.content:
\begin{lemma}[Exact cover: the junk cell is empty]\label{awCell_zero_eq_empty}
  \lean{ErgodicTheory.CatMapToral.awCell_zero_eq_empty}\leanok
  \uses{catAWPartition}
  The junk cell of \Cref{catAWPartition} is \emph{literally empty}, not merely null: a four-case
  skew-lattice reduction shows every torus point, lifted to the unit square, lands in
  \(R_1 \cup R_2\) after subtracting one of the four lattice vectors \((0,0),(0,1),(-1,0),(-1,1)\).
  Hence the two golden rectangles tile the torus exactly.
\end{lemma}

n33569.content:
\begin{theorem}[Blackwell bridge: separating itineraries generate]\label{isGeneratingTwoSided_of_separating}
  \lean{ErgodicTheory.Krieger.isGeneratingTwoSided_of_separating}\leanok
  \uses{IsGeneratingTwoSided}
  For a measurable automorphism of a \emph{standard Borel} space and a finite measurable partition
  \(P\), if the two-sided family of cell-preimages separates points then \(P\) is two-sided
  generating (\Cref{IsGeneratingTwoSided}). The identity map from the ambient Borel structure to the
  coarser saturated \(\sigma\)-algebra is an injective measurable map into a countably separated
  space, hence a measurable embedding by Blackwell's theorem.
\end{theorem}

n33570.content:
\begin{theorem}[The Adler--Weiss partition is a two-sided generator]\label{isGeneratingTwoSided_catAWPartition}
  \lean{ErgodicTheory.CatMapToral.isGeneratingTwoSided_catAWPartition}\leanok
  \uses{catAWPartition, isGeneratingTwoSided_of_separating, awCell_zero_eq_empty, catTorus}
  \(\operatorname{catAWPartition}\) is two-sided generating for \(\operatorname{catTorus}\). Each
  point has a unique admissible two-sided itinerary (consecutive symbols satisfy
  \(\operatorname{tgt} = \operatorname{src}\), by the geometric branch-step keystone and injectivity
  of the covering projection on \(R_1 \cup R_2\)); two points with the same itinerary have
  difference propagating linearly, so the contraction estimate forces them equal. Separation then
  yields generation through \Cref{isGeneratingTwoSided_of_separating}.
\end{theorem}

n33571.content:
\begin{theorem}[Golden transfer-matrix entropy bound]\label{catAW_ksEntropyPartition_le}
  \lean{ErgodicTheory.CatMapToral.catAW_ksEntropyPartition_le}\leanok
  \uses{catAWPartition, posAtomCount, ksEntropyPartition}
  \(h(\operatorname{catTorus}, \operatorname{catAWPartition}) \le \log\!\big((3+\sqrt5)/2\big)\). The
  positive-measure atoms of the join inject into admissible golden itineraries, whose weighted count
  satisfies the exact recurrence \(W(n+1) = \lambda\cdot W(n)\) via the golden weight identity
  \(\sum_{\operatorname{src} e' = b} w(e') = \lambda_+\,w(b)\); the atom-count backbone converts this
  growth rate into the entropy bound.
\end{theorem}

n33574.content:
\begin{theorem}[The sharp cat-map Kolmogorov--Sinai entropy]\label{catTorus_ksEntropy_eq}
  \lean{ErgodicTheory.CatMapToral.catTorus_ksEntropy_eq}\leanok
  \uses{catTorus_ksEntropy_ge, catTorus_ksEntropy_le}
  \(h(\operatorname{catTorus}) = \log\!\big((3+\sqrt5)/2\big) = \log\lambda_+\). This is the exact
  Kolmogorov--Sinai entropy of a hyperbolic system, formalized end-to-end; we have not located a
  prior formalization.
\end{theorem}

n33575.content:
\begin{proof}\leanok
  \uses{catTorus_ksEntropy_ge, catTorus_ksEntropy_le}
  \texttt{le\_antisymm} of the Adler--Weiss generator upper bound \Cref{catTorus_ksEntropy_le} and
  the grid-slab lower bound \Cref{catTorus_ksEntropy_ge}.
\end{proof}

n33579.content:
\begin{definition}[The invariant integer norm form]\label{Qform}
  \lean{ErgodicTheory.CatMapToral.Qform}\leanok
  \uses{catTorus}
  The \emph{norm form} \(Q(p,q) = p^2 - p q - q^2\) of the cat-map matrix \(A = \bigl(\begin{smallmatrix}2&1\\1&1\end{smallmatrix}\bigr)\)
  is the norm form of the ring \(\mathbb{Z}[\varphi]\) (discriminant \(5\)). It is exactly \(A\)-invariant,
  \(Q(A^k n) = Q(n)\) (\lean{ErgodicTheory.CatMapToral.Qform_pow_mulVec}), and --- being the norm of
  a nonzero element of \(\mathbb{Z}[\varphi]\) --- never vanishes on a nonzero lattice vector
  (\lean{ErgodicTheory.CatMapToral.Qform_ne_zero}), hence \(\left\lvert Q(n) \right\rvert\ge 1\) there.
\end{definition}

n33582.content:
\begin{theorem}[Parseval character expansion of the correlation]\label{hasSum_correlation_fourier_ne_zero}
  \lean{ErgodicTheory.CatMapToral.hasSum_correlation_fourier_ne_zero}\leanok
  \uses{catTorus}
  For continuous \(f, g:\mathbb{T}^2\to\mathbb{C}\), Parseval turns the time-\(k\) correlation into a bilinear
  character sum, and the Koopman action \(\texttt{mFourier}\,n\circ\operatorname{catTorus}^{[k]} =
  \texttt{mFourier}(A^k n)\) shifts the index on one factor: the sum over \(b\ne 0\) of
  \(\overline{\hat f(A^k b)}\,\hat g(b)\) converges to the \emph{centred} correlation
  \(\int\overline f\,(g\circ\operatorname{catTorus}^{[k]}) - (\int\overline f)(\int g)\).
\end{theorem}

n33585.content:
\begin{proof}\leanok
  \uses{lemma_beta, summable_bracket_rpow, hasSum_correlation_fourier_ne_zero}
  Split the centred character sum \Cref{hasSum_correlation_fourier_ne_zero} at radius
  \(\langle b\rangle = \lambda_+^{k/2}\). On the near part the norm-form expansion \Cref{lemma_beta}
  forces \(\langle A^k b\rangle\ge(\sqrt5 - 2)\lambda_+^{k/2}\), so the decay class caps
  \(\left\lVert \hat f(A^k b) \right\rVert\) by a \(\lambda_+^{-ks/4}\)-multiple; on the far part the lattice tail
  \Cref{summable_bracket_rpow} contributes \(\lambda_+^{-k(s-2)/4}\). Both parts are dominated by
  \(C\theta^{k}\) with \(\theta = \lambda_+^{-(s-2)/4}\).
\end{proof}

n33586.content:
\begin{theorem}[Autocovariance decay]\label{catAutoCorr_decay}
  \lean{ErgodicTheory.CatMapToral.catAutoCorr_decay}\leanok
  \uses{catCorr_decay}
  For \(f\in C(\mathbb{T}^2,\mathbb{R})\) with \(\mathcal C_s\)-complexification (\(s > 2\)),
  \(\left\lvert \rho(k) \right\rvert\le C\theta^{k}\) with the same rate \(\theta = \lambda_+^{-(s-2)/4}\); this is the
  bridge identifying the probabilistic autocovariance with the centred correlation of
  \Cref{catCorr_decay}.
\end{theorem}

n33587.content:
\begin{proof}\leanok
  \uses{catCorr_decay}
  The autocovariance \(\operatorname{cov}[f, f\circ\operatorname{catTorus}^{[k]}]\) equals the centred
  correlation \(\int f\,(f\circ\operatorname{catTorus}^{[k]}) - (\int f)^2\) by measure preservation;
  apply the real-observable corollary of \Cref{catCorr_decay}.
\end{proof}

n33589.content:
\begin{proof}\leanok
  \uses{catAutoCorr_decay}
  A Toeplitz/Ces\`aro collapse expresses \(\operatorname{Var}(S_n) = 2\sum_{d<n}(n-d)\rho(d) -
  n\rho(0)\); geometric summability of \(\rho\) (\Cref{catAutoCorr_decay}) makes the averaged
  double sum converge to \(\sigma^2\) and bounds it linearly.
\end{proof}

n33590.content:
\begin{theorem}[Finite-sample concentration]\label{catConcentration_fourierDecay}
  \lean{ErgodicTheory.CatMapToral.catConcentration_fourierDecay}\leanok
  \uses{catGreenKubo_fourierDecay}
  For \(f\in\mathcal C_s\) there is a constant \(B\ge 0\) with, for every sample size \(n\ge 1\) and
  threshold \(\varepsilon > 0\),
  \[
    \mu\Bigl\{x : \Bigl\lvert \tfrac1n S_n f(x) - \int_{\mathbb{T}^2}\! f \Bigr\rvert \ge \varepsilon\Bigr\}
      \;\le\; \frac{B}{n\,\varepsilon^2},
  \]
  the tier-3 headline law: the empirical average concentrates around the space mean at the Chebyshev
  rate.
\end{theorem}

n33591.content:
\begin{proof}\leanok
  \uses{catGreenKubo_fourierDecay}
  Chebyshev's inequality against the linear variance bound of \Cref{catGreenKubo_fourierDecay}.
\end{proof}

n33596.content:
\begin{definition}[The two-sided Adler--Weiss itinerary]\label{awSymbFull}
  \lean{ErgodicTheory.CatMapToral.awSymbFull}\leanok
  \uses{catTorus, catAWPartition}
  \(\operatorname{awSymbFull} : \mathbb{T}^2\to(\operatorname{Fin} 5)^{\mathbb{Z}}\),
  \(\operatorname{awSymbFull} x\,k = \operatorname{awSymb} x\,k\), records the branch symbol of the
  forward orbit of \(x\) at every integer time \(k\), landing in the two-sided full shift on the five
  golden branches.
\end{definition}

n33597.content:
\begin{theorem}[The Adler--Weiss coding is an exact factor map]\label{isFactorMap_awSymbFull}
  \lean{ErgodicTheory.CatMapToral.isFactorMap_awSymbFull}\leanok
  \uses{awSymbFull, catTorus}
  \(\operatorname{awSymbFull}\) is a measure-theoretic factor map from
  \((\mathbb{T}^2, \operatorname{catTorus}, \mathrm{vol})\) onto the two-sided full shift, with the
  intertwining \(\operatorname{awSymbFull}\circ\operatorname{catTorus} = \operatorname{biShiftMap}
  \circ\operatorname{awSymbFull}\) holding \emph{everywhere} (not merely a.e.): the empty junk cell of
  \Cref{awCell_zero_eq_empty} gives every point a well-defined symbol at every time. The pushforward
  concentrates on the golden subshift-of-finite-type carrier, which has full measure \(1\)
  (\lean{ErgodicTheory.CatMapToral.map_awSymbFull_biSFTCarrier}).
\end{theorem}

n33599.content:
\begin{definition}[The coarse Adler--Weiss partition]\label{coarseAWPartition}
  \lean{ErgodicTheory.CatMapToral.coarseAWPartition}\leanok
  \uses{catAWPartition, awCell_zero_eq_empty}
  The two-cell \(\operatorname{MeasurePartition}\) of \(\mathbb{T}^2\) into the two projected golden
  rectangles \(R_1, R_2\); its symbolic factor is the merged itinerary
  \(k\mapsto\operatorname{src}(\operatorname{awSymb} x\,k)\).
\end{definition}

n33600.content:
\begin{theorem}[The coarse entropy ceiling]\label{coarseAWPartition_ksEntropy_le}
  \lean{ErgodicTheory.CatMapToral.coarseAWPartition_ksEntropy_le}\leanok
  \uses{coarseAWPartition, ksEntropyPartition}
  \(h(\operatorname{catTorus}, \operatorname{coarseAWPartition})\le\log 2\), strictly below the system
  entropy \(\log\lambda_+\) (\lean{ErgodicTheory.CatMapToral.log_two_lt_log_lam}): the coarse
  partition, unlike the fine generator, is far from generating. This is the abstract
  \(\log(\operatorname{card})\) ceiling for a partition into two cells.
\end{theorem}

n33601.content:
\begin{theorem}[Strict positivity of the coarse entropy]\label{coarseAW_ksEntropyPartition_pos}
  \lean{ErgodicTheory.CatMapToral.coarseAW_ksEntropyPartition_pos}\leanok
  \uses{coarseAWPartition}
  \(0 < h(\operatorname{catTorus}, \operatorname{coarseAWPartition})\); indeed
  \(\log\lambda_+ - \log 2\le h(\operatorname{catTorus}, \operatorname{coarseAWPartition})\)
  (\lean{ErgodicTheory.CatMapToral.coarseAW_ksEntropyPartition_ge}), strictly positive because
  \(\lambda_+ = (3+\sqrt5)/2 > 2\). The merged symbolic factor is thus a two-symbol system whose
  entropy lies in the nontrivial band \([\log\lambda_+ - \log 2, \log 2]\).
\end{theorem}

n33603.content:
\begin{theorem}[Stage 1 is entropy-preserving]\label{ksEntropy_mapAwSymbFull_eq}
  \lean{ErgodicTheory.CatMapToral.ksEntropy_mapAwSymbFull_eq}\leanok
  \uses{isFactorMap_awSymbFull, injective_awSymbFull, catTorus_ksEntropy_eq}
  The golden-SFT image system \(\operatorname{Measure.map}\,\operatorname{awSymbFull}\,\mathrm{vol}\)
  under the shift has Kolmogorov--Sinai entropy exactly \(\log\!\big((3+\sqrt5)/2\big)\): being an
  injective factor, the Adler--Weiss coding is an \emph{entropy-preserving conjugacy}, so the issue's
  expectation of a strict drop at \emph{every} step is impossible on this stage and is disclosed as
  such.
\end{theorem}

n33607.content:
\begin{proof}\leanok
  \uses{ksJoin}
  This is the generator-free half of the equality
  \(\bigvee_k\sigma(\dots)=\operatorname{comap}T\,m_E\) that holds for a one-sided
  \emph{generating} partition: the reverse containment needs generation, but \(\le\) is
  unconditional. Per term the pulled-back generated \(\sigma\)-algebra equals the comap of \(T\)
  applied to the join's own generated \(\sigma\)-algebra, which is below \(m_E\); \texttt{iSup\_le}
  and monotonicity of comap close the bound. This \(\le\) is precisely what removes the generator
  hypothesis from Rokhlin's inequality below.
\end{proof}

n33612.content:
\begin{lemma}[Nonnegative spectrum collapses the positive-part sum]\label{sumPosExp_eq_sumAllExp_of_nonneg}
  \lean{ErgodicTheory.sumPosExp_eq_sumAllExp_of_nonneg}\leanok
  \uses{exponents}
  If every Lyapunov exponent of the derivative cocycle is nonnegative,
  \(0\le\lambda_i\) for all \(i\), then the positive-part exponent sum equals the full exponent
  sum, \(\sum_i\lambda_i^{+}=\sum_i\lambda_i\).
\end{lemma}

n33613.content:
\begin{proof}\leanok
  \uses{exponents}
  The two finite sums differ only in the summands with \(\lambda_i\le 0\); under the hypothesis
  those are \(\lambda_i=0\), which contribute nothing to either side.
\end{proof}

n33618.content:
\begin{theorem}[Pesin's entropy formula, integral form]\label{pesin_entropy_formula}
  \lean{ErgodicTheory.pesin_entropy_formula}\leanok
  \uses{pesin_entropy_formula_spectral, UnstableJacobianRate}
  Under the same hypotheses, with \(\chi\) an unstable-Jacobian integrand
  (\Cref{UnstableJacobianRate}), the system entropy is the literal Pesin integral
  \[
    h_\mu(T) \;=\; \int_E \Bigl(\sum_{\lambda_i>0}\lambda_i\Bigr)\,d\mu
      \;=\; \int_E \chi\,d\mu .
  \]
\end{theorem}

n33620.content:
\begin{theorem}[Per-partition Pesin identity for the doubling map]\label{pesin_identity_doublingMap_perPartition}
  \lean{ErgodicTheory.Examples.Rokhlin.pesin_identity_doublingMap_perPartition}\leanok
  \uses{ksEntropyPartition_doublingMap_eq_log_two, doublingMap_sumPosExp_eq_log_two}
  For the doubling map and its binary partition, the partition-relative Kolmogorov--Sinai entropy
  equals the sum of the positive Lyapunov exponents, both being \(\log 2\):
  \(h_\mu(T,\alpha)=\sum\lambda^{+}\).
\end{theorem}

n33621.content:
\begin{proof}\leanok
  \uses{ksEntropyPartition_doublingMap_eq_log_two, doublingMap_sumPosExp_eq_log_two}
  The entropy side is \(h_\mu(T,\alpha)=\log 2\)
  (\Cref{ksEntropyPartition_doublingMap_eq_log_two}), the exponent side is
  \(\sum\lambda^{+}=\log 2\) (\Cref{doublingMap_sumPosExp_eq_log_two}); the two agree.
\end{proof}

n33622.content:
\begin{definition}[The dyadic-arc family]\label{dyadicArcSet}
  \lean{ErgodicTheory.Examples.Rokhlin.dyadicArcSet}\leanok
  The set of all \(n\)-fold-join cells of the binary partition under the doubling map,
  \(\bigcap_{k<n}T^{-k}\bigl(\operatorname{binCell}(f(k))\bigr)\) over all lengths \(n\) and digit
  strings \(f:\operatorname{Fin}n\to\operatorname{Fin}2\). Each such set is a dyadic arc of length \(2^{-n}\).
\end{definition}

n33624.content:
\begin{lemma}[One-step doubling recursion]\label{rep_doublingMap}
  \lean{ErgodicTheory.Examples.Rokhlin.rep_doublingMap}\leanok
  \uses{binDigit}
  On the representative, the doubling map acts by \(x\mapsto 2x\) on the left half and
  \(x\mapsto 2x-1\) on the right, uniformly
  \(\operatorname{rep}(Ty)=2\operatorname{rep}(y)-d_0(y)\).
\end{lemma}

n33626.content:
\begin{lemma}[Dynamical partial-sum recursion]\label{rep_eq_binPartialSum_add}
  \lean{ErgodicTheory.Examples.Rokhlin.rep_eq_binPartialSum_add}\leanok
  \uses{rep_doublingMap, binDigit}
  The representative splits into its first \(N\) digits plus a rescaled tail:
  \(\operatorname{rep}(y)=\operatorname{binPartialSum}N(y)+\operatorname{rep}(T^N y)\,2^{-N}\).
\end{lemma}

n33627.content:
\begin{proof}\leanok
  \uses{rep_doublingMap}
  Induction on \(N\), feeding the one-step recursion \Cref{rep_doublingMap} into the tail
  (using that the \(0\)-th digit at \(T^N y\) is the \(N\)-th digit at \(y\)).
\end{proof}

n33629.content:
\begin{proof}\leanok
  \uses{rep_eq_binPartialSum_add}
  The tail remainder \(\operatorname{rep}(T^N y)\,2^{-N}\le 2^{-N}\to 0\) is squeezed to zero, so
  the partial sums converge to \(\operatorname{rep}(y)\) by \Cref{rep_eq_binPartialSum_add}.
\end{proof}

n33630.content:
\begin{lemma}[Digit sets are dyadic-measurable]\label{preimage_iterate_binCell_one_mem}
  \lean{ErgodicTheory.Examples.Rokhlin.preimage_iterate_binCell_one_mem}\leanok
  \uses{dyadicArcSet, binDigit}
  Each digit set \(T^{-n}(\operatorname{binCell}1)\) is the finite union of the generation-\((n+1)\)
  dyadic arcs whose last digit is \(1\), hence \(\operatorname{generateFrom}(\operatorname{dyadicArcSet})\)-measurable.
\end{lemma}

n33631.content:
\begin{proof}\leanok
  \uses{dyadicArcSet}
  A point lies in \(T^{-n}(\operatorname{binCell}1)\) iff its length-\((n+1)\) digit string has last
  digit \(1\); realizing the string as the join cell exhibits the digit set as a finite union of
  arcs from \Cref{dyadicArcSet}.
\end{proof}

n33634.content:
\begin{theorem}[Dyadic arcs generate the Borel structure]\label{borel_le_generateFrom_dyadicArcs}
  \lean{ErgodicTheory.Examples.Rokhlin.borel_le_generateFrom_dyadicArcs}\leanok
  \uses{dyadicArcSet, measurable_rep_dyadic}
  The Borel \(\sigma\)-algebra of the circle lies below the one generated by the dyadic arcs,
  \(m_{\mathbb T}\le\operatorname{generateFrom}(\operatorname{dyadicArcSet})\).
\end{theorem}

n33636.content:
\begin{theorem}[The binary partition generates]\label{binPartition_isGenerating}
  \lean{ErgodicTheory.Examples.Rokhlin.binPartition_isGenerating}\leanok
  \uses{borel_le_generateFrom_dyadicArcs, dyadicArcSet, IsGenerating}
  The binary partition is a one-sided generator for the doubling map:
  \(\bigvee_{n}\operatorname{comap}(T^n)\,\sigma(\alpha)=m_{\mathbb T}\).
\end{theorem}

n33637.content:
\begin{proof}\leanok
  \uses{borel_le_generateFrom_dyadicArcs, dyadicArcSet}
  The easy inclusion \(\le\) is immediate from measurability of the cells under the iterates. For
  \(\ge\): each digit set \(T^{-n}(\operatorname{binCell}i)\) is measurable for the saturated
  \(\sigma\)-algebra, hence each dyadic arc, being a finite intersection of digit sets, is too;
  reducing Borel to the dyadic-arc family by \Cref{borel_le_generateFrom_dyadicArcs} closes the
  reverse containment.
\end{proof}

n33638.content:
\begin{theorem}[Entropy of the doubling map is \(\log 2\)]\label{ksEntropy_doublingMap_eq_log_two}
  \lean{ErgodicTheory.Examples.Rokhlin.ksEntropy_doublingMap_eq_log_two}\leanok
  \uses{binPartition_isGenerating, ksEntropy_eq_ksEntropyPartition_of_generating, ksEntropyPartition_doublingMap_eq_log_two}
  The Kolmogorov--Sinai entropy of the doubling map is \(h_\mu(T)=\log 2\).
\end{theorem}

n33641.content:
\begin{proof}\leanok
  \uses{ksEntropy_doublingMap_eq_log_two, doublingMap_sumPosExp_eq_log_two}
  The system entropy is \(\log 2\) (\Cref{ksEntropy_doublingMap_eq_log_two}) and the
  positive-exponent sum of the constant derivative cocycle \((2)\) is \(\log 2\)
  (\Cref{doublingMap_sumPosExp_eq_log_two}); the two agree.
\end{proof}

n33642.content:
\begin{definition}[Coboundary]\label{def:livsic-coboundary}
  \lean{ErgodicTheory.IsCoboundary}\leanok
  An observable \(\varphi\) is a \emph{coboundary} for a bare map \(T:X\to X\) if
  \(\varphi = u\circ T - u\) for some transfer function \(u:X\to\mathbb{R}\), with no regularity assumed on
  \(u\).
\end{definition}

n33643.content:
\begin{definition}[Hölder coboundary]\label{def:livsic-holdercoboundary}
  \lean{ErgodicTheory.IsHolderCoboundary}\leanok
  \uses{def:livsic-coboundary}
  On a metric space, \(\varphi\) is a \emph{Hölder coboundary} for \(T\) if
  \(\varphi = u\circ T - u\) with \(u\) Hölder continuous (some exponent \(0 < r\), constant \(C\)).
  This is the target regularity of the Livšic theorem; forgetting the modulus of \(u\) shows a
  Hölder coboundary is a coboundary.
\end{definition}

n33644.content:
\begin{definition}[Vanishing periodic sums]\label{def:livsic-vps}
  \lean{ErgodicTheory.HasVanishingPeriodicSums}\leanok
  \(\varphi\) \emph{has vanishing periodic sums} for \(T\) if every Birkhoff sum around a periodic
  orbit vanishes: whenever \(T^n p = p\), one has \(S_n\varphi\,p = \sum_{i<n}\varphi(T^i p) = 0\).
  This is the obstruction class the Livšic theorem certifies as complete.
\end{definition}

n33645.content:
\begin{lemma}[Telescoping identity]\label{lem:livsic-telescope}
  \lean{ErgodicTheory.birkhoffSum_eq_of_coboundary}\leanok
  \uses{def:livsic-coboundary}
  If \(\varphi\,x = u(T x) - u\,x\) for all \(x\), then the Birkhoff sum collapses to the endpoints,
  \(S_n\varphi\,x = u(T^n x) - u\,x\). Pure algebra --- no metric, no regularity, valid for a bare
  \(T\).
\end{lemma}

n33646.content:
\begin{proof}\leanok
  \uses{def:livsic-coboundary}
  Induction on \(n\) through \(\texttt{birkhoffSum\_succ}\): the successor term \(\varphi(T^k x) =
  u(T^{k+1}x) - u(T^k x)\) cancels against the running endpoint, leaving \(u(T^n x) - u\,x\).
\end{proof}

n33647.content:
\begin{theorem}[Trivial direction and its obstruction certificate]\label{thm:livsic-trivial}
  \lean{ErgodicTheory.IsCoboundary.hasVanishingPeriodicSums}\leanok
  \uses{def:livsic-coboundary, def:livsic-vps, lem:livsic-telescope}
  A coboundary has vanishing periodic sums. Contrapositively, a single non-vanishing periodic sum
  defeats \emph{every} coboundary: if \(T^n p = p\) and \(S_n\varphi\,p\ne 0\), then \(\varphi\) is
  not a coboundary of any transfer function
  (\lean{ErgodicTheory.not_isCoboundary_of_periodicSum_ne_zero}).
\end{theorem}

n33652.content:
\begin{lemma}[McShane--Whitney Hölder extension]\label{lem:livsic-mcshane}
  \lean{ErgodicTheory.exists_holderWith_extension}\leanok
  A real-valued function that is \(\texttt{HolderOnWith}\ C\ r\) (exponent \(r\le 1\)) on a subset
  \(s\) of a metric space extends to a global \(\texttt{HolderWith}\ C\ r\) function agreeing with it
  on \(s\), with the \emph{same} constant and exponent.
\end{lemma}

n33654.content:
\begin{theorem}[Abstract existence, Katok--Hasselblatt 19.2.1]\label{thm:livsic-existence}
  \lean{ErgodicTheory.exists_holderCoboundary_of_denseOrbit}\leanok
  \uses{def:livsic-holdercoboundary, def:livsic-vps, def:livsic-expclosing, lem:livsic-crux, lem:livsic-mcshane}
  Let \(T\) be continuous on a compact metric space \(X\), let \(\varphi\) be \(r\)-Hölder
  (\(0 < r\le 1\)), suppose \(T\) has the summed exponential closing property, and suppose some
  point \(x_0\) has a dense forward orbit. If \(\varphi\) has vanishing periodic sums, then
  \(\varphi\) is a Hölder coboundary.
\end{theorem}

n33656.content:
\begin{theorem}[The Livšic equivalence]\label{thm:livsic-iff}
  \lean{ErgodicTheory.isHolderCoboundary_iff}\leanok
  \uses{thm:livsic-trivial, thm:livsic-existence}
  Under the standing hypotheses (continuous \(T\) on a compact metric space, \(r\)-Hölder
  \(\varphi\) with \(0 < r\le 1\), summed exponential closing, and a dense forward orbit),
  \[
    \varphi \text{ is a Hölder coboundary} \iff \varphi \text{ has vanishing periodic sums}.
  \]
\end{theorem}

n33657.content:
\begin{proof}\leanok
  \uses{thm:livsic-trivial, thm:livsic-existence}
  Forward: the pure telescoping obstruction (\Cref{thm:livsic-trivial}). Backward: the dense-orbit
  reconstruction (\Cref{thm:livsic-existence}). This is the interface every concrete instance below
  discharges by supplying continuity, compactness, a closing constant, and a dense orbit.
\end{proof}

n33658.content:
\begin{lemma}[Shift metric substrate]\label{lem:livsic-shiftmetric}
  \lean{ErgodicTheory.Livsic.lipschitzWith_two_shiftMap}\leanok
  The left shift is \(2\)-Lipschitz for the \(\texttt{PiNat}\) ultrametric
  (\lean{ErgodicTheory.Livsic.instIsUltrametricDist_shift}), hence continuous; the full shift over a
  finite discrete alphabet is compact by Tychonoff.
\end{lemma}

n33660.content:
\begin{theorem}[Closing for the full shift]\label{thm:livsic-shift-closing}
  \lean{ErgodicTheory.Livsic.expClosing_shiftMap}\leanok
  \uses{def:livsic-expclosing}
  For every exponent \(\alpha > 0\) the full shift satisfies \(\texttt{ExpClosing}\,\sigma\,\alpha\,1\,K\)
  with \(K = (1/2)^{\alpha}/(1 - (1/2)^{\alpha})\).
\end{theorem}

n33662.content:
\begin{definition}[The rich point]\label{def:livsic-richpoint}
  \lean{ErgodicTheory.Livsic.richPoint}\leanok
  The \emph{rich point} is the sequence obtained by concatenating all finite words (enumerated
  through the alphabet's countable encoding). Every finite word appears as a block, so every target
  is approximated by some forward iterate.
\end{definition}

n33663.content:
\begin{theorem}[Dense orbit for the full shift]\label{thm:livsic-shift-dense}
  \lean{ErgodicTheory.Livsic.exists_denseRange_shiftMap_orbit_alphabet}\leanok
  \uses{def:livsic-richpoint}
  Over a nonempty finite alphabet the forward orbit of the rich point is dense.
\end{theorem}

n33664.content:
\begin{proof}\leanok
  \uses{def:livsic-richpoint}
  To match a target on its first \(N\) coordinates, shift the rich point to the block equal to that
  length-\(N\) prefix; the resulting iterate lies within \((1/2)^{N}\) of the target.
\end{proof}

n33665.content:
\begin{theorem}[Livšic for the one-sided full shift]\label{thm:livsic-fullshift}
  \lean{ErgodicTheory.Livsic.livsic_fullShift}\leanok
  \uses{thm:livsic-iff, lem:livsic-shiftmetric, thm:livsic-shift-closing, thm:livsic-shift-dense}
  For a Hölder \(\varphi\) (exponent \(0 < r\le 1\)) on the full shift over a finite discrete
  alphabet,
  \[
    \varphi \text{ is a Hölder coboundary for } \sigma \iff \varphi \text{ has vanishing periodic sums}.
  \]
\end{theorem}

n33666.content:
\begin{proof}\leanok
  \uses{thm:livsic-iff, lem:livsic-shiftmetric, thm:livsic-shift-closing, thm:livsic-shift-dense}
  Feed \Cref{thm:livsic-iff} the substrate (\Cref{lem:livsic-shiftmetric}), the closing constant
  (\Cref{thm:livsic-shift-closing}, \(\delta = 1\)), and the dense orbit
  (\Cref{thm:livsic-shift-dense}).
\end{proof}

n33670.content:
\begin{theorem}[Closing for the two-sided full shift]\label{thm:livsic-bishift-closing}
  \lean{ErgodicTheory.expClosing_biShiftMap}\leanok
  \uses{def:livsic-expclosing, def:livsic-bishift-metric, lem:livsic-minregime}
  For every \(\alpha>0\) the two-sided full shift \(\tilde\sigma\) is \(2\)-Lipschitz
  (\lean{ErgodicTheory.lipschitzWith_two_biShiftMap}) and satisfies
  \(\texttt{ExpClosing}\,\tilde\sigma\,\alpha\,1\,K\) with \(K = 2/(1 - (1/2)^{\alpha})\) --- twice
  the one-sided constant.
\end{theorem}

n33672.content:
\begin{theorem}[Livšic for the two-sided full shift]\label{thm:livsic-bishift}
  \lean{ErgodicTheory.livsic_biShift}\leanok
  \uses{thm:livsic-iff, def:livsic-bishift-metric, thm:livsic-bishift-closing}
  For a Hölder \(\varphi\) (\(0 < r\le 1\)) on the two-sided full shift, \(\varphi\) is a Hölder
  coboundary for the bilateral shift iff all its periodic Birkhoff sums vanish. The dense forward
  orbit is \lean{ErgodicTheory.exists_denseRange_biShiftMap_orbit} (the one-sided rich point placed
  on the non-negative axis, padded on the negative axis).
\end{theorem}

n33673.content:
\begin{proof}\leanok
  \uses{thm:livsic-iff, thm:livsic-bishift-closing}
  Instantiate \Cref{thm:livsic-iff} with the \(\mathbb{Z}\)-ultrametric, the doubled closing constant, and
  the two-sided dense orbit. Compactness comes with no metric/measure diamond because the metric
  reuses the product topology whose Borel structure carries the two-sided Bernoulli measure.
\end{proof}

n33674.content:
\begin{definition}[The SFT carrier and shift]\label{def:livsic-sft}
  \lean{ErgodicTheory.SFTCarrier}\leanok
  For \(M:\operatorname{Fin}k\to\operatorname{Fin}k\to\texttt{Bool}\), the \emph{carrier}
  \(\texttt{SFTCarrier}\ M = \{x : \forall i,\ M(x_i, x_{i+1})\}\) is the closed shift-invariant set
  of admissible sequences; as a subtype (\lean{ErgodicTheory.SFT}) it inherits the ultrametric and,
  being closed in the compact full shift, is compact. The \emph{SFT shift}
  \lean{ErgodicTheory.sftShiftMap} is the restriction of \(\sigma\), still \(2\)-Lipschitz.
\end{definition}

n33675.content:
\begin{lemma}[The \(\delta = 1/2\) crux]\label{lem:livsic-sft-half}
  \lean{ErgodicTheory.sft_head_eq_of_dist_le_half}\leanok
  \uses{def:livsic-sft}
  If \(x\) almost \(n\)-returns within radius \(1/2\), then \(x_0 = x_n\).
\end{lemma}

n33676.content:
\begin{proof}\leanok
  \uses{def:livsic-sft}
  \(\operatorname{dist}(x,\sigma^n x)\le 1/2\) forces agreement on coordinate \(0\), i.e.\ \(x_0 = (\sigma^n x)_0 =
  x_n\).
\end{proof}

n33677.content:
\begin{theorem}[Closing for the SFT, unconditional in \(M\)]\label{thm:livsic-sft-closing}
  \lean{ErgodicTheory.expClosing_sftShiftMap}\leanok
  \uses{def:livsic-expclosing, def:livsic-sft, lem:livsic-sft-half}
  For every \(\alpha>0\) and \emph{every} transition matrix \(M\), the SFT shift satisfies
  \(\texttt{ExpClosing}\,(\texttt{sftShiftMap}\ M)\,\alpha\,(1/2)\,K\) at the reduced closing radius
  \(\delta = 1/2\), with the same constant \(K = (1/2)^{\alpha}/(1-(1/2)^{\alpha})\) as the full
  shift --- \emph{with no irreducibility hypothesis on \(M\)}.
\end{theorem}

n33680.content:
\begin{theorem}[Dense orbit for an SFT with a safe symbol]\label{thm:livsic-sft-dense}
  \lean{ErgodicTheory.exists_denseRange_sftShiftMap_orbit}\leanok
  \uses{def:livsic-safesymbol, def:livsic-sft}
  If \(M\) has a safe symbol, the SFT shift has a point with dense forward orbit.
\end{theorem}

n33682.content:
\begin{theorem}[Livšic for a one-sided SFT]\label{thm:livsic-sft}
  \lean{ErgodicTheory.livsic_sft}\leanok
  \uses{thm:livsic-iff, def:livsic-sft, thm:livsic-sft-closing}
  For a Hölder \(\varphi\) (\(0 < r\le 1\)) on the SFT and a dense forward orbit under the SFT shift,
  \(\varphi\) is a Hölder coboundary iff all its periodic Birkhoff sums vanish.
\end{theorem}

n33683.content:
\begin{proof}\leanok
  \uses{thm:livsic-iff, thm:livsic-sft-closing}
  Instantiate \Cref{thm:livsic-iff} with the subtype substrate and the unconditional
  \(\delta = 1/2\) closing (\Cref{thm:livsic-sft-closing}); the dense orbit is the sole hypothesis,
  the only place a combinatorial assumption on \(M\) enters.
\end{proof}

n33684.content:
\begin{theorem}[The golden-mean shift, unconditional]\label{thm:livsic-goldenmean}
  \lean{ErgodicTheory.livsic_goldenMean}\leanok
  \uses{thm:livsic-sft, thm:livsic-sft-dense, def:livsic-safesymbol}
  For the golden-mean shift (\lean{ErgodicTheory.goldenMeanM}: forbid the block \(11\), Lind--Marcus
  \S1.2), a Hölder \(\varphi\) (\(0 < r\le 1\)) is a Hölder coboundary iff all its periodic Birkhoff
  sums vanish --- with no external hypotheses.
\end{theorem}

n33686.content:
\begin{theorem}[Dense orbit from ergodicity]\label{thm:livsic-ergodic-dense}
  \lean{ErgodicTheory.ergodic_exists_denseRange_iterate}\leanok
  On a second-countable space with an open-positive probability measure, an ergodic map has a point
  with dense forward orbit.
\end{theorem}

n33688.content:
\begin{theorem}[Closing for the doubling map]\label{thm:livsic-doubling-closing}
  \lean{ErgodicTheory.expClosing_doublingMap}\leanok
  \uses{def:livsic-expclosing}
  For every \(r>0\) the doubling map satisfies \(\texttt{ExpClosing}\ r\ 1\ (2^{r}/(2^{r}-1))\).
\end{theorem}

n33690.content:
\begin{theorem}[Livšic for the doubling map]\label{thm:livsic-doubling}
  \lean{ErgodicTheory.livsic_doublingMap}\leanok
  \uses{thm:livsic-iff, thm:livsic-ergodic-dense, thm:livsic-doubling-closing}
  For a Hölder \(\varphi\) (\(0 < r\le 1\)) on the circle, \(\varphi\) is a Hölder coboundary for the
  doubling map iff all its periodic Birkhoff sums vanish.
\end{theorem}

n33692.content:
\begin{definition}[Covering projection]\label{def:livsic-catproj}
  \lean{ErgodicTheory.CatMapToral.catProj}\leanok
  \(\texttt{catProj}:\mathbb{R}^2\to\mathbb{T}^2\) is the coordinatewise quotient projection; it intertwines the
  linear map \(\texttt{cat}_{\mathbb{R}} = \bigl(\begin{smallmatrix}2&1\\1&1\end{smallmatrix}\bigr)\)
  upstairs with \(\texttt{catTorus}\) downstairs and is distance-nonincreasing.
\end{definition}

n33694.content:
\begin{theorem}[Anosov exact-solve closing]\label{thm:livsic-cat-closing}
  \lean{ErgodicTheory.CatMapToral.expClosing_catTorus}\leanok
  \uses{def:livsic-expclosing, def:livsic-catproj, def:livsic-catshadow}
  For every exponent \(0 < \alpha\le 1\), \(\texttt{catTorus}\) has the summed exponential closing
  property with radius \(1\) and an explicit constant \(2\,C_{\mathrm{sh}}^{\alpha}/(1-\theta^{\alpha})\),
  where \(\theta<1\) is the contraction ratio (the small eigenvalue).
\end{theorem}

n33696.content:
\begin{theorem}[Livšic for the Arnold cat map]\label{thm:livsic-cat}
  \lean{ErgodicTheory.CatMapToral.livsic_catTorus}\leanok
  \uses{thm:livsic-iff, thm:livsic-ergodic-dense, thm:livsic-cat-closing}
  For a Hölder \(\varphi\) (\(0 < r\le 1\)) on \(\mathbb{T}^2\), \(\varphi\) is a Hölder coboundary for the
  Anosov diffeomorphism \(\texttt{catTorus}\) iff all its periodic Birkhoff sums vanish.
\end{theorem}

n33698.content:
\begin{definition}[Almost-everywhere coboundary]\label{def:livsic-aecob}
  \lean{ErgodicTheory.IsAeCoboundaryOf}\leanok
  \(\varphi\) is an \emph{a.e.\ coboundary} of \(u\) over \(\mu\) if \(\varphi = u\circ T - u\) holds
  \(\mu\)-almost-everywhere. This is the measurable analogue of \Cref{def:livsic-coboundary}.
\end{definition}

n33699.content:
\begin{theorem}[Continuous tier]\label{thm:livsic-continuous-tier}
  \lean{ErgodicTheory.Livsic.hasVanishingPeriodicSums_of_continuous_coboundary}\leanok
  \uses{def:livsic-aecob, thm:livsic-trivial}
  If \(\varphi\) is continuous and equals the coboundary of a \emph{continuous} \(u\) only
  \(\mu\)-a.e., for a fully supported \(\mu\) (\(\texttt{IsOpenPosMeasure}\)), then \(\varphi\) has
  vanishing periodic sums.
\end{theorem}

n33701.content:
\begin{theorem}[Bounded tier]\label{thm:livsic-bounded-tier}
  \lean{ErgodicTheory.Livsic.vanishingPeriodicSum_of_bounded_shadowing}\leanok
  \uses{def:livsic-aecob, def:livsic-vps}
  Let \(T\) preserve a probability measure \(\mu\), let \(p\) be \(n\)-periodic, and let
  \(\varphi = u\circ T - u\) \(\mu\)-a.e.\ with \(u\) \emph{bounded} (\(\left\lvert u \right\rvert\le M\)). If each
  cylinder \(D_m\) around \(p\) has positive measure and shadows the Birkhoff sum of \(p\) up to a
  uniform additive constant \(B\), then \(S_n\varphi\,p = 0\).
\end{theorem}

n33705.content:
\begin{lemma}[Product structure]\label{lem:livsic-joinpf}
  \lean{ErgodicTheory.joinPF}\leanok
  The bilateral shift space splits measurably as \(\text{past}\otimes\text{future}\) via
  \(\texttt{joinPF}\), under which the two-sided Bernoulli measure is the product of the past and
  future Bernoulli laws (measure-preservingly).
\end{lemma}

n33707.content:
\begin{lemma}[Stable and unstable essential oscillation]\label{lem:livsic-osc}
  \lean{ErgodicTheory.stable_pair_osc}\leanok
  \uses{def:livsic-aecob, lem:livsic-joinpf}
  For a measurable a.e.\ transfer function of an \(r\)-Hölder \(\varphi\) over the two-sided
  Bernoulli measure, and for a.e.\ \emph{stable} pair (two pasts, one shared future) the values of
  \(u\) differ by at most \(C\theta/(1-\theta)\); symmetrically for a.e.\ \emph{unstable} pair (two
  futures, one shared past), \lean{ErgodicTheory.unstable_pair_osc}.
\end{lemma}

n33709.content:
\begin{theorem}[Essential boundedness of the transfer]\label{thm:livsic-essbdd}
  \lean{ErgodicTheory.essBounded_of_measurable_aeCoboundary_biShift}\leanok
  \uses{lem:livsic-osc, lem:livsic-joinpf}
  A merely measurable (possibly unbounded) a.e.\ solution \(u\) of the cohomological equation over
  the two-sided Bernoulli measure is essentially bounded.
\end{theorem}

n33711.content:
\begin{theorem}[Two-sided measurable headline]\label{thm:livsic-measurable-bishift}
  \lean{ErgodicTheory.hasVanishingPeriodicSums_of_measurable_aeCoboundary_biShift}\leanok
  \uses{thm:livsic-essbdd, thm:livsic-bounded-tier}
  Over a fully supported two-sided Bernoulli measure, an \(r\)-Hölder \(\varphi\) that is the a.e.\
  coboundary of a merely measurable (possibly unbounded) \(u\) has vanishing periodic sums.
\end{theorem}

n33713.content:
\begin{theorem}[One-sided measurable headline]\label{thm:livsic-measurable-oneside}
  \lean{ErgodicTheory.Livsic.hasVanishingPeriodicSums_of_measurable_aeCoboundary}\leanok
  \uses{thm:livsic-measurable-bishift, lem:livsic-toshift}
  Over a fully supported one-sided Bernoulli measure, an \(r\)-Hölder \(\varphi\) that is the a.e.\
  coboundary of a merely measurable transfer function has vanishing periodic sums.
\end{theorem}

n33715.content:
\begin{theorem}[Full measurable Livšic rigidity, Katok--Hasselblatt 19.2.4]\label{thm:livsic-measurable-full}
  \lean{ErgodicTheory.Livsic.livsic_measurable_rigidity}\leanok
  \uses{thm:livsic-measurable-oneside, thm:livsic-fullshift}
  Over a fully supported Bernoulli measure, an \(r\)-Hölder \(\varphi\) (\(0 < r\le 1\)) admits some
  \emph{measurable} a.e.\ transfer function \emph{iff} all its periodic Birkhoff sums vanish.
\end{theorem}

n33718.content:
\begin{theorem}[Flow periodic-orbit obstruction]\label{thm:livsic-flow-obstruction}
  \lean{ErgodicTheory.not_isFlowCoboundary_of_periodicOrbitIntegral_ne_zero}\leanok
  \uses{def:livsic-flowcob}
  If \(\Phi_P q = q\) and the closed-orbit integral \(\int_0^P F(\Phi_s q)\,ds\ne 0\), then \(F\) is
  not a flow coboundary of any transfer function.
\end{theorem}

n33719.content:
\begin{proof}\leanok
  \uses{def:livsic-flowcob}
  The fundamental-theorem-of-calculus telescoping around a closed orbit: a transfer function would
  force the orbit integral to equal \(u(\Phi_P q) - u\,q = u\,q - u\,q = 0\). Needs only a bare flow.
\end{proof}

n33720.content:
\begin{definition}[Induced base observable]\label{def:livsic-induced}
  \lean{ErgodicTheory.inducedBaseCocycle}\leanok
  The \emph{induced base observable} of a flow observable \(F\) is the one-lap roof integral
  \(\texttt{inducedBaseCocycle}\ F\ x = \int_0^{\tau x} F([x,s])\,ds\).
\end{definition}

n33721.content:
\begin{theorem}[A flow coboundary induces a base coboundary]\label{thm:livsic-induced-cob}
  \lean{ErgodicTheory.inducedBaseCocycle_isCoboundary}\leanok
  \uses{def:livsic-flowcob, def:livsic-induced, def:livsic-coboundary}
  If \(F\) is a flow coboundary of the suspension flow with transfer function \(u\), then its induced
  base observable is a discrete coboundary for the base map \(T\), with transfer function
  \(u\circ(x\mapsto[x,0])\).
\end{theorem}

n33723.content:
\begin{theorem}[Tier-1 suspension obstruction]\label{thm:livsic-flow-tier1}
  \lean{ErgodicTheory.not_isFlowCoboundary_of_inducedPeriodicSum_ne_zero}\leanok
  \uses{thm:livsic-induced-cob, thm:livsic-trivial}
  If \(p\) is an \(n\)-periodic base point and the periodic Birkhoff sum of the induced base
  observable does not vanish, then \(F\) is not a flow coboundary of the suspension flow.
\end{theorem}

n33724.content:
\begin{proof}\leanok
  \uses{thm:livsic-induced-cob, thm:livsic-trivial}
  Combine \Cref{thm:livsic-induced-cob} with the discrete obstruction certificate of
  \Cref{thm:livsic-trivial} applied to the induced base observable.
\end{proof}

n33725.content:
\begin{theorem}[The lap bridge]\label{thm:livsic-lap-bridge}
  \lean{ErgodicTheory.suspension_periodicOrbitIntegral_eq_birkhoffSum}\leanok
  \uses{def:livsic-induced}
  The integral of \(F\) around one full closed flow orbit above an \(n\)-periodic base point equals
  the base Birkhoff sum of the induced base observable, identifying the tier-1 and (flow-native)
  tier-2 obstruction quantities.
\end{theorem}

n33726.content:
\begin{proof}\leanok
  \uses{def:livsic-induced}
  The lap decomposition: cut the closed orbit at the successive cross-section returns
  (times \(S_k\tau\,p\)); each lap contributes exactly \(\texttt{inducedBaseCocycle}\ F\ (T^k p)\) by
  a change of variables, and summing the adjacent laps (under per-lap interval integrability)
  reassembles the base Birkhoff sum. The flow-native tier-2 obstruction
  \lean{ErgodicTheory.not_isFlowCoboundary_suspensionFlowMap_of_periodicOrbitIntegral_ne_zero}
  follows by closing a base periodic orbit into a flow-periodic one of period \(S_n\tau\,p\).
\end{proof}

n33727.content:
\begin{theorem}[Non-vacuity: the cat-map suspension flow]\label{thm:livsic-cat-suspension}
  \lean{ErgodicTheory.CatMapToral.const_one_not_isFlowCoboundary_catSuspension}\leanok
  \uses{thm:livsic-flow-tier1}
  The constant observable \(1\) is \emph{not} a flow coboundary of the suspension flow over the
  Arnold cat map under the unit roof \(\tau\equiv 1\).
\end{theorem}

n33731.content:
\begin{theorem}[Tier-III equivalence for constant-roof suspension flows]\label{livsic_suspensionFlow_constRoof}
  \lean{ErgodicTheory.livsic_suspensionFlow_constRoof}\leanok
  \uses{def:livsic-flowcob, def:livsic-induced, thm:livsic-induced-cob, uCover_gen}
  Let \(\Phi = \zeta\) be the suspension flow of \(T\) under a \emph{constant} roof \(\tau\equiv c\),
  let \(F\) be a flow observable with per-fibre interval-integrable restrictions, and suppose the base
  map \(T\) discharges the discrete Livšic converse for the induced base observable --- vanishing
  periodic Birkhoff sums of \(\texttt{inducedBaseCocycle}\,F\) imply it is a discrete coboundary.
  Then
  \[
    F \text{ is a flow coboundary of } \zeta
      \iff \texttt{inducedBaseCocycle}\,F \text{ has vanishing periodic sums.}
  \]
\end{theorem}

n33732.content:
\begin{proof}\leanok
  \uses{thm:livsic-induced-cob, uCover_gen}
  Forward is the general obstruction: a flow coboundary induces a base coboundary
  (\Cref{thm:livsic-induced-cob}), which has vanishing periodic sums (\Cref{thm:livsic-trivial}).
  Backward: vanishing periodic sums feed the base converse to produce a base transfer \(u_0\);
  \Cref{uCover_gen} then makes the fundamental-domain candidate seam-invariant, so it descends
  through the suspension quotient (\lean{ErgodicTheory.suspTransfer}, a \(\texttt{Quotient.lift}\))
  to a genuine flow transfer function verifying the continuous-time coboundary equation
  (\lean{ErgodicTheory.suspTransfer_flow}).
\end{proof}

n33733.content:
\begin{theorem}[Flow-native form]\label{livsic_suspensionFlow_constRoof_orbitIntegral}
  \lean{ErgodicTheory.livsic_suspensionFlow_constRoof_orbitIntegral}\leanok
  \uses{livsic_suspensionFlow_constRoof, thm:livsic-lap-bridge}
  Under the same hypotheses, the obstruction may be phrased directly in flow-native terms: \(F\) is a
  flow coboundary iff every \emph{closed-orbit integral} of \(F\) vanishes --- for every base
  \(n\)-periodic point \(p\), the integral of \(F\) around the corresponding closed flow orbit (of
  period \(S_n\tau\,p\)) is zero.
\end{theorem}

n33734.content:
\begin{proof}\leanok
  \uses{livsic_suspensionFlow_constRoof, thm:livsic-lap-bridge}
  Chain \Cref{livsic_suspensionFlow_constRoof} through the lap-decomposition bridge
  (\Cref{thm:livsic-lap-bridge}), which identifies each closed-orbit flow integral with the base
  Birkhoff sum of the induced observable.
\end{proof}

n33735.content:
\begin{theorem}[Flow-Livšic for the cat-map suspension flow]\label{livsic_catSuspensionFlow}
  \lean{ErgodicTheory.CatMapToral.livsic_catSuspensionFlow}\leanok
  \uses{livsic_suspensionFlow_constRoof, thm:livsic-cat}
  For the suspension flow of \(\operatorname{catTorus}\) under the unit roof \(\tau\equiv 1\), a flow
  observable \(F\) whose induced base observable is Hölder (exponent \(0 < r\le 1\)) and whose fibre
  restrictions are interval-integrable is a flow coboundary \emph{iff} every periodic Birkhoff sum of
  its induced base observable vanishes; equivalently (flow-native form
  \lean{ErgodicTheory.CatMapToral.livsic_catSuspensionFlow_orbitIntegral}) iff every closed-orbit
  integral of \(F\) vanishes.
\end{theorem}

n33736.content:
\begin{proof}\leanok
  \uses{livsic_suspensionFlow_constRoof, thm:livsic-cat}
  Instantiate \Cref{livsic_suspensionFlow_constRoof} at \(c = 1\), discharging the base converse with
  the Hölder Livšic theorem for the cat map (\Cref{thm:livsic-cat}, \(\texttt{livsic\_catTorus}\)).
\end{proof}

n33739.content:
\begin{definition}[Hölder flow coboundary]\label{IsHolderFlowCoboundary}
  \lean{ErgodicTheory.IsHolderFlowCoboundary}\leanok
  \uses{def:livsic-flowcob, embDist}
  On the Bowen--Walters metric space \(\operatorname{SuspensionSpace} T\,\tau\) (constant roof \(1\)),
  a flow observable \(F\) is a \emph{Hölder flow coboundary} if it is a flow coboundary
  (\Cref{def:livsic-flowcob}) whose transfer function \(u\) is \(\operatorname{embDist}\)-Hölder:
  \(\left\lvert u\,p - u\,q \right\rvert\le C\,\operatorname{embDist}(p, q)^{r}\) for some \(0 < r\le 1\), \(C\).
  Forgetting the modulus (\lean{ErgodicTheory.IsHolderFlowCoboundary.isFlowCoboundary}) shows a
  Hölder flow coboundary is a flow coboundary.
\end{definition}

n33740.content:
\begin{lemma}[The induced base observable is Hölder]\label{holderWith_inducedBaseCocycle}
  \lean{ErgodicTheory.holderWith_inducedBaseCocycle}\leanok
  \uses{def:livsic-induced, IsHolderFlowCoboundary}
  If \(F\) is \(\operatorname{embDist}\)-\(r\)-Hölder and \(T\) is Lipschitz, the induced base
  observable \(\operatorname{inducedBaseCocycle} T\,\tau\,F\) is \(r\)-Hölder on the base --- the
  regularity input the base Livšic converse consumes.
\end{lemma}

n33742.content:
\begin{theorem}[Cross-seam Hölder gluing]\label{holderWith_suspTransfer}
  \lean{ErgodicTheory.holderWith_suspTransfer}\leanok
  \uses{holderWith_inducedBaseCocycle, uCover_gen, embDist}
  For an \(\operatorname{embDist}\)-\(r\)-Hölder, bounded \(F\) and a base transfer function \(u_0\)
  cobounding the induced base observable, the fundamental-domain candidate
  \(\operatorname{uCover}(x, s) = u_0(x) + \int_0^{s} F[x, \sigma]\,d\sigma\) descends to a transfer
  function that is Hölder for the embedding metric. This cross-seam gluing is the substantive content
  of the theorem.
\end{theorem}

n33746.content:
\begin{theorem}[Hölder flow-Livšic, variable Lipschitz roof]\label{livsic_holderFlow_varRoof}
  \lean{ErgodicTheory.livsic_holderFlow_varRoof}\leanok
  \uses{livsic_holderFlow_constRoof, embDistVar}
  The equivalence extends to a \emph{variable} roof \(\tau\) that is bounded below by
  \(\rho_{\min} > 0\), bounded above, and \emph{Lipschitz}, measured against the variable-roof
  Bowen--Walters metric \(\operatorname{embDistVar}\) of \Cref{embDistVar}: an
  \(\operatorname{embDistVar}\)-\(r\)-Hölder bounded \(F\) is a Hölder flow coboundary iff its induced
  base observable has vanishing periodic sums.
\end{theorem}

n33748.content:
\begin{theorem}[Hölder flow-Livšic for the cat-map suspension flow]\label{livsic_catSuspensionHolderFlow}
  \lean{ErgodicTheory.CatMapToral.livsic_catSuspensionHolderFlow}\leanok
  \uses{livsic_holderFlow_constRoof, thm:livsic-cat}
  For the suspension flow of \(\operatorname{catTorus}\) under the unit roof \(\tau\equiv 1\), a flow
  observable \(F\) that is \(\operatorname{embDist}\)-Hölder (\(0 < r\le 1\)) and bounded, with
  interval-integrable fibre restrictions, is a \emph{Hölder} flow coboundary iff every periodic
  Birkhoff sum of its induced base observable vanishes --- equivalently
  (\lean{ErgodicTheory.CatMapToral.livsic_catSuspensionHolderFlow_orbitIntegral}) iff every closed-orbit
  integral of \(F\) vanishes.
\end{theorem}

n33753.content:
\begin{lemma}[Eigenvalues form a probability vector]\label{DensityMatrix.sum_eigenvalues_eq_one}
  \lean{ErgodicTheory.OperatorEntropy.DensityMatrix.sum_eigenvalues_eq_one}\leanok
  \uses{DensityMatrix}
  The real eigenvalues \(\lambda_i\) of a density matrix \(\rho\) are nonnegative, each at most
  \(1\), and sum to \(1\): \(\sum_i \lambda_i = \Tr\rho = 1\).
\end{lemma}

n33755.content:
\begin{definition}[Von Neumann entropy]\label{vonNeumannEntropy}
  \lean{ErgodicTheory.OperatorEntropy.vonNeumannEntropy}\leanok
  \uses{DensityMatrix}
  The \emph{von Neumann entropy} of a density matrix \(\rho\) with eigenvalues \(\lambda_i\) is
  \[
    S(\rho) \;=\; \sum_i \operatorname{negMulLog}(\lambda_i) \;=\; -\sum_i \lambda_i\log\lambda_i,
  \]
  using Mathlib's \(\operatorname{negMulLog}(x) = -x\log x\), so the convention \(0\log 0 = 0\) is
  built in.
\end{definition}

n33756.content:
\begin{theorem}[Nonnegativity of entropy]\label{vonNeumannEntropy_nonneg}
  \lean{ErgodicTheory.OperatorEntropy.vonNeumannEntropy_nonneg}\leanok
  \(S(\rho)\ge 0\) for every density matrix \(\rho\).
\end{theorem}

n33757.content:
\begin{proof}\leanok
  \uses{vonNeumannEntropy, DensityMatrix.sum_eigenvalues_eq_one}
  Each eigenvalue satisfies \(0\le\lambda_i\le 1\), and on \([0,1]\) one has
  \(\operatorname{negMulLog}(x) = -x\log x\ge 0\). The entropy is a sum of these nonnegative
  terms.
\end{proof}

n33759.content:
\begin{lemma}[Partial trace preserves the trace]\label{trace_partialTraceRight}
  \lean{ErgodicTheory.OperatorEntropy.trace_partialTraceRight}\leanok
  \uses{partialTraceRight}
  \(\Tr(\Tr_B M) = \Tr M\).
\end{lemma}

n33760.content:
\begin{proof}\leanok
  \uses{partialTraceRight}
  Both sides expand to the full double sum \(\sum_{i,j} M_{(i,j),(i,j)}\) over the product index
  set; a reindexing of the finite sum finishes.
\end{proof}

n33761.content:
\begin{lemma}[Partial trace is completely positive]\label{PosSemidef.partialTraceRight}
  \lean{ErgodicTheory.OperatorEntropy.PosSemidef.partialTraceRight}\leanok
  \uses{partialTraceRight}
  If \(M\) is positive semidefinite then so is \(\Tr_B M\).
\end{lemma}

n33765.content:
\begin{lemma}[A state has positive rank]\label{DensityMatrix.rank_pos}
  \lean{ErgodicTheory.OperatorEntropy.DensityMatrix.rank_pos}\leanok
  \uses{DensityMatrix, DensityMatrix.sum_eigenvalues_eq_one}
  The rank of a density matrix is strictly positive, \(0 < \operatorname{rank}\rho\).
\end{lemma}

n33766.content:
\begin{proof}\leanok
  \uses{DensityMatrix.sum_eigenvalues_eq_one}
  The eigenvalues sum to \(1\ne 0\) (\Cref{DensityMatrix.sum_eigenvalues_eq_one}), so at least one
  is nonzero; the rank of a Hermitian matrix is the number of nonzero eigenvalues
  (\(\texttt{IsHermitian.rank\_eq\_card\_non\_zero\_eigs}\)), hence at least \(1\).
\end{proof}

n33769.content:
\begin{corollary}[Bound by the ambient dimension]\label{vonNeumannEntropy_le_log_card}
  \lean{ErgodicTheory.OperatorEntropy.vonNeumannEntropy_le_log_card}\leanok
  \(S(\rho)\le\log(\#n)\), the logarithm of the ambient Hilbert-space dimension.
\end{corollary}

n33770.content:
\begin{proof}\leanok
  \uses{vonNeumannEntropy_le_log_rank}
  The rank never exceeds the number of columns, \(\operatorname{rank}\rho\le\#n\); monotonicity of
  \(\log\) applied to \Cref{vonNeumannEntropy_le_log_rank} gives the bound.
\end{proof}

n33771.content:
\begin{theorem}[Strict positivity off the pure states]\label{vonNeumannEntropy_pos_of_sq_ne}
  \lean{ErgodicTheory.OperatorEntropy.vonNeumannEntropy_pos_of_sq_ne}\leanok
  If a density matrix is not idempotent (\(\rho^2\ne\rho\)) then its von Neumann entropy is strictly
  positive, \(0 < S(\rho)\). Equivalently, a zero-entropy state is a pure state --- a rank-one
  projection.
\end{theorem}

n33773.content:
\begin{definition}[Block-inclusion Kraus operators]\label{krausInclusionRight}
  \lean{ErgodicTheory.OperatorEntropy.krausInclusionRight}\leanok
  For each \(j\in n_B\), the \emph{right block-inclusion operator}
  \(E_j\in\operatorname{Matrix}_{n_A,\,n_A\times n_B}(\mathbb{C})\) is the co-isometry onto the \(A\)-factor picking out the
  \(j\)-th \(B\)-slice,
  \[
    (E_j)_{a,\,(a',j')} \;=\; [\,(a',j') = (a,j)\,].
  \]
  The \emph{left block-inclusion operator} \(F_i\in\operatorname{Matrix}_{n_B,\,n_A\times n_B}(\mathbb{C})\),
  \lean{ErgodicTheory.OperatorEntropy.krausInclusionLeft}
  \((F_i)_{b,\,(i',b')} = [\,(i',b') = (i,b)\,]\), is defined symmetrically for the \(A\)-factor.
\end{definition}

n33774.content:
\begin{lemma}[Kraus conjugation is a block compression]\label{krausConjRight_eq_submatrix}
  \lean{ErgodicTheory.OperatorEntropy.krausConjRight_eq_submatrix}\leanok
  \uses{krausInclusionRight}
  The conjugation \(E_j M E_j^{*}\) is exactly the \((j,j)\)-diagonal block of \(M\), the submatrix
  \(M_{(a,j),(a',j)}\) on the \(A\)-index.
\end{lemma}

n33775.content:
\begin{proof}\leanok
  \uses{krausInclusionRight}
  Entrywise: the two \(E_j\)-factors select the row index \((a,j)\) and column index \((a',j)\)
  through the indicator, leaving \(M_{(a,j),(a',j)}\), which is the asserted \(\texttt{submatrix}\).
\end{proof}

n33777.content:
\begin{proof}\leanok
  \uses{partialTraceRight, krausConjRight_eq_submatrix}
  By \Cref{krausConjRight_eq_submatrix} each summand \(E_j M E_j^{*}\) is the \(j\)-th diagonal block
  submatrix; summing the diagonal blocks over \(j\) is precisely the block-compression form of the
  partial trace already established for \(\Tr_B\) (and symmetrically for \(\Tr_A\)).
\end{proof}

n33778.content:
\begin{lemma}[Co-isometry of each block inclusion]\label{krausInclusionRight_mul_conjTranspose}
  \lean{ErgodicTheory.OperatorEntropy.krausInclusionRight_mul_conjTranspose}\leanok
  \uses{krausInclusionRight}
  Each block inclusion is a co-isometry onto its factor: for every \(j\),
  \(E_j E_j^{*} = 1\) on \(\mathbb{C}^{n_A}\), and symmetrically \(F_i F_i^{*} = 1\) on \(\mathbb{C}^{n_B}\)
  \lean{ErgodicTheory.OperatorEntropy.krausInclusionLeft_mul_conjTranspose}.
\end{lemma}

n33779.content:
\begin{proof}\leanok
  \uses{krausInclusionRight}
  \((E_j E_j^{*})_{a,a'} = \sum_{(a'',j')}[\,(a'',j') = (a,j)\,][\,(a'',j') = (a',j)\,]
  = [\,a = a'\,]\), the identity on the \(A\)-factor.
\end{proof}

n33785.content:
\begin{theorem}[Klein / Gibbs nonnegativity]\label{relEntropy_nonneg}
  \lean{ErgodicTheory.OperatorEntropy.relEntropy_nonneg}\leanok
  For faithful (positive definite) \(\sigma\), \(\;0\le S(\rho\|\sigma)\).
\end{theorem}

n33787.content:
\begin{theorem}[Vanishing on the diagonal]\label{relEntropy_self_eq_zero}
  \lean{ErgodicTheory.OperatorEntropy.relEntropy_self_eq_zero}\leanok
  \(S(\rho\|\rho) = 0\) for every density matrix \(\rho\).
\end{theorem}

n33788.content:
\begin{proof}\leanok
  \uses{relEntropy}
  With \(\sigma = \rho\) the overlap matrix \(Q = \rho.\mathrm{eigVec}^{*}\,\rho.\mathrm{eigVec}
  = 1\), so \(D_{km} = \delta_{km}\). The cross double sum collapses to \(\sum_k p_k\log p_k\),
  exactly cancelling the first term.
\end{proof}

n33789.content:
\begin{theorem}[Unitary invariance]\label{relEntropy_conj_invariant}
  \lean{ErgodicTheory.OperatorEntropy.relEntropy_conj_invariant}\leanok
  For any unitary \(W\), \(\;S(W\rho W^{*}\,\|\,W\sigma W^{*}) = S(\rho\|\sigma)\), where
  \(W\rho W^{*}\) denotes the density matrix
  \lean{ErgodicTheory.OperatorEntropy.DensityMatrix.conj}
  obtained by conjugating \(\rho\).
\end{theorem}

n33791.content:
\begin{theorem}[Ancilla invariance]\label{relEntropy_ancilla_invariant}
  \lean{ErgodicTheory.OperatorEntropy.relEntropy_ancilla_invariant}\leanok
  Tensoring both arguments with a common faithful ancilla \(\alpha\) leaves the relative entropy
  unchanged: for faithful \(\sigma\) and faithful \(\alpha\),
  \(S(\rho\otimes\alpha\,\|\,\sigma\otimes\alpha) = S(\rho\|\sigma)\).
\end{theorem}

n33792.content:
\begin{proof}\leanok
  \uses{relEntropy, relEntropy_self_eq_zero}
  Relative entropy is additive over Kronecker products,
  \(S(\rho\otimes\alpha\,\|\,\sigma\otimes\alpha) = S(\rho\|\sigma) + S(\alpha\|\alpha)\), and the
  self-term vanishes by \Cref{relEntropy_self_eq_zero}.
\end{proof}

n33797.content:
\begin{theorem}[Operator convexity of \(-\log\)]\label{operatorConvexOn_neg_log}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.operatorConvexOn_neg_log}\leanok
  The function \(x\mapsto -\log x\) is operator convex on \((0,\infty)\): for every matrix
  dimension its continuous functional calculus is convex in the Loewner order on the self-adjoint
  matrices with spectrum in \((0,\infty)\).
\end{theorem}

n33802.content:
\begin{theorem}[Effros' theorem: joint convexity of the perspective]\label{operatorPerspective_jointly_convex}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.operatorPerspective_jointly_convex}\leanok
  Let \(f\) be operator convex on \(I\), let \(R_1,R_2\) be positive definite with the sandwiched
  arguments \(R_i^{-1/2}L_iR_i^{-1/2}\) self-adjoint and with spectra in \(I\), and let
  \(c\in[0,1]\). Then
  \[
    P_f\bigl(cL_1 + (1-c)L_2,\;cR_1 + (1-c)R_2\bigr) \;\le\;
      c\,P_f(L_1,R_1) + (1-c)\,P_f(L_2,R_2).
  \]
\end{theorem}

n33804.content:
\begin{definition}[Operator perspective at a general index]\label{opPersp}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.opPersp}\leanok
  The same formula \(P_f(L,R) = R^{1/2}f(R^{-1/2}LR^{-1/2})R^{1/2}\) for matrices indexed by an
  arbitrary finite type \(m\) (rather than \(\operatorname{Fin}N\)).
\end{definition}

n33805.content:
\begin{theorem}[Effros' theorem at a general finite index]\label{opPersp_jointly_convex}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.opPersp_jointly_convex}\leanok
  Under the same hypotheses as \Cref{operatorPerspective_jointly_convex}, joint convexity of
  \(\mathrm{opPersp}\,f\) holds over an arbitrary finite index type \(m\).
\end{theorem}

n33807.content:
\begin{lemma}[Logarithm of a Kronecker product]\label{cfc_log_kron}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.cfc_log_kron}\leanok
  For positive-definite \(A,B\), \(\ \log(A\otimes B) = \log A\otimes 1 + 1\otimes\log B\).
\end{lemma}

n33813.content:
\begin{definition}[Trace-form relative entropy]\label{relEntropyMat}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.relEntropyMat}\leanok
  For matrices \(\rho,\sigma\), the trace-form relative entropy is
  \(\mathrm{relEntropyMat}(\rho,\sigma) = \Re\,\Tr\bigl(\rho\,(\log\rho - \log\sigma)\bigr)\), the
  logarithms taken through the continuous functional calculus.
\end{definition}

n33818.content:
\begin{theorem}[Bridge to the spectral relative entropy]\label{relEntropyMat_eq_relEntropy}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.relEntropyMat_eq_relEntropy}\leanok
  For density matrices \(\rho,\sigma\) with \(\sigma\) faithful (positive definite),
  \(\mathrm{relEntropyMat}(\rho,\sigma) = S(\rho\|\sigma)\), the Umegaki relative entropy.
\end{theorem}

n33823.content:
\begin{theorem}[Partial-trace DPI, unconditional]\label{relEntropyMonotone_partialTrace}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.relEntropyMonotone_partialTrace}\leanok
  The proposition \texttt{RelEntropyMonotoneUnderPartialTrace} holds: the faithfulness hypothesis
  on \(\rho\) is unnecessary, so \(S(\Tr_E\rho\|\Tr_E\sigma)\le S(\rho\|\sigma)\) for every
  \(\rho\) and every faithful \(\sigma\).
\end{theorem}

n33825.content:
\begin{lemma}[Tracing out an adjoined ancilla is the identity]\label{partialTraceRight_kron}
  \lean{ErgodicTheory.OperatorEntropy.partialTraceRight_kron}\leanok
  \uses{partialTraceRight}
  For any state \(\rho\) and any ancilla state \(\alpha\), \(\Tr_E(\rho\otimes\alpha) = \rho\).
\end{lemma}

n33828.content:
\begin{proof}\leanok
  \uses{relEntropy_conj_invariant, relEntropy_ancilla_invariant}
  Unitary conjugation leaves relative entropy invariant (\Cref{relEntropy_conj_invariant}),
  reducing the claim to \(S(\rho\otimes\alpha\|\sigma\otimes\alpha) = S(\rho\|\sigma)\), which is
  ancilla additivity (\Cref{relEntropy_ancilla_invariant}) for the faithful ancilla \(\alpha\).
\end{proof}

n33832.content:
\begin{proof}\leanok
  \uses{stinespring_relEntropy_monotone, relEntropyMonotone_partialTrace}
  Feed the now-discharged partial-trace DPI (\Cref{relEntropyMonotone_partialTrace}) into the
  Stinespring reduction (\Cref{stinespring_relEntropy_monotone}), removing its hypothesis.
\end{proof}

n33835.content:
\begin{corollary}[No Stinespring recovery under a strict drop]\label{no_stinespring_section_of_strict_relEntropy_drop}
  \lean{ErgodicTheory.OperatorEntropy.no_stinespring_section_of_strict_relEntropy_drop}\leanok
  Unconditionally: a strict relative-entropy drop under a coarse-graining \(\Lambda\) (an
  endomorphism of the input space) rules out \emph{any} Stinespring recovery channel
  \(R\,x = \Tr_E(U(x\otimes\alpha)U^{*})\) inverting \(\Lambda\) on \(\rho,\sigma\).
\end{corollary}

n33836.content:
\begin{proof}\leanok
  \uses{no_section_of_strict_relEntropy_drop, monotonicity_relEntropy_under_stinespring}
  Specialize \Cref{no_section_of_strict_relEntropy_drop} to the Stinespring recovery map, whose
  faithful data-processing monotonicity is exactly \Cref{monotonicity_relEntropy_under_stinespring}.
\end{proof}

n33838.content:
\begin{lemma}[Trace preservation]\label{KrausChannel.toMat_trace}
  \lean{ErgodicTheory.OperatorEntropy.KrausChannel.toMat_trace}\leanok
  \uses{KrausChannel}
  A Kraus channel is trace preserving, \(\tr(\Lambda X)=\tr X\) for every \(X\); consequently the
  adjoint is unital, \(\Lambda^{\dagger}(1)=1\) (Lean: \texttt{adj\_unital}).
\end{lemma}

n33839.content:
\begin{proof}\leanok
  \uses{KrausChannel}
  By trace cyclicity \(\tr(K_i X K_i^{\dagger})=\tr(K_i^{\dagger}K_i\,X)\); summing over \(i\) and
  applying \(\sum_i K_i^{\dagger}K_i=1\) collapses the sum to \(\tr X\). Unitality of
  \(\Lambda^{\dagger}\) is the same completeness relation read at \(X=1\).
\end{proof}

n33840.content:
\begin{definition}[Petz recovery map]\label{petz}
  \lean{ErgodicTheory.OperatorEntropy.petz}\leanok
  \uses{KrausChannel}
  For a state \(\sigma\) and a channel \(\Lambda\), the \emph{Petz (transpose) recovery map} is
  \[
    P_{\sigma,\Lambda}(X) \;=\;
      \sqrt{\sigma}\;\Lambda^{\dagger}\!\bigl((\Lambda\sigma)^{-1/2}\,X\,(\Lambda\sigma)^{-1/2}\bigr)\,
      \sqrt{\sigma},
  \]
  realised through the continuous functional calculus (\texttt{CFC.conjSqrt} for the
  \(\sqrt{\cdot}\)-conjugations and the ring inverse for \((\Lambda\sigma)^{-1/2}\)).
\end{definition}

n33848.content:
\begin{proof}
  \uses{rect_isometry_neg_log_loewner}
  Stack the Kraus operators into the column isometry \(V\) and let
  \(X_{\mathrm{bd}}\) be the block-diagonal amplification of \(X\). Then
  \(V^{\dagger}X_{\mathrm{bd}}V=\sum_i K_i^{\dagger}XK_i\) and, since \(-\log\) commutes with block
  diagonals, \(V^{\dagger}(-\log)(X_{\mathrm{bd}})V=\sum_i K_i^{\dagger}(-\log)(X)K_i\). Apply
  Theorem~\ref{rect_isometry_neg_log_loewner} to \((V,X_{\mathrm{bd}})\).
\end{proof}

n33852.content:
\begin{proof}\leanok
  \uses{kronForm_re_eq_relEntropy}
  Since \(W\xi=\operatorname{vec}(\rho^{1/2})\) (cyclicity of the channel contraction), the left form
  is \(S(\rho\|\sigma)\) and the right form is \(S(\Lambda\rho\|\Lambda\sigma)\) by
  Lemma~\ref{kronForm_re_eq_relEntropy}; the entropy equality is precisely their coincidence.
\end{proof}

n33861.content:
\begin{theorem}[Channel unitary-power intertwining]\label{channel_upow_intertwine}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.channel_upow_intertwine}\leanok
  Under entropy saturation, the channel contraction intertwines the modular unitary power on the
  output cyclic vector, \(W\bigl(\Delta_{\mathrm{out}}^{it}\,\xi\bigr)=\Delta^{it}\,(W\xi)\), with
  \(W\xi=\operatorname{vec}(\rho^{1/2})\).
\end{theorem}

n33862.content:
\begin{proof}\leanok
  \uses{contraction_cfc_intertwine, channel_modular_gap}
  Apply Lemma~\ref{contraction_cfc_intertwine} with \(g=\cos(t\log\cdot)\) and \(g=\sin(t\log\cdot)\);
  the scalar saturation input is Theorem~\ref{channel_modular_gap}. The complex power \(\Delta^{it}\)
  is the functional-calculus combination \(\cos(t\log\cdot)+i\sin(t\log\cdot)\), so the two
  intertwinings combine to the unitary-power intertwining.
\end{proof}

n33864.content:
\begin{theorem}[Equality \(\Rightarrow\) modular intertwining (general channel)]\label{channel_equality_imp_intertwinesIt}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.channel_equality_imp_intertwinesIt}\leanok
  For any Kraus channel with all four states faithful, saturation
  \(S(\rho\|\sigma)=S(\Lambda\rho\|\Lambda\sigma)\) implies \texttt{IntertwinesIt}.
\end{theorem}

n33866.content:
\begin{theorem}[Modular intertwining \(\Rightarrow\) Petz recovery]\label{intertwinesIt_imp_recovery}
  \lean{ErgodicTheory.OperatorEntropy.Lieb.intertwinesIt_imp_recovery}\leanok
  If \texttt{IntertwinesIt} holds (all four states faithful), then the Petz map recovers the input:
  \(P_{\sigma,\Lambda}(\Lambda\rho)=\rho\).
\end{theorem}

n33875.content:
\begin{definition}[Operational partition of unity]\label{OperationalPartition}
  \lean{ErgodicTheory.OperatorEntropy.CNT.OperationalPartition}\leanok
  An \emph{operational partition of unity} of size \(k\) is a family \((x_i)_{i<k}\) of operators in
  \(\operatorname{Matrix}_d(\mathbb{C})\) satisfying the partition-of-unity relation \(\sum_i x_i^{\dagger}x_i=1\).
  This is the noncommutative analogue of a measurable partition of the state space.
\end{definition}

n33877.content:
\begin{lemma}[Telescoping identity]\label{sum_refine_conjTranspose_mul_refine}
  \lean{ErgodicTheory.OperatorEntropy.CNT.sum_refine_conjTranspose_mul_refine}\leanok
  The refinement of an operational partition of unity is again an operational partition of unity: for
  every \(n\),
  \[
    \sum_{f\in(\operatorname{Fin}k)^{\operatorname{Fin}n}}
      \bigl(\mathrm{refine}\,\Phi\,X\,n\,f\bigr)^{\dagger}\,
      \bigl(\mathrm{refine}\,\Phi\,X\,n\,f\bigr) \;=\; 1 .
  \]
\end{lemma}

n33879.content:
\begin{definition}[Correlation density matrix]\label{corrMatrix}
  \lean{ErgodicTheory.OperatorEntropy.CNT.corrMatrix}\leanok
  \uses{refine, sum_refine_conjTranspose_mul_refine}
  For a dynamics \(\Phi\), a state \(\rho\) (a density matrix on \(\mathbb{C}^d\)) and an operational
  partition \(X\), the depth-\(n\) \emph{correlation density matrix}
  \(\mathrm{corrMatrix}\,\Phi\,\rho\,X\,n\) is the matrix on the classical index set
  \((\operatorname{Fin}k)^{\operatorname{Fin}n}\) with entries
  \[
    (g,f)\;\longmapsto\;
      \tr\!\bigl(\rho\,(\mathrm{refine}\,\Phi\,X\,n\,g)^{\dagger}\,\mathrm{refine}\,\Phi\,X\,n\,f\bigr).
  \]
  It is a genuine density matrix: its trace is \(1\) by the telescoping identity
  (Lemma~\ref{sum_refine_conjTranspose_mul_refine}) together with \(\tr\rho=1\), and it is positive
  semidefinite because the quadratic form \(x^{\dagger}Mx\) equals \(\tr(T\rho T^{\dagger})\ge 0\) for
  \(T=\sum_f x_f\,\mathrm{refine}(n,f)\).
\end{definition}

n33881.content:
\begin{definition}[Diagonal state]\label{densityOfPMF}
  \lean{ErgodicTheory.OperatorEntropy.CNT.densityOfPMF}\leanok
  For a probability vector \(\mu:\operatorname{Fin}d\to\mathbb{R}_{\ge 0}\) (\(\sum_i\mu_i=1\)), the associated diagonal
  state is \(\rho_\mu=\operatorname{diag}\mu\), a density matrix on \(\mathbb{C}^d\).
\end{definition}

n33882.content:
\begin{definition}[Projection partition]\label{projPartition}
  \lean{ErgodicTheory.OperatorEntropy.CNT.projPartition}\leanok
  \uses{OperationalPartition}
  For a cell map \(c:\operatorname{Fin}d\to\operatorname{Fin}k\), the diagonal \emph{projection partition} is
  \(\{\operatorname{diag}\mathbf 1_{c^{-1}(i)}\}_{i<k}\); it is an operational partition of unity
  encoding the measurable partition \(c^{-1}(\cdot)\) of \(\operatorname{Fin}d\).
\end{definition}

n33883.content:
\begin{definition}[The permutation dynamics (abelian corner)]\label{adPerm}
  \lean{ErgodicTheory.OperatorEntropy.CNT.adPerm}\leanok
  \uses{UnitalStarEndo}
  For a permutation \(\sigma\in\mathfrak{S}_d\), the \emph{permutation dynamics}
  \(\mathrm{adPerm}\,\sigma\) is conjugation \(x\mapsto P_\sigma\,x\,P_\sigma^{\dagger}\) by the
  permutation matrix, a unital \(*\)-endomorphism; on diagonal matrices it acts by
  \((\mathrm{adPerm}\,\sigma)(\operatorname{diag}v)=\operatorname{diag}(v\circ\sigma)\). Paired with a
  \(\sigma\)-invariant diagonal state \(\rho_\mu\) (\(\mu\circ\sigma=\mu\),
  Definition~\ref{densityOfPMF}) and a projection partition (Definition~\ref{projPartition}), this is
  the abelian corner: it mirrors the classical system \((\operatorname{Fin}d,\mu,\sigma)\) with the measurable
  partition \(c^{-1}(\cdot)\).
\end{definition}

n33888.content:
\begin{definition}[Abelian-corner CNT entropy]\label{cntDynamicalEntropyAbelian}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntDynamicalEntropyAbelian}\leanok
  \uses{cntDynamicalEntropy}
  The \emph{abelian-corner CNT dynamical entropy} of \(\mathrm{adPerm}\,\sigma\) in the state
  \(\rho_\mu\) is the supremum of the partition rate over all \emph{projection} operational
  partitions, \(h^{\mathrm{ab}}_{\mathrm{adPerm}\,\sigma}(\rho_\mu)
  =\sup_{k,c}h_{\mathrm{adPerm}\,\sigma}(\rho_\mu,\mathrm{projPartition}\,c)\).
\end{definition}

n33893.content:
\begin{definition}[Hilbert--Schmidt Gram vectors]\label{gramVec}
  \lean{ErgodicTheory.OperatorEntropy.CNT.gramVec}\leanok
  \uses{refine, corrMatrix}
  For a dynamics \(\Phi\), a state \(\rho\) on \(\mathbb{C}^{d}\) and an operational partition \(X\),
  the depth-\(n\) \emph{Gram vectors} are the Hilbert--Schmidt vectors
  \(w_f = (\mathrm{refine}\,\Phi\,X\,n\,f)\cdot\sqrt{\rho}\), reshaped into the matrix
  \(\mathrm{gramVec}\,\Phi\,\rho\,X\,n\) with rows indexed by \(\operatorname{Fin}d\times\operatorname{Fin}d\) and columns by
  the classical index set \((\operatorname{Fin}k)^{\operatorname{Fin}n}\); here \(\sqrt{\rho} = \texttt{CFC.sqrt}\,\rho\) is
  the continuous-functional-calculus positive-semidefinite square root.
\end{definition}

n33894.content:
\begin{theorem}[Gram factorization of the correlation matrix]\label{corrVal_eq_conjTranspose_mul_self}
  \lean{ErgodicTheory.OperatorEntropy.CNT.corrVal_eq_conjTranspose_mul_self}\leanok
  \uses{gramVec, corrMatrix}
  The CNT correlation matrix is the Gram matrix of its Hilbert--Schmidt vectors:
  \[
    \mathrm{corrMatrix}\,\Phi\,\rho\,X\,n
      \;=\; (\mathrm{gramVec}\,\Phi\,\rho\,X\,n)^{\dagger}\,(\mathrm{gramVec}\,\Phi\,\rho\,X\,n).
  \]
\end{theorem}

n33896.content:
\begin{theorem}[Uniform rank bound]\label{rank_corrVal_le}
  \lean{ErgodicTheory.OperatorEntropy.CNT.rank_corrVal_le}\leanok
  \uses{corrVal_eq_conjTranspose_mul_self, gramVec}
  The correlation density matrix of an \(n\)-fold refinement has rank at most \(d^{2}\),
  \emph{uniformly in \(n\)}:
  \[
    \operatorname{rank}\bigl(\mathrm{corrMatrix}\,\Phi\,\rho\,X\,n\bigr) \;\le\; d^{2}.
  \]
\end{theorem}

n33898.content:
\begin{theorem}[Uniform entropy bound]\label{vonNeumannEntropy_corrMatrix_le_log}
  \lean{ErgodicTheory.OperatorEntropy.CNT.vonNeumannEntropy_corrMatrix_le_log}\leanok
  \uses{rank_corrVal_le}
  At every resolution \(n\), the von Neumann entropy of the correlation matrix is bounded by
  \(\log(d^{2})\), a constant independent of \(n\):
  \[
    S\bigl(\mathrm{corrMatrix}\,\Phi\,\rho\,X\,n\bigr) \;\le\; \log\bigl(d^{2}\bigr).
  \]
\end{theorem}

n33900.content:
\begin{theorem}[The entropy rate vanishes for every partition]\label{cntEntropyPartition_eq_zero}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntEntropyPartition_eq_zero}\leanok
  \uses{vonNeumannEntropy_corrMatrix_le_log, cntDynamicalEntropy}
  For every operational partition \(X\), the CNT partition entropy is \(0\):
  \(h_\Phi(\rho,X) = \inf_{n\ge 1}S(\mathrm{corrMatrix}\,n)/n = 0\).
\end{theorem}

n33902.content:
\begin{theorem}[The \(\inf\)-rate is a genuine limit]\label{tendsto_cntEntropySeq_div}
  \lean{ErgodicTheory.OperatorEntropy.CNT.tendsto_cntEntropySeq_div}\leanok
  \uses{cntEntropyPartition_eq_zero}
  For every operational partition, the entropy rate converges to the partition entropy,
  \(S(\mathrm{corrMatrix}\,n)/n\to h_\Phi(\rho,X)\); the \(\inf\)-definition captures a true limit
  here because \(0\le S(\mathrm{corrMatrix}\,n)/n\le\log(d^{2})/n\to 0\).
\end{theorem}

n33903.content:
\begin{proof}\leanok
  \uses{cntEntropyPartition_eq_zero, vonNeumannEntropy_corrMatrix_le_log}
  Squeeze between \(0\) and \(\log(d^{2})/n\to 0\); the limit is \(0\), which
  Theorem~\ref{cntEntropyPartition_eq_zero} identifies with \(h_\Phi(\rho,X)\).
\end{proof}

n33904.content:
\begin{theorem}[Finite-dimensional CNT dynamical entropy vanishes]\label{cntDynamicalEntropy_eq_zero}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntDynamicalEntropy_eq_zero}\leanok
  \uses{cntEntropyPartition_eq_zero, cntDynamicalEntropy}
  The full CNT/ALF dynamical entropy of any finite-dimensional dynamics vanishes,
  \(h_\Phi(\rho) = 0\).
\end{theorem}

n33906.content:
\begin{theorem}[Abelian-corner Fekete subadditivity]\label{subadditive_vonNeumannEntropy_corrMatrix_abelian}
  \lean{ErgodicTheory.OperatorEntropy.CNT.subadditive_vonNeumannEntropy_corrMatrix_abelian}\leanok
  \uses{vonNeumannEntropy_corrMatrix_eq_ksEntropySeq}
  On the diagonal corner the correlation-entropy sequence
  \(n\mapsto S\bigl(\mathrm{corrMatrix}\,(\mathrm{adPerm}\,\sigma)\,\rho_\mu\,(\mathrm{projPartition}\,c)\,n\bigr)\)
  is \emph{subadditive}, \(S(m+n)\le S(m) + S(n)\).
\end{theorem}

n33908.content:
\begin{theorem}[Abelian-corner Fekete convergence]\label{tendsto_cntEntropyPartition_abelian}
  \lean{ErgodicTheory.OperatorEntropy.CNT.tendsto_cntEntropyPartition_abelian}\leanok
  \uses{subadditive_vonNeumannEntropy_corrMatrix_abelian, cntEntropyPartition_eq_ksEntropyPartition}
  On the diagonal corner the averaged entropies converge to the per-partition CNT rate,
  \[
    \frac1n\,S\bigl(\mathrm{corrMatrix}\,(\mathrm{adPerm}\,\sigma)\,\rho_\mu\,(\mathrm{projPartition}\,c)\,n\bigr)
      \;\longrightarrow\; h_{\mathrm{adPerm}\,\sigma}(\rho_\mu,\mathrm{projPartition}\,c).
  \]
  The a priori infimum is thus a true limit on the abelian corner.
\end{theorem}

n33910.content:
\begin{definition}[Full abelian-corner CNT entropy]\label{cntDynamicalEntropyAbelianFull}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntDynamicalEntropyAbelianFull}\leanok
  \uses{cntDynamicalEntropy, cntDynamicalEntropyAbelian}
  The \emph{full abelian-corner CNT dynamical entropy} is the supremum of the partition rate over
  \emph{all} operational partitions whose operators are diagonal (soft / POVM partitions of the
  diagonal subalgebra), a wider family than the sharp projection partitions of
  \(\mathrm{cntDynamicalEntropyAbelian}\) (Definition~\ref{cntDynamicalEntropyAbelian}).
\end{definition}

n33911.content:
\begin{theorem}[The abelian sups vanish]\label{cntDynamicalEntropyAbelianFull_eq_zero}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntDynamicalEntropyAbelianFull_eq_zero}\leanok
  \uses{cntDynamicalEntropyAbelianFull, cntEntropyPartition_eq_zero}
  In finite dimension the full diagonal supremum vanishes,
  \(h^{\mathrm{ab,full}}_{\mathrm{adPerm}\,\sigma}(\rho_\mu) = 0\), as does the sharp projection
  supremum \(h^{\mathrm{ab}}_{\mathrm{adPerm}\,\sigma}(\rho_\mu) = 0\)
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntDynamicalEntropyAbelian_eq_zero}.
\end{theorem}

n33912.content:
\begin{proof}\leanok
  \uses{cntEntropyPartition_eq_zero}
  Each diagonal (resp.\ projection) partition already has entropy rate \(0\)
  (Theorem~\ref{cntEntropyPartition_eq_zero}); the diagonal projection partition of the constant cell
  map \(\operatorname{Fin}d\to\operatorname{Fin}1\) witnesses nonemptiness, so each supremum is \(0\).
\end{proof}

n33913.content:
\begin{lemma}[Free monotonicity]\label{cntDynamicalEntropyAbelian_le_full}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntDynamicalEntropyAbelian_le_full}\leanok
  \uses{cntDynamicalEntropyAbelianFull}
  The sharp abelian-corner entropy is dominated by the full diagonal version,
  \(h^{\mathrm{ab}}_{\mathrm{adPerm}\,\sigma}(\rho_\mu)
    \le h^{\mathrm{ab,full}}_{\mathrm{adPerm}\,\sigma}(\rho_\mu)\), since every projection partition
  \(\mathrm{projPartition}\,c\) is diagonal.
\end{lemma}

n33914.content:
\begin{proof}\leanok
  \uses{cntDynamicalEntropyAbelianFull}
  Each term of the projection supremum is a term of the wider diagonal supremum
  (\(\mathrm{projPartition}\,c\) has diagonal operators, \(\texttt{Matrix.isDiag\_diagonal}\)), so the
  smaller sup is \(\le\) the larger.
\end{proof}

n33915.content:
\begin{theorem}[Full abelian corner \(=\) KS entropy]\label{cntDynamicalEntropyAbelianFull_eq_ksEntropy}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntDynamicalEntropyAbelianFull_eq_ksEntropy}\leanok
  \uses{cntDynamicalEntropyAbelianFull_eq_zero, cntDynamicalEntropyAbelian_eq_ksEntropy}
  For a \(\sigma\)-invariant state with every mass positive, the full diagonal CNT dynamical entropy
  equals the classical Kolmogorov--Sinai entropy of the permutation system,
  \(h^{\mathrm{ab,full}}_{\mathrm{adPerm}\,\sigma}(\rho_\mu) = h_\mu(\sigma)\). Both sides are \(0\).
\end{theorem}

n33916.content:
\begin{proof}\leanok
  \uses{cntDynamicalEntropyAbelianFull_eq_zero, cntDynamicalEntropyAbelian_eq_ksEntropy}
  The full diagonal sup is \(0\) (Theorem~\ref{cntDynamicalEntropyAbelianFull_eq_zero}); the sharp
  abelian sup is both \(0\) and equal to \(h_\mu(\sigma)\) by the corner equality
  (Theorem~\ref{cntDynamicalEntropyAbelian_eq_ksEntropy}), so \(h_\mu(\sigma) = 0\) and the two match.
\end{proof}

n33918.content:
\begin{proof}\leanok
  \uses{cntDynamicalEntropy_eq_zero, cntDynamicalEntropyAbelian_eq_ksEntropy}
  The corner equality (Theorem~\ref{cntDynamicalEntropyAbelian_eq_ksEntropy}) with the abelian
  vanishing shows \(h_\mu(\sigma) = 0\), and the finite-dimensional vanishing
  (Theorem~\ref{cntDynamicalEntropy_eq_zero}) shows \(h_{\mathrm{adPerm}\,\sigma}(\rho_\mu) = 0\);
  the two zeroes coincide.
\end{proof}

n33919.content:
\begin{lemma}[Resolution \(1\): zero entropy]\label{entropy_corrMatrix_one_eq_zero}
  \lean{ErgodicTheory.OperatorEntropy.CNT.entropy_corrMatrix_one_eq_zero}\leanok
  For the pure state \(\rho\), the length-\(1\) correlation matrix is the classical pure state
  \(\operatorname{diag}(1,0)\), so \(S(\rho[X^{(1)}]) = 0\).
\end{lemma}

n33921.content:
\begin{lemma}[Resolution \(2\): positive entropy]\label{entropy_corrMatrix_two_pos}
  \lean{ErgodicTheory.OperatorEntropy.CNT.entropy_corrMatrix_two_pos}\leanok
  \uses{vonNeumannEntropy_pos_of_sq_ne}
  For the same pure state, the length-\(2\) correlation matrix is \emph{not} idempotent (its
  diagonal \(w_{00}\)-entry violates \(M^{2} = M\): the computation yields \(3/8\ne 1/2\)), hence
  \(S(\rho[X^{(2)}]) > 0\).
\end{lemma}

n33924.content:
\begin{proof}\leanok
  \uses{entropy_corrMatrix_one_eq_zero, entropy_corrMatrix_two_pos}
  If the sequence were subadditive, the instance \(u_2\le u_1 + u_1\) would force
  \(S(\rho[X^{(2)}])\le 2\,S(\rho[X^{(1)}]) = 0\) by Lemma~\ref{entropy_corrMatrix_one_eq_zero},
  contradicting \(S(\rho[X^{(2)}]) > 0\) (Lemma~\ref{entropy_corrMatrix_two_pos}).
\end{proof}

n33925.content:
\begin{lemma}[Zero entropy of an idempotent state]\label{vonNeumannEntropy_eq_zero_of_sq_eq}
  \lean{ErgodicTheory.OperatorEntropy.vonNeumannEntropy_eq_zero_of_sq_eq}\leanok
  \uses{vonNeumannEntropy}
  If a density matrix is a projection (\(\rho^2 = \rho\)) then \(S(\rho) = 0\): transporting to the
  eigenbasis forces every eigenvalue into \(\{0,1\}\), on which \(\operatorname{negMulLog}\) vanishes.
  This is the converse of \(\operatorname{vonNeumannEntropy\_pos\_of\_sq\_ne}\).
\end{lemma}

n33926.content:
\begin{lemma}[Relative entropy against the maximally mixed state]\label{relEntropy_maximallyMixed}
  \lean{ErgodicTheory.OperatorEntropy.relEntropy_maximallyMixed}\leanok
  \uses{relEntropy, vonNeumannEntropy}
  \(D(\rho\,\|\,I/d) = \log d - S(\rho)\); the cross term collapses through the doubly-stochastic row
  sum to \(-\log d\cdot\operatorname{Tr}\rho = -\log d\). Unitary invariance of the von Neumann
  entropy (\lean{ErgodicTheory.OperatorEntropy.vonNeumannEntropy_conj}) is proved alongside, via
  \(\operatorname{charpoly\_mul\_comm}\).
\end{lemma}

n33927.content:
\begin{theorem}[Pure-state seal, T2a]\label{quantum_seal_dephase}
  \lean{ErgodicTheory.OperatorEntropy.quantum_seal_dephase}\leanok
  \uses{relEntropy_maximallyMixed, vonNeumannEntropy_eq_zero_of_sq_eq}
  The maximally coherent pure state \(|{+}\rangle\langle{+}|\) dephases to \(I/2\), a strict
  relative-entropy drop of \(S(I/2) - S(|{+}\rangle\langle{+}|) = \log 2 > 0\) against
  \(\operatorname{diagState} s\); consequently no faithful-ancilla Stinespring section recovers it.
\end{theorem}

n33928.content:
\begin{theorem}[Faithful-state seal, T2b]\label{quantum_seal_dephase_faithful}
  \lean{ErgodicTheory.OperatorEntropy.quantum_seal_dephase_faithful}\leanok
  \uses{relEntropy_maximallyMixed}
  The faithful one-parameter family \(\rho_r = \tfrac12\!\left(\begin{smallmatrix}1 & r\\ r &
  1\end{smallmatrix}\right)\) (\(0 < r < 1\), positive definite) dephases to \(I/2\) with a strict
  drop \(\log 2 - h_2\!\big((1+r)/2\big) > 0\), where \(h_2\) is Mathlib's binary entropy (whose
  strict maximum at \(1/2\) supplies the strict inequality); again no faithful-ancilla Stinespring
  section recovers it.
\end{theorem}

n33932.content:
\begin{proof}\leanok
  \uses{vonNeumannEntropy_corrMatrix_le_log}
  Restate the uniform bound \(S \le \log(d^{2})\)
  (Theorem~\ref{vonNeumannEntropy_corrMatrix_le_log}) through \(\log(d^{2}) = 2\log d\)
  (\(\texttt{Real.log\_pow}\), valid also at \(d = 0\) since \(\log 0 = 0\)).
\end{proof}

n33933.content:
\begin{theorem}[The correlation-entropy sequence is bounded]\label{cntEntropySeq_bddAbove}
  \lean{ErgodicTheory.OperatorEntropy.CNT.cntEntropySeq_bddAbove}\leanok
  \uses{cntCumulativeEntropy_le_reservoir, corrMatrix}
  For every partition the sequence
  \(n\mapsto S\bigl(\mathrm{corrMatrix}\,\Phi\,\rho\,X\,n\bigr)\) is bounded above by the fixed
  reservoir \(\log(d^{2})\), uniformly in the step count \(n\). Monotonicity in \(n\) is deliberately
  \emph{not} claimed --- it is unproven in general and forced flat in the saturated regime; only the
  uniform reservoir cap is asserted.
\end{theorem}

n33934.content:
\begin{proof}\leanok
  \uses{vonNeumannEntropy_corrMatrix_le_log}
  The constant \(\log(d^{2})\) is an upper bound of the range by the per-resolution cap
  (Theorem~\ref{vonNeumannEntropy_corrMatrix_le_log}).
\end{proof}

n33937.content:
\begin{definition}[Pauli operational partition]\label{pauliPartition}
  \lean{ErgodicTheory.OperatorEntropy.CNT.pauliPartition}\leanok
  \uses{OperationalPartition}
  The \emph{Pauli operational partition} of \(\operatorname{Matrix}_2(\mathbb{C})\) is the family of four operators
  \((\tfrac12 P_i)_{i<4}\), where \(P_0 = 1\), \(P_1 = X\), \(P_2 = Y\), \(P_3 = Z\) are the Pauli
  matrices. Each \(P_i\) is Hermitian and unitary, so
  \(\sum_i (\tfrac12 P_i)^{\dagger}(\tfrac12 P_i) = \sum_i \tfrac14 P_i^{2} = 4\cdot\tfrac14\cdot 1 = 1\),
  an operational partition of unity of size \(4 = 2^{2}\).
\end{definition}

n33938.content:
\begin{theorem}[Pauli saturation of the correlation matrix at one step]\label{corrMatrix_pauliPartition_one}
  \lean{ErgodicTheory.OperatorEntropy.CNT.corrMatrix_pauliPartition_one}\leanok
  \uses{pauliPartition, corrMatrix}
  For \emph{every} unital \(*\)-endomorphism \(\Phi\) of \(\operatorname{Matrix}_2(\mathbb{C})\), the depth-\(1\)
  correlation matrix of the Pauli partition in the maximally mixed state \(I/2\) is itself the
  maximally mixed state on the \(4\)-element classical index set \((\operatorname{Fin}4)^{\operatorname{Fin}1}\):
  \[
    \mathrm{corrMatrix}\,\Phi\,(I/2)\,\mathrm{pauliPartition}\,1 \;=\; I/4 .
  \]
\end{theorem}

n33939.content:
\begin{proof}\leanok
  \uses{pauliPartition, corrMatrix}
  The depth-\(1\) refinement along a word \(f\) is just the selected operator
  \((\tfrac12 P_{f_0})\). Pauli trace-orthogonality \(\tr(P_i^{\dagger}P_j) = 2\,\delta_{ij}\), scaled
  by the state \(I/2\) and the \((\tfrac12)^{2}\) normalisation, makes the correlation entry
  \(\tr\bigl((I/2)\,(\tfrac12 P_g)^{\dagger}(\tfrac12 P_f)\bigr)\) equal \(\tfrac14\,\delta_{gf}\);
  reading this off on the classical index gives the diagonal \((\tfrac14)\cdot 1\) density matrix.
\end{proof}

n33940.content:
\begin{theorem}[The reservoir cap is tight at \(d = 2\)]\label{vonNeumannEntropy_corrMatrix_pauliPartition_eq}
  \lean{ErgodicTheory.OperatorEntropy.CNT.vonNeumannEntropy_corrMatrix_pauliPartition_eq}\leanok
  \uses{corrMatrix_pauliPartition_one, cntCumulativeEntropy_le_reservoir}
  For every unital \(*\)-endomorphism \(\Phi\) of \(\operatorname{Matrix}_2(\mathbb{C})\), the Pauli partition in the
  maximally mixed state attains the uniform cap at a single step:
  \[
    S\bigl(\mathrm{corrMatrix}\,\Phi\,(I/2)\,\mathrm{pauliPartition}\,1\bigr)
      \;=\; \log(2^{2}) \;=\; 2\,\log 2 .
  \]
\end{theorem}

n33941.content:
\begin{proof}\leanok
  \uses{corrMatrix_pauliPartition_one}
  By Theorem~\ref{corrMatrix_pauliPartition_one} the correlation matrix is maximally mixed on \(4\)
  points, whose von Neumann entropy is \(\log 4 = \log(2^{2})\).
\end{proof}

n33942.content:
\begin{definition}[Growing qubit carrier]\label{Qbits}
  \lean{ErgodicTheory.OperatorEntropy.Qbits}\leanok
  The length-\(n\) qubit block index \(\mathrm{Qbits}\,n\) is defined by recursion,
  \(\mathrm{Qbits}\,0 = \operatorname{Fin}1\) and \(\mathrm{Qbits}\,(n+1) = \operatorname{Fin}2\times\mathrm{Qbits}\,n\); it has
  cardinality \(2^{n}\), so the block algebra is \(\operatorname{Matrix}_{2^{n}}(\mathbb{C})\).
\end{definition}

n33943.content:
\begin{definition}[The \(n\)-fold product state]\label{rhoPow}
  \lean{ErgodicTheory.OperatorEntropy.rhoPow}\leanok
  \uses{Qbits}
  For a single-qubit state \(\rho\), the product state \(\rho^{\otimes n}\) on the length-\(n\) block
  is defined by \(\rho^{\otimes 0} = I/1\) (the unique state on \(\operatorname{Fin}1\), of zero entropy) and
  \(\rho^{\otimes(n+1)} = \rho\otimes\rho^{\otimes n}\).
\end{definition}

n33944.content:
\begin{definition}[Block entropy]\label{blockEntropy}
  \lean{ErgodicTheory.OperatorEntropy.blockEntropy}\leanok
  \uses{rhoPow}
  The \emph{block entropy} of the tower at level \(n\) is the von Neumann entropy of the product
  state, \(\mathrm{blockEntropy}\,\rho\,n = S(\rho^{\otimes n})\).
\end{definition}

n33945.content:
\begin{theorem}[The linear block-entropy law]\label{blockEntropy_eq}
  \lean{ErgodicTheory.OperatorEntropy.blockEntropy_eq}\leanok
  \uses{blockEntropy, rhoPow}
  The block entropy grows exactly linearly in the level:
  \[
    \mathrm{blockEntropy}\,\rho\,n \;=\; n\cdot S(\rho).
  \]
\end{theorem}

n33946.content:
\begin{proof}\leanok
  \uses{blockEntropy, rhoPow}
  Induct on \(n\): the von Neumann entropy is additive under the Kronecker product,
  \(S(\rho\otimes\rho^{\otimes n}) = S(\rho) + S(\rho^{\otimes n})\), and the base block on \(\operatorname{Fin}1\)
  has zero entropy. Summing the single-qubit contribution \(n\) times gives \(n\cdot S(\rho)\).
\end{proof}

n33947.content:
\begin{definition}[Capacity-enlargement embedding]\label{shiftAdjoinQubit}
  \lean{ErgodicTheory.OperatorEntropy.shiftAdjoinQubit}\leanok
  \uses{Qbits}
  The capacity-enlargement step is the embedding
  \(\operatorname{Matrix}_{2^{n}}(\mathbb{C})\hookrightarrow\operatorname{Matrix}_{2^{n+1}}(\mathbb{C})\) adjoining one fresh qubit on the left,
  \(A\mapsto 1\otimes A\). It is unital, multiplicative, and \(*\)-preserving --- a unital
  \(*\)-homomorphism realising the tower inclusion --- and it is injective, since \(1\otimes A\)
  determines \(A\) through the entry identity \((1\otimes A)_{(i,a),(i,b)} = A_{a,b}\).
\end{definition}

n33948.content:
\begin{theorem}[Maximally mixed corollary]\label{blockEntropy_maximallyMixed}
  \lean{ErgodicTheory.OperatorEntropy.blockEntropy_maximallyMixed}\leanok
  \uses{blockEntropy_eq}
  At the maximally mixed single-qubit state \(I/2\) the linear law reads
  \(\mathrm{blockEntropy}\,(I/2)\,n = n\cdot\log 2\), recovering issue \#70's \(n\cdot\log 2\) claim as
  an equality --- the maximal case, where \(S(\rho) = \log 2\) is largest; for a general \(\rho\) the
  honest law is \(n\cdot S(\rho)\le n\cdot\log 2\).
\end{theorem}

n33950.content:
\begin{theorem}[The spatial (per-step) entropy rate]\label{tendsto_blockEntropy_div}
  \lean{ErgodicTheory.OperatorEntropy.tendsto_blockEntropy_div}\leanok
  \uses{blockEntropy_eq}
  The per-step entropy rate converges to the single-qubit entropy,
  \[
    \frac{\mathrm{blockEntropy}\,\rho\,n}{n} \;\longrightarrow\; S(\rho),
  \]
  as an eventually-constant sequence (equal to \(S(\rho)\) for every \(n\ge 1\)).
\end{theorem}

n33951.content:
\begin{proof}\leanok
  \uses{blockEntropy_eq}
  By the linear law (Theorem~\ref{blockEntropy_eq}), for \(n\ge 1\) the ratio is
  \(n\,S(\rho)/n = S(\rho)\); a constant sequence converges to its value.
\end{proof}

n33952.content:
\begin{theorem}[Positive rate on a concrete faithful family]\label{blockEntropy_rhoR_pos}
  \lean{ErgodicTheory.OperatorEntropy.blockEntropy_rhoR_pos}\leanok
  \uses{blockEntropy_eq}
  For the concrete faithful family
  \(\rho_r = \tfrac12\!\left(\begin{smallmatrix}1 & r\\ r & 1\end{smallmatrix}\right)\)
  (\(0 < r < 1\)) every nonempty block carries strictly positive entropy,
  \(\mathrm{blockEntropy}\,\rho_r\,n > 0\) for \(n\ge 1\); its single-qubit entropy is the binary
  entropy \(h_2\!\big((1+r)/2\big) > 0\), so the spatial rate is a \emph{positive} constant --- the
  tower is genuinely alive.
\end{theorem}

n33953.content:
\begin{proof}\leanok
  \uses{blockEntropy_eq}
  By the linear law the block entropy is \(n\cdot S(\rho_r)\); the single-qubit entropy equals the
  binary entropy \(h_2\!\big((1+r)/2\big)\), strictly positive for \(0 < r < 1\), so each nonempty
  block entropy is positive.
\end{proof}

n33954.content:
\begin{definition}[Partial-dephasing channel]\label{dephaseKronId}
  \lean{ErgodicTheory.OperatorEntropy.dephaseKronId}\leanok
  For a block index \(\mathrm{blk}\), the \emph{partial-dephasing channel}
  \(\Delta\otimes\mathrm{id}_{\mathrm{blk}}\) on \(\operatorname{Matrix}_2(\mathbb{C})\otimes\operatorname{Matrix}_{\mathrm{blk}}(\mathbb{C})\)
  dephases the first qubit (killing its coherences) and leaves the block untouched; its Kraus
  operators are \(K_i\otimes 1\) for the qubit-dephasing Kraus operators \(K_i\) (the diagonal
  projections). It factorises on product states, \((\Delta\otimes\mathrm{id})(x\otimes\beta)
  = (\Delta x)\otimes\beta\).
\end{definition}

n33957.content:
\begin{theorem}[No Stinespring recovery, uniform in the block]\label{quantum_seal_dephase_kron_faithful}
  \lean{ErgodicTheory.OperatorEntropy.quantum_seal_dephase_kron_faithful}\leanok
  \uses{relEntropy_strict_drop_dephasing_kron, quantum_seal_dephase_faithful}
  For an \emph{arbitrary} block \(\mathrm{blk}\) (in particular every tower level
  \(\operatorname{Matrix}_{2^{n}}(\mathbb{C})\)) and a faithful block state \(\beta\), no faithful-ancilla Stinespring
  channel on the enlarged system \(\operatorname{Matrix}_2(\mathbb{C})\otimes\operatorname{Matrix}_{\mathrm{blk}}(\mathbb{C})\) inverts the
  partial dephasing on \(\rho_r\otimes\beta\) and \(\operatorname{diagState} s\otimes\beta\)
  simultaneously.
\end{theorem}

n33959.content:
\begin{definition}[Growing quantum world]\label{GrowingQuantumWorld}
  \lean{ErgodicTheory.OperatorEntropy.GrowingQuantumWorld}\leanok
  \uses{blockEntropy_rhoR_pos, tendsto_blockEntropy_div, quantum_seal_dephase_kron_faithful}
  A \emph{growing quantum world} bundles, for one concrete faithful local state \(\rho_r\) and one
  diagonal reference \(\operatorname{diagState} s\), the three faces of the growing-finite tower:
  \begin{enumerate}
    \item \emph{aliveness} --- the single-qubit entropy \(S(\rho_r) > 0\) is positive and the per-step
      spatial rate \(\mathrm{blockEntropy}\,\rho_r\,n / n\) converges to it
      (Theorem~\ref{tendsto_blockEntropy_div});
    \item the \emph{per-stage dephasing seal at the world's own block states} --- at every level \(n\),
      no faithful-ancilla Stinespring recovery inverts the partial dephasing on both
      \(\rho_r\otimes\rho_r^{\otimes n}\) and \(\operatorname{diagState} s\otimes\rho_r^{\otimes n}\),
      the block being the world's own length-\(n\) block \(\rho_r^{\otimes n}\)
      (Theorem~\ref{quantum_seal_dephase_kron_faithful});
    \item a \emph{base-factor non-commutativity certificate} --- the single-qubit dynamics does not
      preserve the canonical MASA and the seal's eigenprojection is off-diagonal
      (Theorem~\ref{qDynamics_seal_no_common_canonical_masa}).
  \end{enumerate}
\end{definition}

n33960.content:
\begin{theorem}[A growing quantum world exists]\label{growingQuantumWorld_exists}
  \lean{ErgodicTheory.OperatorEntropy.growingQuantumWorld_exists}\leanok
  \uses{GrowingQuantumWorld, blockEntropy_rhoR_pos, tendsto_blockEntropy_div, quantum_seal_dephase_kron_faithful, qDynamics_seal_no_common_canonical_masa}
  A concrete alive-and-sealed growing quantum world exists. Take the balanced faithful local state
  \(\rho_{1/2}\) and the balanced diagonal reference \(\operatorname{diagState}(1/2)\): aliveness holds
  because \(h_2(3/4) > 0\), the per-stage seal is
  Theorem~\ref{quantum_seal_dephase_kron_faithful} instantiated at the world's own block state
  \(\rho_{1/2}^{\otimes n}\) (positive definite), and the base-factor certificate is
  Theorem~\ref{qDynamics_seal_no_common_canonical_masa}.
\end{theorem}

n33964.content:
\begin{lemma}[The inclusion is injective]\label{appendQubit_injective}
  \lean{ErgodicTheory.OperatorEntropy.appendQubit_injective}\leanok
  \uses{appendQubit}
  The far-end inclusion is injective: \(x\otimes 1\) (reindexed) determines \(x\) through the entry
  identity \((\mathrm{appendQubit}\,x)_{(0,a),(0,b)} = x_{a,b}\).
\end{lemma}

n33965.content:
\begin{proof}\leanok
  \uses{appendQubit}
  Read off the \((0,a),(0,b)\) entry of \(x\otimes 1\): the identity factor contributes
  \(1_{0,0}=1\), leaving \(x_{a,b}\). Two inclusions with equal images therefore have equal entries.
\end{proof}

n33967.content:
\begin{proof}\leanok
  \uses{appendQubit, shiftAdjoinQubit}
  Both sides realise the same entrywise triple Kronecker product \(1\otimes M\otimes 1\): the shift
  amplifies on the left and the inclusion on the right, and these two amplifications act on disjoint
  index factors, so their composites agree slot by slot.
\end{proof}

n33968.content:
\begin{lemma}[The tracial state is closed under the tensor step]\label{kron_maximallyMixed}
  \lean{ErgodicTheory.OperatorEntropy.kron_maximallyMixed}\leanok
  The maximally mixed state is closed under the Kronecker product,
  \(\mathrm{mm}\otimes\mathrm{mm}=\mathrm{mm}\): concretely
  \((a^{-1}\cdot 1)\otimes(b^{-1}\cdot 1)=(a\,b)^{-1}\cdot 1\) with \(a,b\) the factor cardinalities.
\end{lemma}

n33970.content:
\begin{theorem}[The tracial state is a tower fixed point]\label{rhoPow_maximallyMixed}
  \lean{ErgodicTheory.OperatorEntropy.rhoPow_maximallyMixed}\leanok
  \uses{kron_maximallyMixed, rhoPow}
  The \(n\)-fold product of the maximally mixed single-qubit state is the maximally mixed state on the
  whole length-\(n\) block, \(\mathrm{rhoPow}\,\mathrm{mm}\,n=\mathrm{mm}\): the tracial state is a
  fixed point of the tower construction.
\end{theorem}

n33971.content:
\begin{proof}\leanok
  \uses{kron_maximallyMixed, rhoPow}
  Induct on \(n\): the tensor step (Definition~\ref{rhoPow}) tensors a fresh maximally mixed qubit onto
  the inductive block, and Lemma~\ref{kron_maximallyMixed} collapses \(\mathrm{mm}\otimes\mathrm{mm}\)
  back to \(\mathrm{mm}\); the base level on \(\operatorname{Fin}1\) is maximally mixed trivially.
\end{proof}

n33973.content:
\begin{proof}\leanok
  \uses{rhoPow, shiftAdjoinQubit}
  The product state factors as \(\rho\otimes(\mathrm{rhoPow}\,\rho\,n)\) and the observable as
  \(1\otimes x\); the Kronecker product multiplies factorwise and the trace factorises, so the fresh
  qubit contributes \(\tr(\rho\cdot 1)=\tr\rho=1\), leaving \(\tr((\mathrm{rhoPow}\,\rho\,n)\cdot x)\).
\end{proof}

n33975.content:
\begin{proof}\leanok
  \uses{appendQubit}
  The trace of \(x\otimes 1\) is \(2\,\tr x\) (the fresh far-end factor contributes \(\tr 1=2\)), and
  the maximally mixed normalizations differ by exactly the factor \(2 = 2^{n+1}/2^{n}\); the two
  cancel, leaving the level-\(n\) tracial pairing.
\end{proof}

n33976.content:
\begin{definition}[The iterated shift]\label{shiftIter}
  \lean{ErgodicTheory.OperatorEntropy.shiftIter}\leanok
  \uses{shiftAdjoinQubit}
  The \emph{\(k\)-fold shift} \(A_n\hookrightarrow A_{n+k}\) iterates the capacity-enlargement
  embedding \(\mathrm{shiftAdjoinQubit}\) (\(A\mapsto 1\otimes A\)) \(k\) times, by the recursion
  \(\mathrm{shiftIter}\,0=\mathrm{id}\) and
  \(\mathrm{shiftIter}\,(k+1)=\mathrm{shiftAdjoinQubit}\circ\mathrm{shiftIter}\,k\). It is a unital
  \(*\)-homomorphism and is injective.
\end{definition}

n33978.content:
\begin{proof}\leanok
  \uses{shiftIter, rhoPow_shiftAdjoinQubit_pairing}
  Induct on \(k\): each shift step peels off one application of
  Theorem~\ref{rhoPow_shiftAdjoinQubit_pairing}, lowering the level by one at unchanged value, and the
  inductive hypothesis carries the level-\(n+k\) pairing down to the level-\(n\) marginal.
\end{proof}

n33979.content:
\begin{definition}[The temporal window entropy]\label{windowEntropy}
  \lean{ErgodicTheory.OperatorEntropy.windowEntropy}\leanok
  \uses{blockEntropy}
  The \emph{window entropy} \(\mathrm{windowEntropy}\,\rho\,k\) is the von Neumann entropy of the
  length-\(k\) window of the chain, generated by the first \(k\) sites. Numerically it equals the
  block entropy of \S\ref{sec:growing-tower} (\(\mathrm{windowEntropy}\,\rho\,k=\mathrm{blockEntropy}\,
  \rho\,k\)); the temporal content is the \emph{reading} --- the window of the shift filtration on the
  fixed, shift-invariant state hierarchy (Theorem~\ref{shiftIter_pairing}) --- not the value.
\end{definition}

n33980.content:
\begin{theorem}[The tracial window entropy]\label{windowEntropy_tracial}
  \lean{ErgodicTheory.OperatorEntropy.windowEntropy_tracial}\leanok
  \uses{windowEntropy, blockEntropy_maximallyMixed}
  At the tracial (maximally mixed) state the length-\(k\) window carries entropy
  \(\mathrm{windowEntropy}\,\mathrm{mm}\,k = k\cdot\log 2\).
\end{theorem}

n33981.content:
\begin{proof}\leanok
  \uses{windowEntropy, blockEntropy_maximallyMixed}
  The window entropy is definitionally the block entropy (Definition~\ref{windowEntropy}), which at the
  maximally mixed single-qubit state equals \(k\cdot\log 2\) by the linear block-entropy law
  (Theorem~\ref{blockEntropy_maximallyMixed}).
\end{proof}

n33982.content:
\begin{theorem}[The temporal entropy rate is \(\log 2\)]\label{tendsto_windowEntropy_div_tracial}
  \lean{ErgodicTheory.OperatorEntropy.tendsto_windowEntropy_div_tracial}\leanok
  \uses{windowEntropy_tracial}
  The per-window rate \(\mathrm{windowEntropy}\,\mathrm{mm}\,k / k\) is the constant \(\log 2\) for
  every \(k\ge 1\), hence converges to \(\log 2\):
  \[
    \frac{\mathrm{windowEntropy}\,\mathrm{mm}\,k}{k} \;\longrightarrow\; \log 2.
  \]
  This is the site-window entropy rate of the quantum Bernoulli shift at the tracial state.
\end{theorem}

n33983.content:
\begin{proof}\leanok
  \uses{windowEntropy_tracial}
  By Theorem~\ref{windowEntropy_tracial} the numerator is \(k\cdot\log 2\), so for \(k\ge 1\) the ratio
  is the constant \(\log 2\); a constant sequence converges to its value.
\end{proof}

n33986.content:
\begin{theorem}[The chain seal holds at every level]\label{chain_seal_dephase_faithful}
  \lean{ErgodicTheory.OperatorEntropy.chain_seal_dephase_faithful}\leanok
  \uses{ChainSealed, quantum_seal_dephase_kron_faithful}
  For all faithful parameters \(0<r,s<1\), the chain-seal predicate holds:
  \(\mathrm{ChainSealed}\,r\,s\). Dephasing site \(0\) of the chain at the tracial block admits no
  faithful-ancilla Stinespring recovery, at every level \(n\).
\end{theorem}

n33988.content:
\begin{definition}[The modular automorphism]\label{modAut}
  \lean{ErgodicTheory.OperatorEntropy.modAut}\leanok
  For a faithful (positive-definite) density matrix \(\rho\), the \emph{modular automorphism}
  \(\sigma_t(a)=\rho^{it}\,a\,\rho^{-it}\) is built from the unitary power \(\rho^{it}\) of the
  Tomita--Takesaki / Petz-equality infrastructure. It is the finite-dimensional shadow of the
  type-III modular flow of the qubit chain.
\end{definition}

n33990.content:
\begin{proof}\leanok
  \uses{modAut}
  Expand \(\sigma_s(\sigma_t(a))=\rho^{is}\rho^{it}\,a\,\rho^{-it}\rho^{-is}\); the unitary powers add,
  \(\rho^{is}\rho^{it}=\rho^{i(s+t)}\) and \(\rho^{-it}\rho^{-is}=\rho^{-i(s+t)}\), giving
  \(\sigma_{s+t}(a)\).
\end{proof}

n33995.content:
\begin{proof}\leanok
  \uses{modAut, shiftAdjoinQubit}
  The unitary power of a Kronecker product factorises, \((\rho\otimes\rho^{\otimes n})^{it}
  =\rho^{it}\otimes(\rho^{\otimes n})^{it}\); conjugating \(1\otimes a\) by it, the first-factor
  \(\rho^{it}\) cancels against \(\rho^{-it}\) around the identity block, leaving
  \(1\otimes\bigl((\rho^{\otimes n})^{it}\,a\,(\rho^{\otimes n})^{-it}\bigr)\).
\end{proof}

n33997.content:
\begin{proof}\leanok
  \uses{modAut}
  The maximally mixed state is a scalar multiple of the identity, \(\rho=c\cdot 1\), so its unitary
  power \(\rho^{it}\) is again a scalar (a constant diagonal), hence central; it commutes past \(a\),
  and \(\rho^{it}\rho^{-it}=1\) leaves \(a\).
\end{proof}

n33998.content:
\begin{theorem}[Intrinsic-clock dichotomy: the non-tracial half]\label{modAut_diagState_ne_id}
  \lean{ErgodicTheory.OperatorEntropy.modAut_diagState_ne_id}\leanok
  \uses{modAut}
  A faithful non-tracial (Powers-type) product state \(\operatorname{diagState} s\)
  (\(0<s<1\), \(\rho=\operatorname{diag}((1+s)/2,(1-s)/2)\)) has a \emph{nontrivial} modular flow: the
  modular group is not the trivial action. Concretely, at
  \(t_0=\pi/\log\bigl((1+s)/(1-s)\bigr)\) the flow sends the off-diagonal unit \(E_{01}\) to
  \(-E_{01}\).
\end{theorem}

n34000.content:
\begin{definition}[The quantum Bernoulli shift, directed-local representation]\label{QuantumBernoulliShift}
  \lean{ErgodicTheory.OperatorEntropy.QuantumBernoulliShift}\leanok
  \uses{shiftAdjoinQubit_appendQubit, appendQubit_maximallyMixed_pairing, rhoPow_shiftAdjoinQubit_pairing, tendsto_windowEntropy_div_tracial, chain_seal_dephase_faithful, modAut_maximallyMixed_eq_id}
  A \emph{quantum Bernoulli shift} bundles the fixed hierarchy of finite marginals of the one-sided
  qubit chain into one certificate:
  \begin{enumerate}
    \item the \emph{directed system} --- the inclusion \(\mathrm{appendQubit}\) and the shift
      \(\mathrm{shiftAdjoinQubit}\) commute (Theorem~\ref{shiftAdjoinQubit_appendQubit});
    \item the \emph{inclusion- and shift-compatibility of the tracial state}
      (Theorems~\ref{appendQubit_maximallyMixed_pairing} and
      \ref{rhoPow_shiftAdjoinQubit_pairing});
    \item the \emph{temporal entropy rate} \(\log 2\) along the shift-window filtration
      (Theorem~\ref{tendsto_windowEntropy_div_tracial});
    \item the \emph{per-stage dephasing seal at the tracial blocks}, for some faithful parameters
      \(r,s\) (Definition~\ref{ChainSealed}, Theorem~\ref{chain_seal_dephase_faithful});
    \item the \emph{trivial tracial modular clock} at every level
      (Theorem~\ref{modAut_maximallyMixed_eq_id}).
  \end{enumerate}
  The maps are definitionally the fixed \(\mathrm{appendQubit}\) / \(\mathrm{shiftAdjoinQubit}\), so
  only their laws are recorded.
\end{definition}

n34001.content:
\begin{theorem}[A quantum Bernoulli shift exists]\label{quantumBernoulliShift_exists}
  \lean{ErgodicTheory.OperatorEntropy.quantumBernoulliShift_exists}\leanok
  \uses{QuantumBernoulliShift, shiftAdjoinQubit_appendQubit, appendQubit_maximallyMixed_pairing, rhoPow_shiftAdjoinQubit_pairing, tendsto_windowEntropy_div_tracial, chain_seal_dephase_faithful, modAut_maximallyMixed_eq_id}
  A concrete quantum Bernoulli shift exists. The witness assembles the already-proved theorems: the
  inclusion/shift commutation, the tracial inclusion- and shift-compatibility, the temporal rate
  \(\log 2\), the per-stage seal at the balanced parameters \(r=s=1/2\), and the trivial tracial
  clock.
\end{theorem}

n34005.content:
\begin{lemma}[Binary intersection of analytic sets is analytic]\label{thm:dst-inter}
  \lean{MeasureTheory.AnalyticSet.inter'}\leanok
  In a Hausdorff space, if \(s\) and \(t\) are analytic then so is \(s\cap t\).
\end{lemma}

n34007.content:
\begin{lemma}[Binary union of analytic sets is analytic]\label{thm:dst-union}
  \lean{MeasureTheory.AnalyticSet.union'}\leanok
  If \(s\) and \(t\) are analytic then so is \(s\cup t\).
\end{lemma}

n34009.content:
\begin{lemma}[Product of analytic sets is analytic]\label{thm:dst-prod}
  \lean{MeasureTheory.AnalyticSet.prod'}\leanok
  If \(s\subseteq X\) and \(t\subseteq Y\) are analytic then \(s\times t\subseteq X\times Y\) is
  analytic.
\end{lemma}

n34011.content:
\begin{theorem}[Analytic sets are universally measurable]\label{thm:dst-nullmeas}
  \lean{MeasureTheory.AnalyticSet.nullMeasurableSet}\leanok
  Every analytic set in a standard Borel space is \texttt{NullMeasurableSet} for every s-finite
  measure.
\end{theorem}

n34013.content:
\begin{definition}[Borel-separated family]\label{thm:dst-sepfam}
  \lean{ErgodicTheory.SepFam}\leanok
  A countable family \(E:\mathbb{N}\to\mathcal P(X)\) is \emph{Borel separated} (\texttt{SepFam}) if there
  are measurable supersets \(B_n\supseteq E_n\) with empty intersection
  \(\bigcap_n B_n=\emptyset\) (Srivastava's terminology after 4.6.1).
\end{definition}

n34014.content:
\begin{lemma}[The single-entry split, Lemma 4.6.2]\label{thm:dst-sepfam-split}
  \lean{ErgodicTheory.sepFam_of_forall_update}\leanok
  \uses{thm:dst-sepfam}
  Fix a position \(j\) and a countable decomposition \(E_j\subseteq\bigcup_m G_m\). If every
  refinement \(\mathrm{update}\,E\,j\,(G_m)\) (replacing the \(j\)-th entry by \(G_m\)) is Borel
  separated, then so is \(E\). Its contrapositive existential form
  \lean{ErgodicTheory.exists_not_sepFam_update}
  states: if \(E\) is \emph{not} separated then some refinement \(\mathrm{update}\,E\,j\,(G_m)\) is
  not separated either.
\end{lemma}

n34016.content:
\begin{lemma}[One stage of the Mokobodzki recursion, inductive Lemma 4.6.2]\label{thm:dst-stage-step}
  \lean{ErgodicTheory.stage_step}\leanok
  \uses{thm:dst-sepfam-split}
  Applied to images \(A_n=\mathrm{range}\,f_n\) of continuous maps \(f_n:(\mathbb{N}\to\mathbb{N})\to X\) from Baire
  space, consider the stage-\(k\) family
  \lean{ErgodicTheory.famE}
  \(\mathrm{famE}\,f\,\sigma\,k=\bigl(f_n[\mathrm{cylinder}(\sigma_n,k-n)]\bigr)_n\) of
  cylinder images around centres \(\sigma_n\). If \(\mathrm{famE}\,f\,\sigma\,k\) is not Borel
  separated, there are refined centres \(\sigma'\), each within the length-\((k-n)\) cylinder of
  \(\sigma_n\), for which \(\mathrm{famE}\,f\,\sigma'\,(k+1)\) is still not separated.
\end{lemma}

n34017.content:
\begin{proof}\leanok
  \uses{thm:dst-sepfam-split}
  Extend the entries one coordinate at a time along the mixed-length intermediate family
  \lean{ErgodicTheory.famMix}
  \(\mathrm{famMix}\), by an inner induction over the position \(j\le k+1\): decompose the
  \(j\)-th cylinder into the one-longer cylinders \(\bigcup_m\mathrm{cylinder}(\mathrm{update}\,
  \sigma'_j\,(k-j)\,m)\), and invoke the single-entry split
  (\Cref{thm:dst-sepfam-split}) to pick a coordinate value \(m_0\) preserving non-separatedness.
  At \(j=k+1\) the mixed family is exactly \(\mathrm{famE}\,f\,\sigma'\,(k+1)\).
\end{proof}

n34018.content:
\begin{theorem}[First separation for ranges, Srivastava 4.6.1]\label{thm:dst-sepfam-ranges}
  \lean{ErgodicTheory.sepFam_ranges}\leanok
  \uses{thm:dst-stage-step}
  If \(f_n:(\mathbb{N}\to\mathbb{N})\to X\) are continuous with \(\bigcap_n\mathrm{range}\,f_n=\emptyset\), then the
  family \((\mathrm{range}\,f_n)\) is Borel separated.
\end{theorem}

n34020.content:
\begin{theorem}[Generalized first separation theorem, Novikov; Srivastava 4.6.1]\label{thm:dst-first-separation}
  \lean{ErgodicTheory.generalized_first_separation}\leanok
  \uses{thm:dst-sepfam-ranges}
  A countable family \((A_n)\) of analytic sets with empty intersection is Borel separated: there
  are measurable \(B_n\supseteq A_n\) with \(\bigcap_n B_n=\emptyset\).
\end{theorem}

n34021.content:
\begin{proof}\leanok
  \uses{thm:dst-sepfam-ranges}
  If some \(A_{n_0}=\emptyset\), take \(B_{n_0}=\emptyset\) and \(B_n=\mathrm{univ}\) otherwise.
  Otherwise every \(A_n\) is a nonempty continuous image of Baire space, \(A_n=\mathrm{range}\,f_n\),
  and \Cref{thm:dst-sepfam-ranges} applies verbatim.
\end{proof}

n34022.content:
\begin{theorem}[Weak reduction principle for coanalytic sets, Srivastava 4.6.5]\label{thm:dst-weak-reduction}
  \lean{ErgodicTheory.weak_reduction_coanalytic}\leanok
  \uses{thm:dst-first-separation, thm:dst-inter}
  If \((S_n)\) is a countable family with analytic complements (the \(S_n\) are coanalytic) and
  Borel union \(\bigcup_n S_n\), there are pairwise-disjoint measurable \(D_n\subseteq S_n\) with
  \(\bigcup_n D_n=\bigcup_n S_n\).
\end{theorem}

n34024.content:
\begin{theorem}[Saint Raymond's theorem, Srivastava 4.7.1]\label{thm:dst-saint-raymond}
  \lean{ErgodicTheory.saintRaymond_closedSections}\leanok
  \uses{thm:dst-weak-reduction, thm:dst-inter, thm:dst-union, thm:dst-prod}
  For disjoint analytic \(A_0,A_1\subseteq X\times Y\) whose \(A_0\)-sections \(\{y\mid(x,y)\in
  A_0\}\) are closed, and a countable basis \((V_n)\) of \(Y\), there are Borel \(B_n\subseteq X\)
  with \(A_1\subseteq\bigcup_n B_n\times V_n\) and \(A_0\cap\bigcup_n B_n\times V_n=\emptyset\).
\end{theorem}

n34026.content:
\begin{theorem}[Kunugui--Novikov theorem, Srivastava 4.7.2]\label{thm:dst-kunugui-novikov}
  \lean{ErgodicTheory.kunuguiNovikov_openSections}\leanok
  \uses{thm:dst-saint-raymond}
  A Borel \(B\subseteq X\times Y\) all of whose sections \(\{y\mid(x,y)\in B\}\) are open is a
  countable union of Borel rectangles \(B=\bigcup_n B_n\times V_n\) over any countable basis
  \((V_n)\) of \(Y\).
\end{theorem}

n34028.content:
\begin{lemma}[Enumerated countable basis]\label{thm:dst-nat-basis}
  \lean{ErgodicTheory.exists_nat_basis}\leanok
  A second-countable space admits an \(\mathbb{N}\)-indexed basis \((V_n)\) (with possible empty entries):
  every point of every open set lies in some \(V_n\) contained in that open set.
\end{lemma}

n34030.content:
\begin{theorem}[Closed sections become closed after a topology refinement, Srivastava 4.7.4]\label{thm:dst-finer-polish}
  \lean{ErgodicTheory.exists_finer_polish_isClosed_of_closedSections}\leanok
  \uses{thm:dst-kunugui-novikov, thm:dst-nat-basis}
  For a Borel \(B\subseteq X\times Y\) with closed sections, there is a finer Polish topology
  \(t'\le t_X\) on \(X\) alone in which \(B\) becomes closed (in the product topology \(t'\times
  t_Y\)).
\end{theorem}

n34032.content:
\begin{theorem}[Compact-section projection, compact fibre space]\label{thm:dst-proj-compact}
  \lean{ErgodicTheory.measurableSet_image_fst_of_isCompact_sections_of_compactSpace}\leanok
  \uses{thm:dst-finer-polish}
  If \(Y\) is compact, a Borel \(B\subseteq X\times Y\) with compact sections has Borel projection
  \(\pi_X(B)\).
\end{theorem}

n34034.content:
\begin{lemma}[Continuous injection into the Hilbert cube]\label{thm:dst-cube}
  \lean{ErgodicTheory.exists_continuous_injective_toCube}\leanok
  Every Polish space \(Y\) admits a continuous injection into the compact Polish cube
  \(\mathbb{N}\to[0,1]\).
\end{lemma}

n34036.content:
\begin{theorem}[Novikov compact-section projection theorem, Srivastava 4.7.11]\label{thm:dst-proj}
  \lean{ErgodicTheory.measurableSet_image_fst_of_isCompact_sections}\leanok
  \uses{thm:dst-proj-compact, thm:dst-cube}
  For Polish \(X,Y\), a Borel \(B\subseteq X\times Y\) all of whose sections are compact has Borel
  projection \(\pi_X(B)\) (Kechris, Thm.~28.8).
\end{theorem}

n34038.content:
\begin{theorem}[Everywhere-Borel distance map via closed balls]\label{thm:dst-infdist}
  \lean{ErgodicTheory.measurable_infDist_of_measurableGraph}\leanok
  \uses{thm:dst-proj}
  Let \(V:X\to\mathrm{Submodule}\,\mathbb{R}\,(\mathbb{R}^d)\) over a standard Borel base \(X\) have a measurable
  graph \(\{(x,v)\mid v\in V x\}\). Then for every \(c\in\mathbb{R}^d\) the map \(x\mapsto\mathrm{infDist}\,
  c\,(V x)\) is \texttt{Measurable}.
\end{theorem}

n34040.content:
\begin{theorem}[Everywhere-measurable orthogonal projector from a measurable graph]\label{thm:dst-projmatrix-converter}
  \lean{ErgodicTheory.measurable_orthProjMatrix_of_measurableGraph}\leanok
  \uses{thm:dst-infdist, orthProjMatrix}
  Over a standard Borel base \(X\), a measurable subspace graph \(\{(x,v)\mid v\in V x\}\) makes the
  orthogonal-projection matrix \(x\mapsto\mathrm{orthProjMatrix}(V x)\) \texttt{Measurable}.
\end{theorem}

n34041.content:
\begin{proof}\leanok
  \uses{thm:dst-infdist, orthProjMatrix}
  Reduce to entrywise measurability (\texttt{Matrix} carries the Pi structure). Each entry is a
  projected-basis coordinate (\texttt{orthProjMatrix\_apply}), which the polarisation identity
  \texttt{starProjection\_apply\_coord} writes as a fixed real combination of the three scalar
  distance maps \(x\mapsto\mathrm{infDist}\,c\,(V x)\) for \(c\) among the two basis vectors and
  their difference. Each is \texttt{Measurable} by \Cref{thm:dst-infdist}, and \texttt{Measurable}
  arithmetic with \texttt{measurable\_pi\_lambda} assembles the full projector.
\end{proof}

n34042.content:
\begin{theorem}[A.e.-measurable projector from a measurable graph]\label{thm:dst-aeconverter}
  \lean{ErgodicTheory.aemeasurable_orthProjMatrix_of_measurableGraph}\leanok
  \uses{thm:dst-nullmeas, orthProjMatrix}
  For any s-finite measure \(\mu\) on a standard Borel base, a measurable subspace graph makes
  \(x\mapsto\mathrm{orthProjMatrix}(V x)\) \texttt{AEMeasurable}.
\end{theorem}

n34045.content:
\begin{proof}\leanok
  \uses{thm:dst-projmatrix-converter}
  The sublevel filtration has a measurable graph
  \lean{ErgodicTheory.measurableSet_graph_lambdaSublevel}
  built from the measurable data \(A,T\) and the everywhere gate, and the general converter
  (\Cref{thm:dst-projmatrix-converter}) turns that graph into the everywhere-measurable projector
  via the Novikov compact-section projection theorem.
\end{proof}

n34046.content:
\begin{theorem}[The a.e.\ sublevel projector, issue \#6]\label{thm:dst-aemeasurable}
  \lean{ErgodicTheory.aemeasurable_orthProjMatrix_lambdaSublevel}\leanok
  \uses{thm:dst-aeconverter, lambdaSublevel, isUltrametricGrowth_lambdaBar}
  For the invertible-MET data (ergodic, measure-preserving \(T\), integrable log-norms), the
  sublevel projector \(x\mapsto\mathrm{orthProjMatrix}(\mathrm{lambdaSublevel}\,A\,T\,x\,c)\) is
  \texttt{AEMeasurable}.
\end{theorem}

n34048.content:
\begin{theorem}[The space of probability measures on a compact metric space is Polish]\label{thm:dst-pspace-polish}
  \lean{ErgodicTheory.MeasureTheory.polishSpace_probabilityMeasure}\leanok
  For a compact metric Borel space \(X\), the space \(P(X) = \mathrm{ProbabilityMeasure}\,X\) with the
  topology of convergence in distribution is Polish (Kechris \S17.E).
\end{theorem}

n34050.content:
\begin{theorem}[Joint continuity of the pushforward]\label{thm:dst-pushforward-cont}
  \lean{MeasureTheory.continuous_probabilityMeasure_map_compact}\leanok
  For a compact metric \(X\) and a metric \(Y\), the pushforward
  \((f,\nu) \mapsto f_*\nu : C(X,Y) \times P(X) \to P(Y)\) is jointly continuous, with
  \(C(X,Y)\) carrying the uniform metric and \(P(X)\) the topology of convergence in distribution.
\end{theorem}

n34053.content:
\begin{theorem}[The section relation is closed]\label{thm:dst-sectionrel-closed}
  \lean{ErgodicTheory.isClosed_sectionRel}\leanok
  \uses{thm:dst-sectionrel, thm:dst-pushforward-cont}
  \(\{(p,s) \mid \mathrm{SectionRel}\,p\,s\}\) is a closed subset of
  \(\mathrm{Params}\,X \times C(X,X)\).
\end{theorem}

n34055.content:
\begin{theorem}[Section-existence is analytic; sealedness coanalytic]\label{thm:dst-section-analytic}
  \lean{ErgodicTheory.sectionExists_analyticSet}\leanok
  \uses{thm:dst-sectionrel-closed, thm:dst-pspace-polish}
  The set \(\{p \mid \exists s,\ \mathrm{SectionRel}\,p\,s\}\) of parameters admitting some continuous
  section is \emph{analytic} (\(\Sigma^1_1\)): it is the continuous image, under the coordinate
  projection \(\mathrm{Prod.fst}\), of the closed relation of \Cref{thm:dst-sectionrel-closed} inside
  the Polish space \(\mathrm{Params}\,X\). Dually the sealed set \(\{p \mid \mathrm{IsSealed}\,p\}\) is
  \emph{coanalytic} (\(\Pi^1_1\), \texttt{ErgodicTheory.isSealed\_coanalyticSet}). The identity
  parameter certifies non-vacuity (\texttt{ErgodicTheory.sectionExists\_nonempty}).
\end{theorem}

